quests[83081] = { id = 83081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht genug Mineralien", description = "Ich habe nicht damit gerechnet, dass die Opalgrube angegriffen wird! Brinthe bestimmt auch nicht.\n\nFriedensbewahrerin Hektare lässt mich nicht kämpfen, Euch aber vielleicht schon.\n\nIch bleibe hier und kümmere mich um diese Irdenen. Ich habe in Dornogal ein, zwei Kniffe gelernt.\n\nOh, aber... Brinthe brauchte diese Opale wirklich dringend...", sourceObjective = "Sammelt 6 Irdenen-Feueropale von der Opalgrube auf der Insel von Dorn.", progress = "Ich bin sicher, ich kann einen Heilumschlag für diesen Irdenen herstellen. Zu schade, dass ich an keine Opale rankomme.", completion = "Feueropale? Ihr habt welche gefunden?\n\nBrinthe wird das gefallen!\n\nDieser Irdene scheint sich auch besser zu fühlen. Alle sind zufrieden!", sourceObjectiveStatus = "unverified-source-field" }
quests[83082] = { id = 83082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Opalfront", description = "Ich bin Stadtwache, keine Soldatin! Aber diese Leute brauchen unsere Hilfe!\n\nDa sind zu viele Neruber, als dass wir sie bekämpfen könnten. Wir können nur diesen Flaschenhals halten und hoffen, dass es die Minenarbeiter bis zu uns schaffen.\n\nDer war zu klein. Aber Ihr seht wie eine Kämpfernatur aus. Helft uns!", sourceObjective = "Tötet Kämpfer der Neruber in der Opalgrube auf der Insel von Dorn.", progress = "Wir tun, was wir können, um den Minenarbeitern bei der Flucht zu helfen.", completion = "Vielen dank, Fremdling. Ihr habt ihnen eine Chance verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[83083] = { id = 83083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vergessener Ort", description = "Es gibt... einen Ort hinter Dornogal, an den ich nicht gehen kann.\n\nUnd nicht nur ich. Irgendetwas, eine Kraft, die wahrscheinlich von einem Titanen ausgeht, hält die Irdenen davon ab, einen kleinen Teil der Insel hinter der Stadt zu erkunden.\n\nDas weckt natürlich meine Neugierde. Aber seit Tausenden von Jahren habe ich mich brav ferngehalten. Es schien der Wille der Titanen zu sein.\n\nDas Gelände sendet ein schwaches Signal aus, wie das von diesem Gerät. Vielleicht ist es im wahrsten Sinne des Wortes \"der Schlüssel\" zu dem, was uns dort erwartet.\n\nWir werden sehen.", sourceObjective = "Trefft Sprecherin Brinthe und Dagran hinter Dornogal auf der Insel von Dorn.", completion = "Ich kann nicht beschreiben, wie sich dieser Ort für mich anfühlt.\n\nEr ist... bedrückend. Ich kann nicht denken.\n\nDer Drang, umzukehren, ist... stark.", sourceObjectiveStatus = "unverified-source-field" }
quests[83084] = { id = 83084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alten Befehle", description = "Vor langer Zeit gab es einmal Pläne, einen Tunnel durch den Berg nach Dornogal zu bauen.\n\nBevor die Grabungen beginnen konnten... verließen alle plötzlich das Gebiet.\n\nEs gibt keine Aufzeichnungen darüber, was passiert ist. Nur... eine Abschreckung, nämlich das Feld, das alle Irdenen von dieser Region fernhält.\n\nJeder Teil meiner kognitiven Matrix drängt mich, zu gehen. Aber wir müssen durchhalten.\n\nDas Signal des Geräts zeigt an, dass sich etwas im Inneren des Turms befindet.", sourceObjective = "Untersucht den verlassenen Turm hinter Dornogal.", progress = "Ich bin mir nicht sicher, was Brinthe bedrückt, aber es geht ihr nicht gut, so viel ist klar. Ich habe ihr angeboten, sie zurück in die Stadt zu begleiten, aber sie hat abgelehnt.\n\nIch werde bei ihr bleiben und dafür sorgen, dass es ihr nicht schlechter geht, und auch versuchen, dieses Gerät etwas besser zu verstehen.", completion = "Vergesst, was Ihr im Turm gefunden habt. Habt Ihr das gesehen?! Die sahen aus wie Titanenhüter!\n\nAber... was hat das alles zu bedeuten? Und wer waren sie?", sourceObjectiveStatus = "unverified-source-field" }
quests[83087] = { id = 83087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alte Garde", description = "Dornic... Galan... Ich habe diese Namen im Proszenium gehört!\n\nAber wer hat da gesprochen? Sie waren nicht glücklich mit Galan. All diese irdenen Körper...\n\nUmfunktioniert... wie umprogrammiert? Um was zu schützen?\n \nLasst uns dem anderen Signal nachgehen. Sieht aus, als würde es in die Berge führen.\n\nIch bleibe mit Brinthe hier und untersuche den Turm weiter. Ihr nehmt das Gerät.", sourceObjective = "Folgt dem Signal und seht die zweite Erinnerung.", progress = "Ich werde hier bei Brinthe bleiben. Ich will nicht, dass ihr was zustößt.", completion = "Ihr habt noch eine Erinnerung gesehen? Und sie hat Euch angegriffen?\n\nDas ist beeindruckend... Ich meine, ich bin so froh, dass es Euch gut geht.\n\nWährend wir das Signal verfolgt haben, konnte ich weitere Notizen finden. Ich habe sie für Euch zusammengestellt. Es geht um Dornic und Galan.\n\nSo wissen wir wahrscheinlich zumindest, wo Galan gelandet ist... begraben unter Tonnen von Stein. Aber was hat sie bewacht?\n\nWas war so wichtig, dass sie dazu benutzt wurde, es für Tausende von Jahren zu beschützen?\n\nArgh! Wir haben mehr Fragen als Antworten. Das gefällt mir gar nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[83088] = { id = 83088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ätzende Sammlung", description = "Boxknochel ist mein Boss... und Mentor. Der beste Schleimtaucher aller Zeiten! Bis jetzt...\n\nEs liegt nicht an ihm... Schleimtauchen ist einfach nicht mehr das, was es einmal war! Die Schleimlinge sind mit der Zeit immer giftiger geworden.\n\nEs ist schon so schlimm, dass ich glaube, dass wir alle lieber Augenschutz tragen sollten... nicht nur ich. Aber der alte Knochel ist traditionsverbunden. Es wird mehr als ein paar rote Augen brauchen, um ihn zu überzeugen.\n\nUnd da kommt Ihr ins Spiel. Wenn Ihr ein paar Rückstandsproben von den besonders fiesen Schleimen sammelt, kann ich den alten Knochel vielleicht doch überzeugen.", sourceObjective = "Sammelt 6 stechende Rückstände von ätzendem Bergungsgut in den Bottichwerken.", progress = "Habt Ihr genug Rückstände vom schleimigen Bergungsgut gesammelt?\n\nNehmt das richtig fiese Zeug. Ihr wisst schon, das Zeug, das an einem kleben bleibt und außerdem die Haut schmelzen lässt?", completion = "Das ist es! Genau das Zeug!\n\nVielleicht hört Knochel diesmal auf mich...", sourceObjectiveStatus = "unverified-source-field" }
quests[83089] = { id = 83089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier herrscht Brillenpflicht!", description = "Mein Mentor Knochel mag hier am lautesten sein, aber er ist sicher nicht der Einzige, der Hilfe braucht.\n\nUnsere gesamte Truppe hört nur auf ihn! Was bedeutet, dass keiner von ihnen angemessene Schutzausrüstung trägt.\n\nNehmt diese Brillen und überzeugt alle, dass sie sie mal ausprobieren sollen. Wenn sie alle ihre Meinung ändern, hört Knochel vielleicht endlich auf mich.", sourceObjective = "Sprecht mit 5 Schleimtauchern in den Bottichwerken.", completion = "<Kazzandra jubelt.>\n\nEndlich! Es sind alle hier. Und sie tragen alle ihre Brillen. Jetzt MUSS Knochel einfach auf mich hören!", sourceObjectiveStatus = "unverified-source-field" }
quests[83091] = { id = 83091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brille auf", description = "Ätzaria? Ist der bekloppt? Niemand hat es je geschafft, dieses Ungetüm zu verarbeiten!\n\nWir müssen Knochel aufhalten, bevor er sich noch verletzt!\n\nÄtzaria lauert am Ende dieses Kanals. Schnappt Euch Eure Brille und folgt mir!", sourceObjective = "Besiegt Ätzaria in den Bottichwerken.", progress = "Ist Ätzaria noch größer geworden? Der Gestank brennt mir von hier bereits die Nasenhaare ab!", completion = "Es geht ihm gut! Vielen, vielen Dank für Eure Hilfe, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[83092] = { id = 83092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feuriges Ende", description = "Als das Magmatransportrohr kaputtging, eilten unsere Arbeiter herunter, um es zu reparieren.\n\nDie Elementare erwischten uns nichtsahnend, kamen hervor und griffen uns mit großen Lavabrocken an.\n\nZum Glück bestehen wir Irdenen aus ziemlich festem Material und ein bisschen Magma bringt uns nicht um. Leider hat sich das abkühlende Magma aber zu steinernen Sarkophagen erhärtet, die unseren Reparaturtrupp jetzt gefangen halten.\n\nZerschmettert ihr Steingefängnis und befreit meine Arbeiter!", sourceObjective = "Befreit eingeschlossene Irdene aus ihrem Steinsarkophag beim Heilsturz-Tor.", completion = "Vielen Dank, Übertägiger. Jetzt, wo unsere Kameraden wieder da sind, können wir uns wieder an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83096] = { id = 83096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in Lorenhall", description = "Da seid Ihr ja! Ich bin Grimla. Willkommen in Lorenhall. Wenn Ihr Euch über die aktuelle Situation informieren wollt, seid Ihr beim richtigen Goblin. Pamsy hat sich für Euch verbürgt, das reicht mir.\n\nIch habe einen Gutschein, den Ihr im Hotel Inkontinental einlösen könnt. Wir fangen dort an.\n\nKommt, wir machen eine Spritztour mit \"Opi\", meinem Hot Rod! Steigt ein, wenn Ihr bereit seid.", sourceObjective = "Geht mit Grimla zum Hotel Inkontinental und erfahrt mehr über Lorenhall.", progress = "Habt Ihr etwas Gutes gehört, während Ihr Euch eingewöhnt habt?", completion = "Das ist also das Hotel Inkontinental. Von hier an geht es bergab.", sourceObjectiveStatus = "unverified-source-field" }
quests[83097] = { id = 83097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glut und Sturm", description = "Die wilden Kreaturen hier weisen erstaunliche Merkmale auf. Ich frage mich, was wohl passiert, wenn ich sie miteinander kombiniere?\n\nHaltet nach abgefüllten Stürmen und brennenden Glutbienenborsten Ausschau. Wenn Ihr mir ein paar Proben bringt, entlohne ich Euch auch großzügig. Oh, und wenn Ihr sie selbst sammelt, dann passt auf, dass Ihr nicht angekokelt werdet. Oder einen Stromschlag bekommt. Oder beides.", sourceObjective = "Sammelt 5 abgefüllte Stürme und 5 brennende Glutbienenborsten und bringt sie zu Ginnad in Dornogal.", progress = "Wer weiß, was passiert, wenn wir diese Materialien miteinander kombinieren!", completion = "Wunderbar! Ich kann kaum erwarten, mich an die Arbeit zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83098] = { id = 83098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knacken und Knistern", description = "Habt Ihr einen Moment Zeit?\n\nIch suche nach einigen besonderen Materialien. Nach etwas Scharfem mit dem gewissen Knistern. Wenn Ihr mir ein paar geschliffene Knochenfragmente und donnernde Häute besorgen könntet, würde ich Euch nur zu gerne dafür entlohnen.", sourceObjective = "Sammelt 5 geschliffene Knochenfragmente und 2 donnernde Häute und bringt sie zu Ginnad in Dornogal.", progress = "Zusammen werden diese Materialien etwas wahrlich Eindrucksvolles ergeben.", completion = "Genau, wonach ich gesucht habe! Ich kann es kaum erwarten, damit zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[83099] = { id = 83099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fusionen und Übernahmen", description = "Als die Neruber meine Metbrauerei angriffen, blieb nichts als ein verkohltes Gerippe zurück. Adelgonn versprach, sie wiederaufzubauen, aber ich wurde ungeduldig und nahm das Angebot von Venture Co. an, bei der \"Restrukturierung\" zu helfen.\n\nAber jetzt ist klar, dass die ihre eigene Agenda hatten. Die verdammten Goblins haben den ganzen Laden übernommen und fahren den Karren an die Wand. Sie haben die Produktion auf ein brandgefährliches Niveau hochgefahren und treiben die Glutbienen und unsere Ausrüstung an ihre Grenzen.\n\nBitte helft mir, die Sache in Ordnung zu bringen, {name}.", sourceObjective = "Besiegt Goldie Barontasch und helft Wenbrandt, die Metbrauerei Glutbräu zurückzugewinnen.", progress = "Wenn ich nur an diese Goblins in meiner Brauerei denke... Oh, das bringt mein Hirn zum Schmelzen. Was mich wiederum an mein Glutbräu erinnert!", completion = "Ich weiß nicht, wie ich Euch alles, was Ihr für die Metbrauerei Glutbräu getan habt, danken kann.\n\nDie Venture Co. zu vertreiben ist keine Kleinigkeit, aber dank Euch konnten wir unsere geliebte Brauerei zurückgewinnen. Jetzt können wir uns wieder daran machen, Glutbräu zu brauen... auf die richtige Weise, wie wir es schon seit Jahrhunderten getan haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[83100] = { id = 83100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzer knacken", description = "Willkommen!\n\nIhr glaubt ja nicht, was wir hier oben alles an Materialien verbrauchen. Und nicht nur von dem seltenen Zeug! Wir können nie genug Düsternischitin kriegen. Wenn Ihr welches findet, dann bringt es zu mir. Ihr sollt dafür auch gut entlohnt werden.", sourceObjective = "Sammelt 20 Düsternischitin und bringt es zu Ginnad in Dornogal.", progress = "Konntet Ihr schon etwas in die Finger kriegen?", completion = "Genau zur rechten Zeit. Unser Vorrat wurde langsam knapp.", sourceObjectiveStatus = "unverified-source-field" }
quests[83101] = { id = 83101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ressourcenhunger" }
quests[83102] = { id = 83102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bismut ist gut", description = "Wisst Ihr, was das Fundament einer guten Bergbauunternehmung ist? Es sind nicht die beeindruckenden seltenen Erze. Es ist das gute alte Bismut.\n\nUnd davon haben wir nicht ansatzweise genug! Egal, wohin Ihr geht, haltet die Augen nach Bismut offen. Bringt mir so viel, wie Ihr könnt.\n\nIhr werdet auch reichlich entlohnt.", sourceObjective = "Sammelt 20 Bismut und bringt es zu Tarib in Dornogal.", progress = "Bismut ist gut! Besonders fürs Geschäft!", completion = "Ihr seid zurück? Vielen Dank. Ihr wisst offensichtlich, wie man eine Spitzhacke schwingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83103] = { id = 83103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aqirit akquirieren", description = "Ihr da!\n\nHabt Ihr schon mal von Aqirit gehört? Wertvoll, vielseitig und nur zu oft von Nerubern umgeben.\n\nIch brauche das Erz, mir egal, wie Ihr es besorgt. Wenn Euch ein Neruber aufhalten will, dann verpasst ihm eine von mir.", sourceObjective = "Sammelt 10 Aqirit und bringt es zu Tarib in Dornogal.", progress = "Also, habt Ihr es schon?", completion = "Aqirit wird immer gern gesehen. Ich leite es an die richtigen Stellen weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[83104] = { id = 83104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenklaue gesucht", description = "Ich habe ein Team zum Abbau von Eisenklauenerz losgeschickt, aber die meinten, sie hätten keines gefunden. Ist das zu fassen? Es ist eine große Klaue, die aus dem Boden ragt, verdammt noch mal!\n\nIch hoffe, Ihr erkennt Eisenklauenerz, wenn Ihr welches seht. Bringt mir welches und Ihr sollt entlohnt werden.", sourceObjective = "Sammelt 10 Eisenklauenerz und bringt es zu Tarib in Dornogal.", progress = "Glaubt mir, es ist nicht zu übersehen.", completion = "Habt Dank. Ich wusste, dass ich mich auf Euch verlassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[83105] = { id = 83105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenklaueneilauftrag", description = "Schön, Euch zu sehen. Ich habe Arbeit für Euch.\n\nDie Schmiede haben gerade auf den letzten Drücker seltene Erze angefordert. Diese kiesfressenden Hammerschwinger! Würde es sie umbringen, mal vorauszuplanen? Egal, ich bin mir sicher, dass Ihr das geregelt kriegt.\n\nSieht aus, als müsstet Ihr etwas Aqirit und Eisenklauenerz beschaffen.", sourceObjective = "Sammelt 5 Aqirit und 5 Eisenklauenerz und bringt alles zu Tarib in Dornogal.", progress = "Habt Ihr alles? Die Schmiede kauen mir schon ein Ohr ab.", completion = "Ausgezeichnete Arbeit. Wir wissen diese Erze wirklich zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83106] = { id = 83106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nullstein, null Kies", description = "Schon mal einen Nullstein gesehen? Nun, das werdet Ihr. Die sind selten, aber wir wissen sie gut zu nutzen. Keine Sorge, ich brauche nur ein paar.\n\nUnd wenn Ihr schon dabei seid, könnt Ihr mir auch gleich etwas Bismut mitbringen. Man kann nie genug Bismut haben.", sourceObjective = "Sammelt 10 Bismut und 2 Nullsteine und bringt sie zu Tarib in Dornogal.", progress = "Hattet Ihr Glück mit den Nullsteinen?", completion = "Hervorragend! Hoffentlich hat es Euch nicht zu viele Probleme bereitet, die aufzutreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[83108] = { id = 83108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carpe Diagnosem", description = "Es ist mir Pflicht und Ehre, jeden Tag diagnostische Daten zu erfassen. Ich ermittle die Leistung und Effizienz der großen Maschinen unseres Steingewölbes. Diese Bürde ist mein.\n\nBeschreibe Komplikation: Nun, da Skardyn das Steingewölbe überrannt haben, komme ich nicht mehr an meine Maschinen!\n\nVorgeschlagene Lösung: Mir ist zu Ohren gekommen, dass Ihr <ein namhafter Held/eine namhafte Heldin> seid. Könntet Ihr heute für mich hineineingehen und die Daten ablesen? Der Zeitpunkt ist kritisch, falls etwas schiefgehen sollte. Erwarte Bestätigung.", sourceObjective = "Erfasst Diagnosedaten von 4 Maschinen im Steingewölbe.", progress = "Es gibt zahlreiche Konsolen, die dabei helfen, die großen Maschinen des Steingewölbes am Laufen zu halten. Die Arbeit hört nicht auf, selbst im Angesicht dieses Wahnsinns.\n\nBitte lest so schnell wie möglich die Daten für mich ab!", completion = "Danke fürs Ablesen. Hoffentlich zeigt die Analyse, dass mit den großen Maschinen alles in Ordnung ist.\n\nBis es für uns sicher ist, ins Steingewölbe zurückzukehren, stecke ich hier fest. Aber wenigstens weiß ich jetzt, wie die Daten heute aussehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83109] = { id = 83109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Grimlaexpress", description = "Nächster Halt: Hintertürpark. Früher hatte dort das Bilgewasserkartell das Sagen, aber Gallywix hatte andere Pläne. Jetzt tun die Düsternisverschmolzenen so, als würde ihnen der Ort gehören, und das Bilgewasserkartell... Nun, sie tun ihr Bestes.\n\nIch bin mir nicht sicher, wer es jetzt leitet, falls es überhaupt jemand tut.", sourceObjective = "Fahrt mit Grimlas Hot Rod zum Hintertürpark.", completion = "Sie schauen zu Gazlowe auf. Vielleicht macht es ihnen ein bisschen Hoffnung, wenn Ihr auftaucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[83110] = { id = 83110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liefert Ausrüstung", description = "Liefert den Goblins des Dampfdruckkartells Sicherheitsausrüstung, damit sie ihre Experimente mit Schwarzblut sicherer durchführen können." }
quests[83113] = { id = 83113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlangt Werkzeuge zurück", description = "Tötet Schwarzblutschleime und sammelt die von den Schleimen absorbierten Werkzeuge ein." }
quests[83114] = { id = 83114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotes Band", description = "Erst war es nur Schwarzblut, jetzt die Astralen?\n\nIch weiß nicht, wie das alles zusammenpasst, aber wir brauchen Hilfe, wenn wir es herausfinden wollen.\n\nOrweyna ist vor einer Weile gegangen, um Alleria zu holen. Wir sollten zum Bahnhof Schmetterzentrale gehen, um zu sehen, ob sie es schon hierher geschafft haben.", sourceObjective = "Findet Alleria am Bahnhof Schmetterzentrale", progress = "Wir hätten es wissen müssen. Diese Typen sehen einen Fremdling ohne Begleitung und versuchen sofort, ihn abzuziehen.\n\nVersucht, sie zu überzeugen, davon abzulassen.", completion = "Jetzt, wo Alleria hier ist, lasst uns der Sache auf den Grund gehen, angefangen bei Noggenfogger.", sourceObjectiveStatus = "unverified-source-field" }
quests[83115] = { id = 83115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Runde", description = "Mir gefällt der Gedanke nicht, dass Noggenfogger etwas damit zu tun hat, aber das können wir nur herausfinden, wenn wir mit ihm reden.\n\nDas Hauptquartier des Dampfdruckkartells ist wahrscheinlich ein guter Ort, um nach ihm zu suchen.\n\nWir werden ihm die Chance geben, es zu erklären. Wenn es ein Missverständnis ist oder er sich nur in Schwierigkeiten gebracht hat, muss ich es wissen.", sourceObjective = "Sprecht mit Marin Noggenfogger bei den Bottichwerken.", progress = "Seht Ihr, wie viele Düsternisverschmolzene es hier gibt?", completion = "<Gazlowe senkt seine Stimme.>\n\nHier wimmelt es von Düsternisverschmolzenen. Noggenfogger wird beobachtet. Ganz genau.", sourceObjectiveStatus = "unverified-source-field" }
quests[83116] = { id = 83116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trankaufruhr", description = "Es ist wirklich toll, Euch und Gazlowe zu sehen! Ich habe gerade darüber nachgedacht, wie gerne ich Euch beide an meinem Geburtstag sehen wollte.\n\nAn einem Tag, an dem ich weder unter Druck noch unter Zwang stehe! Überhaupt nicht.\n\n<Vorsichtig wirft er einen Blick auf die Wachen der Düsternisverschmolzenen, dann flüstert er Euch etwas zu.>\n\nIch erzähle Euch alles, was ich kann, wenn Ihr sie beseitigt.\n\n<Er nickt unauffällig in Richtung seiner Alchemiestation.>", sourceObjective = "Sammelt einige von Noggenfoggers halbluxuriösen Elixieren und benutzt sie, um die 8 stationierten Laborwachen abzulenken.", progress = "Ich werde ein Auge auf Noggenfogger werfen. Ihr schafft das schon.", completion = "Venture und Kaja'mit. Zwei weitere Puzzlestücke.\n\nHoffen wir, dass sie irgendwann zusammenpassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83117] = { id = 83117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Jagd nach einer Spur", description = "Venture hat nicht gerade den Ruf, ein aufrechtes Kartell zu sein. Ihre Loyalität lässt sich billig erkaufen und sie haben keine Skrupel, den Zweck mit den Mitteln zu heiligen.\n\nWir wussten, dass sie mit Gallywix zusammenarbeiten. Wir wussten nur nicht, wie tief sie mit ihm unter einer Decke stecken.\n\nLasst uns die Kaja'mit-Versorgungslinien überprüfen. Wir dürfen keine Zeit verlieren.", sourceObjective = "Trefft Gazlowe vor den Halden.", completion = "Jede Menge Düsternisverschmolzene, aber weniger als beim Dampfdruckkartell. Wahrscheinlich, weil Venture Company regelkonformer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[83118] = { id = 83118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüft die Zeitpläne", description = "Wenn es eine Sache gibt, bei der Venture Ordnung hält, dann ist es der Papierkram. Sie nehmen es sehr genau mit der Aufteilung ihrer Arbeitskräfte und halten den Schichtplan genau ein. Sie sind effizient, das muss ich ihnen lassen.\n\nDa vorne ist einer ihrer Schrottplätze. Dort sollten überall Listen aushängen, auf denen die Mitarbeiter von Venture ihre Arbeitsstunden eintragen und sehen können, was ansteht.\n\nNehmt so viele mit, wie Ihr finden könnt. In der Zwischenzeit sehen wir uns das Venture-Hauptquartier an.", sourceObjective = "Sammelt die Schichtpläne von 3 Mitarbeitern.", progress = "Die Schichtpläne sollten überall ausgehängt sein. Hoffentlich wird das keine sinnlose Verfolgungsjagd.", completion = "<Gazlowe liest die Listen schnell durch, seine Miene wird mürrisch.>\n\nDie gute Nachricht ist, Noggenfogger hat nicht gelogen.\n\nDie schlechte ist... das sind eine MENGE Namen. Da wird alles an die Kaja'Küste in Zuldazar geschickt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83119] = { id = 83119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist einen Versuch wert", description = "Venture Company hat eine ziemlich miese Vorgeschichte, aber nicht alle, die für das Kartell arbeiten, sind böse. Einige von uns versuchen, über die Runden zu kommen.\n\nVielleicht können wir ein paar von ihnen zur Vernunft bringen. Weniger Venture-Arbeiter bedeuten weniger Leute, die Gallywix' Drecksarbeit machen.\n\nVenture Company beschäftigt viele Nichtgoblins, also wird Euch niemand fragen, warum Ihr da seid, solange Ihr eine Uniform tragt. Ich habe eine Ersatzuniform, die Euch wahrscheinlich einigermaßen passt.\n\nSchaut, ob Ihr sie zum Aufhören bringen könnt. Wenn sie einen Kampf anfangen, tut, was Ihr tun müsst.", sourceObjective = "Versucht, 10 unterbezahlte Arbeiter zu überzeugen, bei Venture Co. aufzuhören.", completion = "Das reicht schon.\n\nSelbst ein Goblin weniger, der für Gallywix arbeitet, ist ein Erfolg in meinen Augen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83120] = { id = 83120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raub der Schlüssel", description = "Wenn Ihr zu einem vertraulichen Arbeitsplatz wie der Kaja'Küste wollt, müsst Ihr Euch in Kromes Büro eine Stempelkarte holen.\n\nDer leitende Vorarbeiter Krome ist einer der großen Bosse, die die Aufteilung der Arbeitskräfte der Venture Company organisieren.\n\nFür Renzik sollte es ein Leichtes sein, reinzugehen und die Stempelkarte zu holen, aber Ihr müsst Euch um Krome und seine Wachhyäne kümmern. Wenn wir zur Kaja'Küste wollen, sollten wir vorher nicht zum Kauspielzeug werden, ja?", sourceObjective = "Tötet den leitenden Vorarbeiter Krome.", progress = "Habt Ihr den Weg für Renzik schon frei gemacht, damit er die Stempelkarte holen kann?", completion = "<Gazlowe zieht eine Grimasse, als er die Waffe des Vorarbeiters inspiziert.>\n\nDie Batterie in diesem Ding wird von Schwarzblut gespeist.\n\nIch weiß nicht, wie sie das geschafft haben, ohne dass das Ding explodiert, oder noch schlimmer. Aber die Situation ist jetzt noch viel gefährlicher geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[83121] = { id = 83121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermögensverwaltung", description = "Ich habe einen kurzen Blick in die Mine da vorne geworfen, während Ihr weg wart. Es sieht so aus, als würde die Venture Co. das ganze Kaja'mit abbauen und zum Strand bringen. Es wird dort unten verpackt, aber ich konnte nicht erkennen, wohin es danach gebracht wird.\n\nWir müssen die Versorgung am Ursprung unterbrechen. Kümmert Euch um die Aufseher in der Mine, und ich wette, ihre Arbeiter haben genug Verstand, um hinterherzurennen.", sourceObjective = "Tötet 6 Venturevorsteher in den Glücksmomentminen.", completion = "Gut. Je weniger Leute bei Venture Co. Gallywix gegenüber loyal sind, desto besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[83122] = { id = 83122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Markt zerstören", description = "Als ich dem Bilgewasserkartell die Verantwortung für den Kaja'mit-Abbau in Zuldazar überließ, war es sauber und sicher. Oder zumindest sauberer und sicherer. Wir haben viele Abkommen mit den Zandalari getroffen, um das zu gewährleisten. Gallywix dringt nicht nur in unser Territorium ein, er bedroht auch unser wohl verdientes Ansehen und Vertrauen, weil er zugelassen hat, dass Venture die ganze Operation in den Sand setzt.\n\nSprengt die Kaja'mit-Lager, die Ihr in der Mine findet. Ich will nicht, dass Kaja'mit aus unethischen Quellen in Umlauf gebracht wird, egal, wer es kauft oder verkauft.", sourceObjective = "Zerstört 5 Kaja'mitvorräte in den Glücksmomentminen.", completion = "Wenn das alles erledigt ist, wird Bilgewasser zurückkommen, hier aufräumen und es richtig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83123] = { id = 83123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine fiese Mine", description = "<Bei der Leiche des Venture Co.-Angestellten findet Ihr ein zerknülltes Stück Papier, das in einen Umschlag gestopft ist. Es scheint eine Gehaltsabrechnung von einem Kaja'mit-Depot in der Venture Co.-Gegend von Lorenhall zu sein.\n\nUnter der vollständigen Adresse des Arbeitgebers steht in roter Tinte eine Überschrift.>\n\nGALLYWIXS GEHEIMES KAJA'MIT-LAGER - NUR INTERN, NICHT DRUCKEN\n\n<Eine Notiz von Gallywix ist notdürftig auf die Rückseite der Gehaltsabrechnung geklebt.>", sourceObjective = "Lest die zerknüllte Gehaltsabrechnung und bringt sie zu Gazlowe zurück.", progress = "Was habt Ihr da?", completion = "Damit wäre das beantwortet.\n\nVenture Company wird von einem von Gallywix' geheimen Lagern in Lorenhall bezahlt.\n\nDas heißt, er hortet das ganze Kaja'mit dort. Wofür könnte er so viel brauchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[83124] = { id = 83124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "V.O.G.E.L.-Beobachtung", description = "Ich habe die Teile, die Ihr gesammelt habt, zu einer neuen Maschine zusammengebaut und sie dann wieder in den Roboter eingebaut. Jetzt kann er mit dieser Fernbedienung gesteuert werden. Mit der Fernbedienung können wir auch alles sehen und hören, was der Bot macht.\n\nIch glaube nicht, dass wir durch Töten allein lernen werden, was wir brauchen. Wir müssen Gallywix mit seinen eigenen Waffen schlagen und seine Arbeiter ausspionieren.\n\nWollt Ihr uns die Ehre erweisen, {name}? Ich erkläre es Euch.", sourceObjective = "Steuert den kurzgeschlossenen V.O.G.E.L., um die Aktivitäten der Düsternisverschmolzenen an der Kaja'Küste auszuspionieren.", progress = "Sie werden keinen Verdacht schöpfen.", completion = "Da haben wir das letzte Puzzlestück. Gallywix hat Schwarzblut und Kaja'mit eingesetzt, um diese Waffen herzustellen, und jetzt verwendet er sie, um das Dunkle Herz zu reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[83125] = { id = 83125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preiserhöhung", description = "Noggenfogger hat also nicht gelogen. Die Düsternisverschmolzenen haben das Dampfdruckkartell unter Druck gesetzt, damit sie herausfinden, wie man Kaja'mit mit Schwarzblut versetzen kann. Es sieht so aus, als ob sie es so in die Waffen bekommen haben, ohne sich selbst in die Luft zu jagen oder Schlimmeres anzurichten.\n\nEs steht mehr auf dem Spiel, als ich dachte, und ich habe das Gefühl, dass es noch tiefer geht. Ich muss Noggenfogger in Sicherheit bringen. Renzik und Ihr schaltet den Aufseher aus und trefft uns dann im Dampfdruckkartell wieder.", sourceObjective = "Tötet Aufseher Dritz und trefft Euch dann mit Gazlowe in Lorenhall.", completion = "Verdammt. Noggenfogger ist schwer verletzt.\n\nErst die Düsternisverschmolzenen, jetzt die Astralen. Was könnten sie nur vom Dampfdruckkartell wollen?", sourceObjectiveStatus = "unverified-source-field" }
quests[83126] = { id = 83126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astrale Invasion", description = "Vor wenigen Augenblicken sind diese Astralen aus dem Nichts aufgetaucht. Sie haben Noggenfogger angegriffen und versucht, ihn wegzuschleppen. Ich habe mit den ersten Angreifern kurzen Prozess gemacht, aber sie kommen immer wieder.\n\nJetzt durchsuchen sie alle Gebäude und töten jeden, der sich ihnen in den Weg stellt.\n\nIch weiß nicht, wonach sie suchen, aber wir können nicht zulassen, dass sie dieses Gemetzel fortsetzen.\n\nLasst uns ihnen eine Lektion erteilen.", sourceObjective = "Tötet 12 Astrale in den Bottichwerken.", completion = "Die Astralen haben nicht damit gerechnet, dass sie hier auf Widerstand stoßen. Sie haben sich geirrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83127] = { id = 83127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettlauf mit der Zeit", description = "Wir hatten schon vorher keine Zeit mehr, aber jetzt haben wir WIRKLICH keine Zeit mehr.\n\nDie Astralen werden vor uns im Lagerhaus sein, aber vielleicht schaffen wir es noch vor ihnen zum Dunklen Herzen.\n\nLos!", sourceObjective = "Trefft Gazlowe vor Gallywix' geheimen Lager in den Halden.", completion = "Wenigstens haben die Astralen den Großteil der Düsternisverschmolzenen erledigt. Das ist... gut, wahrscheinlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[83128] = { id = 83128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt unsere Leute raus", description = "Während Alleria nach dem dunklen Herz sucht, müssen wir die Geiseln finden. Hoffen wir, dass es ihnen noch gutgeht.\n\nSie haben ein paar Wegelagerer zurückgelassen, aber wir haben die Besten von SI:7 auf unserer Seite. Wenn Ihr glaubt, dass sich einer von ihnen versteckt, sagt Renzik Bescheid und er wirft eine Rauchbombe. Das wird sie heraustreiben und betäuben, sodass wir den Spieß umdrehen können.", sourceObjective = "Befreit alle Geiseln, die Gallywix im Lager festhält, und tötet 10 astrale Herzsucher.", completion = "Die Geiseln sind in Sicherheit. Gallywix hat auf keines der Kartelle mehr Einfluss.\n\nZeit, die Sache zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[83129] = { id = 83129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Versteck mehr", description = "Die Barrikade wirkt beabsichtigt. Hobart hat gesagt, dass Gallywix in eine Höhle geflohen ist, und ich würde sagen, das hier sieht danach aus.\n\nGallywix muss das Dunkle Herz da drin haben. Helft mir, die Barrikade aufzusprengen und macht Euch bereit für den Kampf.", sourceObjective = "Zerstört die behelfsmäßige Barrikade und folgt dann Gazlowe in den Hortraum, um Gallywix zu stellen.", completion = "<Gazlowe atmet schwer aus und blickt zurück auf den rauchenden Teleporter.>\n\nEs ist vorbei. Lasst uns gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83130] = { id = 83130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurer Sieg", description = "Das war's. Es ist vorbei. Wir sind fertig.\n\nGallywix hat verloren, aber die Astralen haben das Dunkle Herz.\n\nAlleria muss sie aufspüren. Wir müssen nach den anderen in den Bilgewasserapartments sehen und dann weg. In dieser Stadt gibt es nichts mehr für uns.", sourceObjective = "Trefft Gazlowe im Schrottladen in den Bilgewasserapartments.", completion = "<Gazlowe hält die Arme verschränkt und starrt in die Ferne ins Nichts.>", sourceObjectiveStatus = "unverified-source-field" }
quests[83137] = { id = 83137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn eine Gelegenheit hochgeht", description = "Da seid Ihr ja, {name}! Habt Ihr schon die neuesten Nachrichten gehört? An der Chancenspitze in den Schallenden Tiefen ist ein großes Loch in die Bergwand gesprengt worden.\n\nEs wurde von opportunistischen Typen überrannt und nun wimmelt es dort von ihnen. Wir sollten uns schnellstens dorthinbegeben.", sourceObjective = "Untersucht das gesprengte Loch an der Chancenspitze.", completion = "Das ist... eine Mautstelle?\n\nSoll das ein Scherz sein?\n\n<Monte Gazlowe verdreht die Augen und lacht leise.>\n\nIch schätze, man kann mit allem Geld machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83138] = { id = 83138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Tages", description = "Sprinkel und Seehorn geht es gut. Marin und Hobart erholen sich. Wir haben Gallywix nicht aufgehalten, aber zumindest ist das dunkle Herz... nun, es ist nicht in seinen Händen.\n\nWir können also gehen. Hier gibt es für uns nichts mehr zu tun.\n\nErledigt alles, was Ihr in Lorenhall zu erledigen habt. Ich muss diesen verdammten Ort verlassen.", sourceObjective = "Sprecht mit Renzik.", completion = "<Gazlowe wischt sich etwas Aschiges von der Wange. Seine Hand zittert, als er darauf starrt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[83139] = { id = 83139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemischte Nachrichten", description = "Viele dieser Arbeiter sind auf dem Weg zu einem Venture-Lager ganz in der Nähe. Das ist eine gute erste Anlaufstelle für Informationen. Wir werden die Mautgebühr bezahlen. Es ist am besten, wenn wir erst einmal mitspielen.", sourceObjective = "Bezahlt die Maut an der Mautstelle und sammelt dann Informationen aus dem nördlichen Goblinlager.", progress = "Findet heraus, was diese Goblins über die Gegend wissen!", completion = "Vielleicht will derjenige, der die Mauer gesprengt hat, auch hier unsere Aufmerksamkeit. Wir müssen tiefer graben.", sourceObjectiveStatus = "unverified-source-field" }
quests[83140] = { id = 83140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Arbeitsumgebung", description = "Größer und gefährlicher als Chancenspitze? Diese Minen im Süden hören sich wirklich schlimm an, selbst wenn man eine hohe Toleranz für schlechte Arbeitsbedingungen hat. Aber was bauen sie ab? Irgendetwas hier ist viel Geld wert. Wir müssen es uns ansehen.\n\nIch gehe mit Renzik im Verstohlenheitsmodus am großen Lager der Düsternisverschmolzenen vorbei. Lenkt von uns ab, ja? Ich bin sicher, Ihr könnt die Produktion verlangsamen, während Ihr dort seid.", sourceObjective = "Tötet Düsternisverschmolzene, um den Ärger von Gazlowe und Renzik fernzuhalten.", completion = "Alle Augen waren auf Euch gerichtet, sehr gut. Und Ihr habt uns weitere Ressourcen gebracht, oder? Diesen Zirdo? Gut mitgedacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[83141] = { id = 83141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minenermittlungen", description = "Welche \"Reichtümer\" graben sie aus der Erde? Könnte dieses tiefe Graben etwas mit meinen Visionen zu tun haben? Sicherlich würden diese Goblins keinen Wert in etwas wie Schwarzblut sehen.\n\nWir müssen uns das genauer ansehen. Gemeinsam werden wir uns einen Einblick in ihre Machenschaften verschaffen.", sourceObjective = "Untersucht verdächtige Kanister und Kisten mit Orweyna.", completion = "Meine Visionen deuten darauf hin, dass es im Süden noch mehr gibt. Wir sollten bald weiterziehen.\n\nHat der Goblin, den Ihr gefunden habt, weitere Informationen?", sourceObjectiveStatus = "unverified-source-field" }
quests[83142] = { id = 83142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großer Befehl", description = "<Dieses Dokument verlangt, dass jeder, der Informationen darüber hat, wer die Westmauer geöffnet hat, diese Informationen seinem Vorgesetzten mitteilt.\n\nDie Belohnung ist eine Beförderung zur Arbeit in Lorenhall. Es enthält auch ein Versprechen auf Gunst und \"Anerkennung\" von Gallywix.\n\nGazlowe wird davon hören wollen.>", sourceObjective = "Gebt Gazlowe das Kopfgeld von Gallywix.", progress = "Was habt Ihr gefunden?", completion = "Gallywix kontrolliert die Düsternisverschmolzenen direkt und will wissen, wer gegen ihn gearbeitet hat. Wir könnten hier einen Verbündeten haben. Das ist ein wichtiger Hinweis, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[83143] = { id = 83143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute, ehrliche Arbeit", description = "Ihr seid neu hier, stimmt's? Das merke ich an Euren Fragen. Aber keine Sorge, Zirdo ist Euer bester Kumpel!\n\nIch werde Euch eine persönliche Tour geben. Gossenheim, die Stadt der Venture Company, liegt südlich die Straße hinunter. Es wird informativ und interaktiv sein. Eine bessere Erfahrung könnt Ihr Euch nicht wünschen, glaubt mir!", sourceObjective = "Folgt Zirdo auf seiner \"Tour\".", progress = "Mir fehlen die Worte.", completion = "Mir fehlen die Worte.", sourceObjectiveStatus = "unverified-source-field" }
quests[83144] = { id = 83144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aderlass", description = "Das Land leidet unter der Oberfläche. Diese Rohrleitung transportiert Schwarzblut in riesigen Mengen nach Norden!\n\nIch habe das Land noch nie so schnell verseucht gesehen. Beseitigt die Fäulnis, vielleicht können wir es noch retten.\n\nIch kümmere mich um die Strukturen. Weist auf Schwachstellen hin, wenn Ihr sie findet, und ich konzentriere unseren Angriff!", sourceObjective = "Tötet Schwarzblutkreaturen und signalisiert Orweyna, Schwachstellen in der Rohrleitung anzugreifen.", progress = "Die Schrecken, die diese Goblins hervorgebracht haben, sind wahrlich eine Plage für dieses Land.", completion = "Ich misstraue den Goblins, die für diese Rohrleitung verantwortlich sind.\n\nSeid vorsichtig, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[83145] = { id = 83145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paranoiaprävention", description = "Welche Informationen sucht Gallywix hier in Gossenheim? Mal sehen, ob uns einige dieser Goblins einen Hinweis geben können.\n\nFangen wir mit allen Bilgewasser-Goblins an, die wir finden können.", sourceObjective = "Untersucht Gossenheims Spionageproblem.", progress = "Hier scheint es mehr darum zu gehen, die Leute zum Schweigen zu bringen, als wirklich etwas zu erfahren.", completion = "Ich hoffe, Renzik erwischt Zirdo, bevor er plaudern kann, aber darauf sollten wir uns nicht verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83146] = { id = 83146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pamsys prächtige Pumpe", description = "Ich habe ein Team von Ingenieuren. Sie alle haben Familien. Sie haben immer wieder schreckliche Unfälle und Infektionen durch das Schwarzblut. Ich konnte einfach keinen weiteren Tod ertragen. Ich habe die Mauer geöffnet. Ich wollte uns damit etwas Hoffnung bringen.\n\nIhr taucht auf und wollt das Schwarzblut aufhalten. Es bringt nichts, die Rohre hier oben zu stoppen. Wir müssen an die Pumpstation kommen.\n\nAlso, meine Leute und die Pumpen? Sie sind alle an der gleichen Station. Aber wir sollten uns beeilen.", sourceObjective = "Geht zur Pumpstation und trefft Pamsy.", completion = "Ich kann es nicht glauben. Zirdo muss Aufseher Gozzic von mir erzählt haben. Das ist eine klare Botschaft, aufzuhören...", sourceObjectiveStatus = "unverified-source-field" }
quests[83147] = { id = 83147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutiges Geschäft", description = "Die Schrecken des Schwarzbluts hier dürfen nicht unterschätzt werden. Die Stärke des Schwarzbluts an diesem Ort führt dazu, dass sich meine Visionen weit entfernt anfühlen, wie ein seltsames Flüstern.\n\nTötet die Manifestationen dieser Fäulnis, bevor sie stärker werden.", sourceObjective = "Tötet Blutschrecken für Orweyna.", progress = "Ich kann diese Plage im Land nicht ignorieren.", completion = "Es wird viel mehr nötig sein, um diese Wunden zu stillen. Wir dürfen nicht müde werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[83148] = { id = 83148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "X-treme Kälte", description = "Pamsy und ich haben eine Idee. Da wir nicht an die Steuerungen herankommen und sie auch nicht in die Luft jagen können, könnten wir die Pumpstation einfrieren.\n\nHört mir zu!\n\nPamsy hat erwähnt, dass viele der Maschinen im Norden in letzter Zeit überhitzen, weil das ganze Kühlmittel im Süden gebraucht wird. Und es ist noch schwerer, an welches zu kommen, weil die Blutschleime es fressen. Was wäre, wenn wir den gesamten Kühlmittelvorrat finden und in die Pumpstation kippen würden?\n\nWir legen den ganzen Betrieb auf Eis und es würde ewig dauern, das zu reparieren!", sourceObjective = "Tötet Kühlbauchschleime und sammelt Frostknallkanister.", progress = "Sammelt genug, um die ganze Station einzufrieren!", completion = "Toll, das ist eine gute Ausbeute!", sourceObjectiveStatus = "unverified-source-field" }
quests[83149] = { id = 83149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt für sie Rache", description = "Ich bin Zirdos Spur nach Süden gefolgt und bin auf einen ziemlich üblen Kerl namens Gozzic Ritzelstock gestoßen, der seine Arbeiter schikaniert und irgendwas von einer \"weiteren Lektion\" faselt. Zirdo muss diesem Gozzic alles erzählt haben, aber ich muss das noch bestätigen. Ich denke, dass wir die Beweise bei Gozzic selbst finden werden.\n\nGozzic könnte die Befehle erteilt haben, aber angesichts des blutigen Schredders und der Spuren an Pamsys Mannschaft, bin ich mir sicher, dass er sich selbst die Hände schmutzig gemacht hat. Ihr solltet es ihm gleichtun. Tötet Gozzic und durchsucht ihn auf Hinweise darauf, dass Zirdo bei ihm ausgepackt hat.", sourceObjective = "Tötet die Düsternisverschmolzenen, die Pamsys Ingenieure getötet haben.", progress = "Diese Ingenieure haben etwas Besseres verdient.", completion = "Ihr habt Beweise gefunden? Ich wusste es. Nicht so gut, wie Zirdo selbst zu erwischen, aber wir werden ihn am Ende kriegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83150] = { id = 83150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Plan ausweiten", description = "Hier ist der Plan. Wenn wir nur die Außenseite einfrieren, schmilzt alles in kurzer Zeit und wird wieder normal. Aber wir haben Orweyna. Sie kann Risse und Lecks in den Rohrleitungen ausfindig machen, damit das Kühlmittel ins Innere gelangen und alles richtig aufmischen kann.\n\nDa Ihr alle Kanister gesammelt habt, solltet Ihr die Ehre haben, die Rohrleitung fest einzufrieren.\n\nPamsy hat ein Raketenbrett, mit dem Ihr eisige Gerechtigkeit auf die wichtigsten Bereiche der Station ausüben könnt. Folgt Orweyna!", sourceObjective = "Reitet auf dem Raketenbrett und beschießt die Rohrleitung mit Eis.", progress = "Springt auf das Raketenbrett und schießt los!", completion = "Saubere Arbeit! Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[83151] = { id = 83151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Lorenhall", description = "Wir haben hier getan, was wir konnten. Es ist an der Zeit, einen Blick auf Lorenhall zu werfen.\n\nPamsy hat einen Kontakt, einen Venture-Goblin namens Grimla. Damit können wir anfangen, wenn wir ankommen.\n\nLasst uns Gazlowe holen und loslegen. Lorenhall ist nicht die Art von Problem, die man mit dem Messer löst. Dafür brauchen wir jemanden wie Gazlowe. Ihr wisst schon, einen Baumeister und Anführer.", sourceObjective = "Sprecht mit Gazlowe und geht dann mit dem Raketenbohrer nach Lorenhall.", completion = "Ich hoffe, Renzik und Pamsy wissen, was sie hier mit Grimla machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83152] = { id = 83152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmanagement", description = "Als wäre der Ausfall des Rohrs nicht so schon genug, sind dabei auch noch eine Horde magmatischer Elementare hervorgebrochen.\n\nWir können nicht riskieren, jemanden zur Reparatur runterzuschicken, solange das Gebiet überlaufen ist, doch das Magma ist unerlässlich für die Energieversorgung der gesamten Tiefen.\n\nWenn Ihr Euch das zutraut, dann beseitigt die Elementare, damit wir das Magma wieder fließen lassen können.", sourceObjective = "Tötet erweckte Magma und Schlackeblasen in der Nähe des Tors von Heilsturz.", completion = "Beachtliche Leistung. Wir könnten bei unserer Arbeit etwas weniger Aufregung gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83153] = { id = 83153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Problematische Proben", description = "Die Auswirkungen des magmatischen Rückstaus sind klar zu erkennen, doch wir verstehen nach wie vor die Ursache dahinter nicht.\n\nUm der Sache auf die Spur zu kommen und weitere Ausbrüche zu vermeiden, müssen wir Proben der vulkanischen Gase sammeln, die aus dem Boden schießen.\n\nFrische Proben. Richtig frische Proben.\n\nIhr müsst Euch hineinstellen, wenn sie hervorbrechen, damit ich bekomme, was ich brauche.", sourceObjective = "Steht in der Nähe des Tors von Heilsturz in ausbrechenden Gasschloten, um Proben zu sammeln.", completion = "Hoffentlich offenbaren diese Proben, was falsch gelaufen ist. Ich weiß Eure Unterstützung wirklich zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83154] = { id = 83154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schickschnacks Krimskrams", description = "Nicht fair! Nicht fair! Schnickschnack sammeln viel Glitzerzeug während langes Leben. Aber jetzt blöde Wachsbirnen von Kerzenklauen Schnickschnack und Familie vertrieben. Alles Glitzerzeug zurückgelassen!\n\nHier, Goblinfreund mit Liste aller Schätze in Dunkelflammenspalt geholfen. Ihr zurückholen!", sourceObjective = "Holt Schnickschnacks Schätze aus dem Dunkelflammenspalt.", progress = "Schätze alle sehr wichtig. Sehr wertvoll. Ihr nichts nehmen für Euch! Mir wiederbringen!", completion = "Ihr geschafft haben! Ihr geschafft haben! Meine Schätze! Das nehmen, blöde Kerzenklauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83155] = { id = 83155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maulwurfrauswurf", description = "Alles, was zwischen uns und der saftigsten Ausgrabungsstätte überhaupt steht, sind paar Maulwürfe und ein langbeiniges Wildvieh. Aber ich greife vorweg.\n\nSeht Ihr diese Schredder? Das Modernste, was es zum Keulen und Vernichten gibt. Aber sie bleiben immer in Löchern stecken!\n\nHört zu, ich bin so umweltbewusst wie jeder Goblin, aber diese Maulwürfe müssen weg. Macht diesen Wühlmäusen ordentlich den Garaus. Und wenn Ihr Leute aus meinem Trupp seht, helft ihnen aus, ja?", sourceObjective = "\"Entfernt\" 15 Dickschädelmaulwürfe.", progress = "Habt Ihr Euch schon um sie gekümmert? Ich habe keine Lust, noch mehr Schredder aus dem Dreck zu ziehen.", completion = "Denen habt Ihr ordentlich Beine gemacht! Jetzt steht nur noch eine klitzekleine Sache zwischen uns und all diesen schönen Ressourcen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83159] = { id = 83159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lange Beine, kurzer Prozess", description = "Habt Ihr schon mal einen Tiefschreiter gesehen? Dieser scheint jedenfalls nicht sehr erfreut, uns zu sehen. Macht kurzen Prozess mit diesen Schreddern, die es an den Maulwürfen vorbei geschafft haben. Nur blöd, dass die Piloten jetzt Überstunden schieben müssen, um die Schäden wiedergutzumachen.\n\nAber wenn sich jemand darum kümmerte und mir einen Beweis dafür brächte, tja, ich wette, das würde einen hübschen Zahltag ergeben.", sourceObjective = "Tötet Alhainr und sammelt seinen Schädel ein.", progress = "Was habt Ihr getan?!", completion = "Das ist übel, echt übel! Man würde meinen, wenn man was abmurkst, wird es weniger gefährlich. Wir werden zertrampelt!", sourceObjectiveStatus = "unverified-source-field" }
quests[83160] = { id = 83160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glutbräureserve", description = "Der Handel mag eingeschränkt worden sein, doch eher verkalke ich, als dass ich meine Glutbräureserve in die Hände dieser rostigen Schrauben fallen oder in die Luft fliegen lasse, sobald ein Elementar sie schief anguckt.\n\nDie Inspekteure behalten mich im Auge, weshalb ich sie nicht selbst holen kann, aber Euch werden sie nicht weiter beachten.\n\nIch habe sie hinter dem Schreibtisch unten in meinem alten Büro gelassen.\n\nKommt aber den Vollstreckern nicht zu nahe, sonst konfiszieren sie sämtliches Glutbräu, das Ihr bei Euch tragt, was wiederum bedeutet, dass ich nichts zu trinken bekomme.", sourceObjective = "Bringt die Glutbräureserve zu Ratzels am Tor von Heilsturz.", progress = "Habt Ihr ihn?", completion = "Ah, wenn das nicht ein Bräu ist, auf das es sich zu warten lohnt. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[83162] = { id = 83162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts wie weg damit!", description = "Das macht alles zunichte! Wer will schon ein Resort besuchen, an dem sich ein 10 Meter großer Geisterhirsch rumtreibt? Okay, kein Grund zur Panik. Er ist vermutlich nur ein bisschen angefressen, weil Ihr seinen Schädel stibitzt habt.\n\nErstmal müsst Ihr paar dieser Schleime loswerden. Und dann bringt Ihr den Schädel weg von hier. Je weiter weg, desto besser.\n\nOh Mann, die versauen noch die heißen Becken mit ihrem Ektoplasma!", sourceObjective = "Zerstampft Schleime und bringt Alhainrs Schädel weg von der Stadt.", progress = "Beeilt Euch, bevor die hier noch mehr Chaos stiften!", completion = "Puh, das war knapp. Die ganze Sache hat mich die Schönheit der Natur wirklich schätzen gelehrt.\n\n<Der Goblin bricht in Gelächter aus.>\n\nDa hab ich Euch echt drangekriegt, was? Ich glaube allerdings, dass ich von der Abyssausgrabung wirklich eine Weile die Finger lassen sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[83163] = { id = 83163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture gespalten", description = "Als Nächstes geht es in mein Revier, Venturemühle. Das liegt in der Nähe der Halden.\n\nDie Venture Company ist größtenteils auf Gallywix' Seite. Das bedeutet, dass viele von den hohen Tieren genauso korrupt sind wie er. Passt auf.\n\nAber es gibt dort auch ein paar gute Leute. Wie Pamsy und ihre Truppe. Der kleine Mann bei Venture Company hat es schwer. Alle denken, bei Venture Company gäbe es nur die Bösen, darum kümmert sich niemand um sie. Aber ich muss es versuchen, oder?\n\nSpringt in den Hot Rod und ich zeige Euch, was ich meine.", sourceObjective = "Fahrt mit dem Hot Rod zur Venturemühle und helft den freundlichen Goblins der Venture Co.", progress = "Anscheinend gibt es keinen Respekt für die ganz unten.", completion = "Das habt Ihr gut gemacht für diese Goblins. Nikki sorgt für Chaos, und nicht auf die lustige Art.", sourceObjectiveStatus = "unverified-source-field" }
quests[83164] = { id = 83164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stadt der Fäden: Die Verbinderin trennen", description = "Der \"Aufstieg\" ist keine wahre Evolution. Es ist eine Entweihung. Eine Verdammnis. Und Ansurek meißelt dieses Unheil mit jedem Tag weiter in den Stein.\n\nWenn wir das Transformatorium ausschalten, können wir Azj-Kahet möglicherweise ein für alle Mal von diesen Monstrositäten befreien.\n\nIzo, die große Verbinderin, ist Ansureks auserwählte Aufseherin für den Aufstiegsprozess. Schlagt dieser Hexe den Kopf ab, dann finden diese Mutationen hoffentlich ein Ende.", sourceObjective = "Betretet die Stadt der Fäden und besiegt Izo, die große Verbinderin.", progress = "Habt Ihr Euch um das Transformatorium gekümmert, {name}?", completion = "Ihr habt Ansurek einen Schlag versetzt, von dem sie sich nie erholen wird, {name}.\n\nNehmt das und dann weg hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[83165] = { id = 83165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse, Bot!", description = "Nur zu, lacht ruhig. Das würde ich auch, wenn ich gerade nicht Wichtigeres zu tun hätte. Der Fuß meines Bots hat einen Felsbrocken am Boden gestreift, mich rausgeschleudert und sich dann wieder gefangen... Ohne mich im Cockpit!\n\nIch sitze hier am Boden fest, während mein Bot vergnügt herumschwirrt. Ist das zu fassen?\n\nHört mal, falls Ihr hoch zur Schattenaderspitze geht, könntet Ihr Kagfritha dann bitte mitteilen, dass ich zu spät zu meiner Schicht komme? Ich muss darauf warten, dass dem Schrotthaufen der Treibstoff ausgeht, um mich wieder hinters Steuer klemmen zu können.", sourceObjective = "Sprecht mit Kagfritha an der Schattenaderspitze.", completion = "Sinruna wurde wieder abgeworfen, wie? Ich habe ihr schon so oft gesagt, dass sie zu tief fliegt. Vielleicht hat sie ihre Lektion jetzt auf die harte Weise gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83166] = { id = 83166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ara-Kara, die Stadt der Echos: Das Ende der Ernte", description = "Ihr habt es selbst gesehen, nicht wahr? Das \"schwarze Blut\", wie wir es nennen.\n\nWir werden nicht länger untätig bleiben. Nicht, während Ansurek unser kostbares Land für die letzten stinkenden Reste vom Todesröcheln der alten Götter schändet, aufbohrt und ausblutet.\n\nSucht die alte Stadt unter uns auf: Ara-Kara, die Stadt der Echos. Wenn Ihr die Halunkin erledigt, die für die Ausgrabung verantwortlich ist, erwartet Euch sicher ein hübsches Kopfgeld. Ihr Volk nennt sie Ki'katal die Ernterin.", sourceObjective = "Betretet Ara-Kara, die Stadt der Echos, und besiegt Ki'katal die Ernterin.", completion = "Ki'katal ist tot? Sehr gut.\n\nWir schulden Euch Dank, {name}. Sowohl in Worten als auch in materiellem Wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[83167] = { id = 83167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen von oben", description = "Das mit Nikki war hart. Und schlimmer noch, die Spionagekopter der Düsternisverschmolzenen haben alles gesehen. Es fühlt sich an, als könnten wir den Spionen nicht entkommen, was?\n\nVenture Company wäre wirklich nicht geholfen, wenn Gallywix denkt, diese Arbeiter seien nicht loyal, weil sie bei einem von Nikkis Wutausbrüchen gefilmt wurden. Wir wollen nicht, dass sich das wiederholt, was mit meiner letzten Truppe passiert ist.\n\nBesorgt Euch das Filmmaterial von den Spionagekoptern. Sie lauern normalerweise in den Werkstätten oder folgen den Venture-Arbeitern.", sourceObjective = "Vernichtet 8 Spionagekopter, um ihr Filmmaterial zu stehlen.", progress = "Es gibt nichts Besseres, als böse Maschinen für eine gute Sache zu zerstören.", completion = "Je weniger Gallywix gegen uns in der Hand hat, desto besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[83168] = { id = 83168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schwarzblutspur", description = "Während Ihr Euch mit der Lage in Lorenhall vertraut gemacht habt, habe ich unsere Beute aufgespürt. Die Präsenz des Schwarzbluts ist überall, versteckt hinter lauten Ablenkungen.\n\nAber diese Stadt kann mich nicht täuschen. Ich habe eine Schwarzblutlieferung an einem Ort namens Bruchbudenhügel entdeckt, aber er wurde von Maschinen bewacht. Wir sollten zusammen hingehen.", sourceObjective = "Sucht in Bruchbudenhügel nach Schwarzblutlieferungen.", progress = "Die Verfolgung der Lieferungen sollte uns zeigen, wer sie benutzt. Überprüft alle herumliegenden Etiketten oder Briefe!\n\nIch glaube, ich habe alle Abwehrkräfte überwältigt, sie werden uns in Ruhe lassen.", completion = "Baron Revilgaz transportiert Schwarzblut in der Stadt? Und er ist paranoid wegen der Astralen?!\n\nIch habe Fragen, und er hat Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[83169] = { id = 83169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weit weg von der Beutebucht", description = "Es besteht kein Zweifel. Diese Lieferungen tragen die Handschrift der Schwarzmeer AG... im wahrsten Sinne des Wortes. Das Schwarzblut kommt hier an und wird dann von der Schwarzmeer AG per Kurier irgendwo in die Stadt gebracht.\n\nWenn wir also herausfinden wollen, wohin, müssen wir ganz nach oben, zu Baron Revilgaz. Grimla hat erwähnt, dass Revilgaz hier in der Nähe, in Bruchbudenhügel, eine vorläufige Niederlassung hat. Gehen wir ihn besuchen.\n\nDas mit den Astralen wird warten müssen.", sourceObjective = "Findet Baron Revilgaz in Bruchbudenhügel.", progress = "Ich habe ein ungutes Gefühl bei der Sache, aber lasst uns mit Revilgaz reden.", completion = "Wir können uns sicherlich einigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83170] = { id = 83170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht schon wieder!", description = "Die Düsternisverschmolzenen gehen nach Bruchbudenhügel. Genau dasselbe haben sie auch an der Schwarzmeermarina getan. Kaum sind sie ankommen, schubsen sie die Einwohner herum. Manchmal vertreiben sie sie auch einfach. Es ist falsch und ich möchte mich wehren, aber mir sind die Hände gebunden.\n\nWenn ein Fremdling auftauchen und Ärger machen würde, wäre das eine andere Geschichte.", sourceObjective = "Heizt für Revilgaz den Düsternisverschmolzenen in Bruchbudenhügel ein.", completion = "Wenn ich mehr wie Euch hätte, hätte ich nicht meinen... den Hafen verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[83171] = { id = 83171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es brennt in den Augen", description = "Sie nennen sie Rekrutierungsplakate, aber das ist nicht alles, was sie sind. Sie sind hier, um alle daran zu erinnern, dass die Düsternisverschmolzenen das Sagen haben und tun können, was sie wollen. Wenn ich oder einer der Einheimischen sie abreißen, geht es schlecht für uns aus. \n\nAber Euch hassen die Düsternisverschmolzenen sowieso. \n\nWenn Ihr alle Plakate verbrennt, schulde ich Euch was.", sourceObjective = "Verbrennt 8 Rekrutierungsplakate der Düsternisverschmolzenen an und um Revilgaz' Haus.", completion = "Das hält vielleicht nicht die Düsternisverschmolzenen fern, aber wenigstens ist Bruchbudenhügel etwas schöner ohne diesen Müll an den Wänden. \n\nWie gesagt, ich schulde Euch was.", sourceObjectiveStatus = "unverified-source-field" }
quests[83172] = { id = 83172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzblutstaffellauf", description = "Die Schwarzmeer AG ist nur ein Schritt auf der Reise und sie halten die Dinge gern in Bewegung. Revilgaz lässt es seine Leute vom Bahnhof abholen, eine Weile verstecken und dann zu den Lagerstätten bringen. Die Lagerstätten ändern sich, aber gerade ist es ein Depot in den Halden.\n\nWir müssen es uns ansehen und herausfinden, wo das Schwarzblut anschließend hinkommt.\n\nEr sagt, das Depot ist bewacht, also haltet am Rand Ausschau nach uns.", sourceObjective = "Trefft Euch mit Renzik und Gazlowe in der Nähe des Schwarzblutdepots in den Halden.", completion = "Das sind viele Wachen. Wir sind etwas auf der Spur.", sourceObjectiveStatus = "unverified-source-field" }
quests[83173] = { id = 83173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Depot ausräumen", description = "In den Halden wimmelt es nur so von Wachen. Wir haben eine Gelegenheit, die Schwarzblutoperation in Lorenhall zu stören, und die sollten wir ergreifen.\n\nWir können nicht verhindern, dass das Schwarzblut in die Stadt gelangt, aber wir können einige Wachen erledigen und einige Lieferungen zerstören. Macht genug Chaos, um die Dinge zu unterbrechen. Jedes Bisschen hilft.", sourceObjective = "Säubert das Depot in den Halden.", progress = "Jede verlorene Wache oder Lieferung wird sie Zeit und Geld kosten. Und Gallywix hasst es, beides zu verlieren.", completion = "Das sollte das Schwarzblutgeschäft bremsen. Hoffentlich haben alle, die auf eine Lieferung warten, einen richtig schlechten Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[83174] = { id = 83174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser lieber Freund", description = "Unser alter Kumpel Zirdo ist zurück. Sieht aus, als wäre er zum Aufseher der Halden befördert worden und überwacht jetzt die Schwarzblutlieferungen.\n\nWir schulden ihm noch eine Retourkutsche, weil er uns in Gossenstadt verpfiffen hat. Er hat einige gute Goblins umbringen lassen, um sich mit Gallywix gut zu stellen. Gebt der Ratte, was sie verdient.", sourceObjective = "Tötet Zirdo.", completion = "Ich habe nicht vergessen, was er Pamsys Leuten in Gossenstadt angetan hat... das war auch für sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[83175] = { id = 83175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein weiterer Teil des Puzzles", description = "<Das Geschäftsbuch ist voll mit langwierigem Gefasel über Zirdos Errungenschaften, enthält aber auch mehrere Schwarzblutlieferungen in ganz Lorenhall. Mehrere Einträge im Geschäftsbuch kommen Euch merkwürdig vor:\n\n- Eintausend Einheiten für Geheimprojekt, an geheimen Ort zu liefern.\n- Zwanzig Einheiten für experimentelle Munition, per Kurier auszuliefern.\n\n- Überweisungen von Noggenfogger vom Dampfdruckkartell autorisiert.>", sourceObjective = "Besprecht den Inhalt von Zirdos Geschäftsbuch mit Gazlowe in den Halden.", progress = "Noggenfogger weiß es besser, als sich mit Gallywix anzulegen.", completion = "Das ist alles zu viel.", sourceObjectiveStatus = "unverified-source-field" }
quests[83176] = { id = 83176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ein Gefühl", description = "Es ist Zeit zu überlegen, wie wir weitermachen. Diese Sache mit Noggenfogger macht Gazlowe ganz nervös und wir müssen schnell handeln, um herauszufinden, was los ist. \n\nMich macht auch was nervös. Wir sollten schnell aus den Halden verschwinden. Aber Gazlowe muss mit an Bord sein.", sourceObjective = "Meldet Euch bei Renzik wegen Gazlowe und trefft dann Gazlowe vor den Halden.", completion = "Grimla sagt, Orwenya und Alleria sind nicht aufgetaucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[83177] = { id = 83177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Medizin fürs Volk", description = "Ich bin darauf aufmerksam geworden, dass viele der geknechteten Einwohner des Baus einer Art Krankheit anheimgefallen sind.\n\nNehmt diesen Trank und verabreicht ihn den Kranken. Das wird sie stärken und einen weiteren Ausbruch verhindern.", sourceObjective = "Verabreicht geknechteten Einwohnern Nizreks Trank.", progress = "Habt Ihr den Einwohnern des Baus geholfen?", completion = "Ich werde nicht zulassen, dass sie leiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[83178] = { id = 83178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regeln und Konsequenzen", description = "Ich fürchte, ich war in letzter Zeit etwas zu vorlaut, als ich meinen Beistand anbot. Jetzt habe ich einige unerwünschte Blicke auf mich gezogen.\n\nSeid wachsam. Eine verschleierte Bedrohung lauert.", sourceObjective = "Besiegt die Assassine.", progress = "Habt Ihr Euch um den Eindringling gekümmert?", completion = "Vielen Dank für Eure Hilfe. Mein Verstand ist meine Stärke, aber mein Geschick auf dem Schlachtfeld lässt etwas zu wünschen übrig.\n\nUnd doch, wenn Ansureks Attentäter mich gefunden haben...\n\nNein. Ich kann jetzt nicht aufhören. Ich habe noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[83181] = { id = 83181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute Freunde, gleiches Ende", description = "Ich habe beobachtet, wie die Schiffsbauerin die Höhle verließ und zum Strand hinunter ging. Sie wurde von einem stattlichen Neruber begleitet.\n\nDie Schiffsbauerin ist der führende Kopf hinter dieser ganzen Operation. Sie weiß genau, wie man das Holz zuschneiden muss und welches Holz man für ihre Luftschiffe braucht.\n\nDie Neruber wissen, wie wichtig sie ist, und haben ihr vermutlich einen ihrer besten Krieger als Leibwache zur Seite gestellt.\n\nWenn wir die Schiffsbauerin ausschalten, können wir ihre sorgfältig ausgearbeiteten Pläne zunichte machen.", sourceObjective = "Schaltet Schiffsbauerin Isaebela und Schattenweber Azarak bei der Seidenwaldgrotte aus.", completion = "Jetzt, wo die Anführerin der Neruber vernichtet wurde, wird unter ihren verbleibenden Truppen das Chaos herrschen.\n\nOhne das Wissen und die Befehle der Schiffsbauerin ist ihre gesamte militärische Operation kopflos.\n\nHoffen wir, dass dies auch einen Keil zwischen diese hoffentlich ehemaligen Freunde treibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83182] = { id = 83182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutiges Erbe", description = "Als die Kobyss meine Eltern getötet haben, haben sie einige ihrer liebsten Dinge gestohlen.\n\nNicht mich, selbstverständlich, sondern geliebte Gegenstände.\n\nLasst uns danach Ausschau halten, während wir ein paar Kobyss abmurksen.", sourceObjective = "Erlangt die Gegenstände von Alyzas Eltern im Lauernden Strudel in Heilsturz.", progress = "Elendige Kobyss. Ich hasse sie.", completion = "Gut gemacht. Ihr seid deutlich nützlicher als all die anderen Erwachsenen, die mir das ausreden wollten.\n\n\"Aber Alyza, die Kobyss sind gefährlich. Da stirbst du noch.\" Dumme Erwachsene denken, sie wüssten alles besser.\n\nSeid Ihr bereit, den Großen zu erledigen? Also ich bin bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[83194] = { id = 83194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter Feuer", description = "Ich stehe nur wegen Renzik hier. Er hat nicht einmal darüber nachgedacht, er hat einfach...", sourceObjective = "Seid für Monte Gazlowe da.", progress = "Wir sind noch nicht fertig.", completion = "<Gazlowes Gesicht zeigt einen Ausdruck, wie Ihr ihn noch nie gesehen habt. Es ist vor Wut verzerrt, und doch spricht er mit tödlicher Ruhe.>\n\nEs besteht kein Zweifel mehr. Es heißt Gallywix oder wir. Wir können ihn keinen Tag länger ertragen. Er muss aufgehalten werden. Keine Kompromisse mehr. Keine Geduld mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[83195] = { id = 83195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mobilisiert das Volk", description = "Niemand wurde stärker von Gallywix unterdrückt als das Bilgewasserkartell. Eine Menge wollen sich erheben, aber das reicht nicht. Wir müssen ihnen zeigen, was Gallywix getan hat, und sie überzeugen, dass die Zeit jetzt gekommen ist.\n\nFangen wir mit einer Schlagzeile an. Kommt schon, her mit den Ideen. Ein großer Name wie Eurer vertritt unsere Botschaft besser als irgendwer sonst.", sourceObjective = "Überlegt Euch mit Dirk Schmierhändler eine Schlagzeile und verbreitet dann das Wort von der Revolution im Hintertürpark.", progress = "Die Zeit, sich zu erheben ist gekommen. Sagt es ihnen, {name}.", completion = "Spannung liegt in der Luft. Ich kann es spüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[83196] = { id = 83196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufteilen!", description = "Gallywix kann die Wahrheit nicht verbergen, aber er kann uns so lange fertigmachen, bis die Leute keine andere Wahl haben, als seine Version zu akzeptieren. Das werden wir nicht noch einmal zulassen. \n\nWenn Ihr jemanden seht, der einem Bilgewassergoblin wehtut, erwidert den Gefallen.", sourceObjective = "Tötet 20 Düsternisverschmolzene im Hintertürpark.", completion = "Die Gelegenheit, das mit Worten zu klären, ist längst vorbei. Wenn sie zu Gallywix stehen, ist das ihr Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[83197] = { id = 83197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wem gehört die Straße?", description = "Sie! Nikki die Macherin, die oberste Vollstreckerin der Venture Company. Renziks Blut klebt an ihren Händen. \n\nIch darf mich nicht darum kümmern, ob sie noch eine Kugel hat. Wir müssen ihr nach. Seid Ihr dabei, {name}?", sourceObjective = "Stellt Renziks Mörderin, Nikki die Macherin.", completion = "Ihr habt es gerade rechtzeitig zum Enterkommando geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[83198] = { id = 83198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterhofmarine", description = "Gallywix und seine Leute haben sich zu lange in unsere Angelegenheiten eingemischt. Seht Euch an, was sie mit meinem Hafen machen! Sie fühlen sich mit ihrem Besitz so wohl, dass sie auf Jetskis Donuts machen!\n\nEs wird Zeit, dass wir sie mit ein wenig Hochsee-Feuerkraft bekannt machen.\n\nNehmt diese Kanone und jagt die Schiffe der Düsternisverschmolzenen in die Luft, die unsere Gewässer unsicher machen. Und danach tut mir einen Gefallen und seht nach dem Großen, ja?", sourceObjective = "Zerstört die Freudenreiter der Düsternisverschmolzenen in der Schwarzmeermarina.", progress = "Hat mein Kapitän Euch geschickt? Er wusste, dass ich Hilfe brauche...", completion = "Hrrk. Das Donnern von Kanonenfeuer und der Geruch von Schwarzpulver. Ihr wärt ein guter Kanonier.", sourceObjectiveStatus = "unverified-source-field" }
quests[83199] = { id = 83199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das hab ich mir aufgehoben", description = "Hört her, {name}. Sprinkel kocht da seit langem etwas aus, was ich endlich zu Geld machen kann. Eine kleine alchemistische Geheimzutat. Zitrusfrüchte! Liefert den doppelten Kick von Noggenfoggers Wiederherstellungselixieren in der halben Zeit. Stärkt Eure Knochen, lässt die Muskeln wachsen, macht Eure Steuern. Das volle Programm!\n\nDas Problem ist, dass ich nichts derartiges griffbereit habe. Diese Resortleute haben vielleicht, was Ihr braucht. Wir haben uns das Rezept für die schweren Geräte aufgehoben. Geht sicher, dass es Seehorn gut geht, bevor Ihr es aufkocht, ja?", sourceObjective = "Sammelt Limonen von den Resortangestellten in der Schwarzmeermarina.", progress = "Ngh. Haben sie mich mit dem Schwarzblut erwischt?", completion = "Limone? Was soll das denn? Wir sind im Krieg gegen etwas viel schlimmeres als Skorbut!", sourceObjectiveStatus = "unverified-source-field" }
quests[83200] = { id = 83200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahoi, Ihr Lappen!", description = "Uff. Ich war hier so lange eingesperrt. Vor lauter Wut wurde ich leichtsinnig.\n\nWas auch immer Noggenfogger Euch gegeben hat, ich verspreche, dass ich es nicht verschwende. Bringt mich zurück in den Kampf und ich lasse diese Eindringlinge die ganze Macht der Schwarzmeer AG spüren.", sourceObjective = "Braut Noggenfogger Deluxe mit Limone und gebt es Flottenmeister Seehorn.", completion = "Ich fühle mich wie neugeboren, dank Euch.\n\nSie haben unseren Hafen in ein überteuertes Resort verwandelt, hinter dessen Fassade Schwarzblut geschmuggelt wird. \n\nRechnen wir ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[83201] = { id = 83201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expresslieferung", description = "Die Schwarzmeer AG übernimmt den Hafen. Aber mit dem ganzen Schwarzblut da draußen sind die Leute nicht sicher.\n\nDiese fliegenden Transporte müssen das Schwarzblut zu einem Ort bringen, der in der Hand der Venture Company ist. Wenn Ihr eine davon steuert, könntet Ihr Grimla finden. Sie ist in diese Richtung gegangen, nachdem wir uns getrennt haben, und hat gerufen, dass eine Freundin von ihr unterwegs sei.", sourceObjective = "Fliegt mit einem defekten Kistenschlepper mit.", completion = "Genau die zwei Leute, die ich sehen wollte. Wir stecken hier bis zum Hals in Schwarzblut.", sourceObjectiveStatus = "unverified-source-field" }
quests[83202] = { id = 83202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagfertige Argumente", description = "Die Zeit, unsere Differenzen auszudiskutieren, ist vorbei. Ich habe genug davon, zu hinterfragen, wer noch zu Gallywix steht.\n\nEinige von Nikkis Leuten führen die Produktion dieser neuen Waffen fort. Also schalten wir sie aus. Das macht es auch viel einfacher, die Venture Company aufzuräumen, nachdem all das vorbei ist. \n\nAber passt auf. Nikki hält nicht den Hals für ihre Offiziere hin, aber sie nimmt jede Chance an, in einem Kampf gegen Euch etwas zu drehen.", sourceObjective = "Besiegt die drei Leutnants der Venture Company-Loyalisten.", completion = "Es musste getan werden. Wir sind noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[83203] = { id = 83203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen scharf", description = "Die zerstörerischen Impulse jener, die Azeroth für ihren eigenen Profit ausbeuten, entsetzen mich jedes Mal. Doch diese Waffen sehen anders aus als alles zuvor.\n\nAlle Behälter mit Schwarzblut müssen geleert und vernichtet werden. Waffen, die damit angetrieben werden, zerschmettert und zerlegt werden. Jene, die sie gegen andere nutzen, unschädlich gemacht werden. Die Bewohner dieser Stadt und dieser Welt sind nicht sicher, bis das getan ist.", sourceObjective = "Zerstört Schwarzblutkisten und -waffen in den Halden.", completion = "Gut gemacht. Doch nun müssen wir das Herz ihrer Waffenproduktion angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83204] = { id = 83204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dingsbums", description = "Nikkis Technik wird mit Schwarzblut betrieben. Ich weiß das, weil ich an der Hälfte davon mitgearbeitet habe. Das bedeutet auch, dass ich eine Ahnung habe, wie wir sie lange genug vom Himmel holen können, um sie auszuschalten.\n\nKeine Zeit für Vorproduktionen. Wir müssen bauen.\n\nErinnert Ihr Euch an unser schickes kleines Schwebebrettabenteuer? Eis ist heiß, nicht? Ich denke an ein ähnliches Konzept - im Schrott der Halde sollte alles stecken, was wir für den Bau dieses hypothetischen Dingsbums brauchen.", sourceObjective = "Bergt Teile für Pamsy in den Halden.", progress = "Wenn Ihr Zeit zum Quatschen habt, habt Ihr auch Zeit zum Zerschmettern!", completion = "Ich kenne nur einen Ingenieur, der den Grips hat, um rechtzeitig das zu bauen, was wir brauchen, um Nikki zu erledigen...", sourceObjectiveStatus = "unverified-source-field" }
quests[83205] = { id = 83205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Produktionsstopp", description = "<Orweyna reibt sich die Hände mit Erde ein und lässt dann die Knöchel knacken.>\n\nJetzt lassen wir alle, die mit Schwarzblut spielen, den Zorn der Natur spüren. Ich würde gerne die Wurzeln anrufen, die sich durch Azeroth winden.\n\nSchließt Euch mir an. Entfesselt den Zorn der Natur, wie wir es schon einmal getan haben. Lasst uns ihren wertvollen Schwarzblutvorrat zerstören.", sourceObjective = "Zerstört den Schwarzblutvorrat in den Halden.", completion = "Natürlich wurde aus dem Fleck ein riesiges Monster. Immerhin habt Ihr Euch darum gekümmert. Je weniger Schwarzblut sie haben, um ihre Waffen zu betreiben, umso besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[83206] = { id = 83206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uns gehört die Straße", description = "Die Handelsprinzen behandeln die Goblins hier nicht wirklich gerecht, das kann also nicht nur ein weiterer Kartellkrieg sein. Die Leute müssen wissen, dass sie nicht für Bilgewasser oder Dampfdruck kämpfen. \n\nSie kämpfen für Lorenhall. \n\nWir brauchen jemanden, der kein Kartellmufti ist, um sie zusammenzutrommeln und in Sicherheit zu bringen. Tut, was Ihr müsst, um sie ins Garbagio zu schaffen, und zeigt diesen Goblins, dass es ihre Stadt ist.", sourceObjective = "Mobilisiert das Volk von Lorenhall gegen Gallywix.", completion = "Gallywix gehören diese Straßen nicht. Sondern uns. Das wird er nie mehr vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83207] = { id = 83207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein bester Lakai", description = "Wir haben Gallywix in die Enge getrieben. Und Lorenhall und seine Bewohner, die er unterdrückt hatte, erheben sich endlich.\n\nEr denkt, diese Macherin wird ihn schützen. Zeigen wir Gallywix, Nikki und allen anderen, dass die Dinge diesmal anders laufen.\n\n<Gazlowe schaut sich das Dingsbums an, das er gerade zusammengebaut hat.>\n\nSeht euch das an.", sourceObjective = "Bezwingt Nikki die Macherin.", completion = "Lasst es auf Euch wirken. Wir haben gewonnen. Gallywix konnte sich zwar vorerst herauswinden, aber wir haben ihm die Stadt abgenommen. \n\nAb heute gehört Lorenhall uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[83229] = { id = 83229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Wenn die Tiefen sich regen" }
quests[83240] = { id = 83240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Theatertruppe", description = "Da Ihr ein Ehrenmitglied der Theatertruppe seid, {name}, was haltet Ihr davon, eine Rolle in unseren Stücken zu spielen?\n\nKeine große Rolle. Ich möchte den Rest der Truppe nicht verärgern, indem ich ihnen das Rampenlicht nehme. Ihr wisst ja, wie sie sind.\n\nSteht Ihr zur Verfügung, sagen wir, einmal pro Woche?", sourceObjective = "Nehmt am Theatertruppenereignis teil.", progress = "Die Show muss weitergehen! Immer und immer weiter. Wir haben jetzt einen Vertrag für wiederkehrende Auftritte erhalten. Für die Irdenen bedeutet das... Tja, es bedeutet, dass wir alle sehr, sehr lange Arbeit haben werden.", completion = "Steinstark! Ihr seid der perfekte Neuzugang für unsere Theatertruppe, {name}.\n\nBitte helft uns auch bei unserem nächsten Auftritt!", sourceObjectiveStatus = "unverified-source-field" }
quests[83247] = { id = 83247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtig misstrauisch", description = "Viele Jahre lang waren die einzigen Nicht-Arathi, die wir in Heilsturz je sahen, Feinde, die uns töten wollten. Neruber, Schattenkreaturen, Bestien. Also verzeiht mir, wenn mir Eure plötzliche Ankunft verdächtig vorkommt.\n\nMeine bessere Hälfte würde mich jedoch drängen, etwas freundlicher zu sein... und ich will ja an mir arbeiten. Für sie.\n\nEinige der Salamanther in Schmuggelstieg haben uns Ärger gemacht. Tötet sie und bringt mir den Beweis.", sourceObjective = "Sammelt 9 Salamantherherzen in Schmuggelstieg.", progress = "Andere würden einfach darauf vertrauen, dass Ihr die Wahrheit sagt, wenn Ihr behauptet, getan zu haben, was Euch aufgetragen wurde.\n\nIch allerdings nicht.", completion = "Ihr habt geholfen.\n\nVielleicht hat sie recht und ich sollte dem Beispiel Dunelles folgen.\n\nVielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[83271] = { id = 83271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geheimnis kommt selten allein", description = "Nachdem mein Vater getan hat, was auch immer er getan hat, sind die Titanenmaschinen wieder funktionstüchtig - sogar die hier in Dornogal.\n\nDagran hatte genug Spaß mit Brinthe, indem er ihr tausend Fragen stellte, aber jetzt hilft er ihr, das Archiv zu durchsuchen.\n\nUnd jetzt braucht er Eure Hilfe. Er war zu aufgeregt, um mir zu sagen, warum, aber er wollte, dass Ihr ihn im Archiv aufsucht.", sourceObjective = "Seht nach Dagran Thaurissan II und Brinthe im Archiv in Dornogal.", completion = "Faszinierend. Dies ist eindeutig eine Kammer, die für einen Hüter bestimmt ist. Aber warum?\n\nDas müssen wir herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[83274] = { id = 83274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ursprünglicher Pfad durch die Zeit", description = "Alte Krieger erzählen immer wieder Geschichten, wie viel schwerer sie es zu ihrer Zeit auf Azeroth hatten.\n\nIch wette, sie würden behaupten, dass Ihr nicht einmal 10 Minuten in ihrer Welt durchhalten würdet.\n\nSeid Ihr zäh genug, um es herauszufinden? Zeigt es mir doch bitte.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ihr habt es geschafft, {name}! Diesen alten Kriegern habt Ihr gezeigt, dass Azeroth immer noch in guten Händen ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[83275] = { id = 83275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrüstung verzaubern", description = "Hallo, <Fremdländer/Fremdländerin>!\n\nIch habe von Eurem Treiben gehört seit Eurer dramatischen Ankunft an unseren Künsten. Wir Irdenen wissen Eure Hilfe zu schätzen.\n\nIch kann Euch lehren, wie Ihr Eure Ausrüstung mit Ressourcen aus meinem Land verzaubert. Um unsere Feinde zu besiegen, hilft jedes bisschen Macht.", sourceObjective = "Schließt die Einführung zu Gegenstandsverzauberungen ab, indem Ihr einen beliebigen Ring mit der Verzauberung von Ellerdin, 'Ring - Schimmerndes Tempo', verzaubert.", progress = "Die Verzauberung und der Ring, die ich Euch überlassen habe, passen zueinander. Ihr könnt aber auch eigene nutzen.", completion = "Möget Ihr so unbezwingbar sein wie die Erde selbst. Also, macht Euch auf, Fremdling!", sourceObjectiveStatus = "unverified-source-field" }
quests[83276] = { id = 83276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Soldat Spindel", description = "Eine meiner Weberatten hat sich ungewöhnlich lange nicht mehr gemeldet. Ich habe Spindel entsandt, um Informationen zu beschaffen, die wir gegen einen von Ansureks Günstlingen verwenden können, aber sie ist von ihrem Auftrag nicht zurückgekehrt.\n\nMeesk die Giftzunge ist ein Schuft und ein Kriecher, aber er ist trotzdem gefährlich. Obwohl ich großes Vertrauen in die Fähigkeiten meiner lieben Spindel habe, fürchte ich, was ein Übeltäter wie Meesk einer meiner Kleinen antun würde, sollte er sie finden.\n\nFindet Spindel. Und sorgt dafür, dass sie wohlauf ist.", sourceObjective = "Findet Spindel in den Hochhöhlen.", completion = "<Die kleine Spinne sieht Euch mit vielen flehenden Augen an. Ihr habt das Gefühl, dass sie nicht möchte, dass Ihr mit jemandem darüber sprecht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[83277] = { id = 83277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Persönlicher Diebstahl", description = "<Die kleine Spinne sieht sich im Raum um und jedes ihrer Augen verengt sich.\n\nIhr erinnert Euch, dass die Weberin Euch gebeten hat, Beweise zu beschaffen, um Meesk zu erpressen.\n\nAber es scheint, als ob das Durchwühlen von Meesks Lager für Spindel jetzt etwas Persönliches geworden ist.>", sourceObjective = "Findet 3 belastende Beweisstücke in Meesks Zuflucht.", progress = "Na, mein Häppchen? Habt Ihr etwas Bemerkenswertes gefunden?", completion = "Wie ich sehe, habt Ihr meine Spindel zurückgebracht. Und einige interessante Beweisstücke noch dazu.\n\nOffenbar hat dieser Halunke Meesk seine Vorgesetzten verleumdet, um die Gunst von Ansurek und ihresgleichen zu gewinnen. Seine Macht wächst nicht nur von Tag zu Tag, sondern geht auch auf Kosten des Vermächtnisses von Königin Neferess.\n\nAlso, das ist einfach nicht hinnehmbar. Kehrt bald zu mir zurück, mein kleines Häppchen. Ich brauche etwas Zeit, um unser weiteres Vorgehen auszuklügeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[83278] = { id = 83278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familie Hügelpinne: Ein verlorener Schuh", description = "<Ein Schuh in dem Stil, wie ihn die Familie Hügelpinne trägt. Vielleicht kann Aliya Hügelpinne mehr darüber erzählen.>", sourceObjective = "Bringt den verlorenen Schuh zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Addysen und ich sind früher barfuß durch diese Höhlen geschlichen. Wenn man leise auftrat, wachte der schlummernde Fungus nicht auf. Das klappte nicht immer, und wir haben auf der Flucht vor wütenden Peitschenpilzen eine Menge Schuhe verloren.\n\nAber dieser Schuh muss früher mal Gerta gehört haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[83279] = { id = 83279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mutprobe", description = "Ja, Ihr habt uns mit diesem Ungeziefer geholfen, aber das ist nicht genug. Ich brauche mehr.\n\nEines der Gebiete in der Nähe unserer Stadt ist von Schatten überrannt worden. Wenn Ihr wirklich nicht von Eurer... seltsamen Herkunft kontrolliert werdet, hättet Ihr doch kein Problem damit, die Quelle dieser Gefahr zu vernichten, oder?", sourceObjective = "Besiegt die Geronnene Sünde in Schmuggelstieg.", completion = "Ich gehöre seit meiner Geburt zur Kirche der Heiligen Flamme. Doktrin legt man nicht einfach so ab.\n\nAber ich sehe jetzt ein, dass Ihr hier seid, um zu helfen. Und solange Ihr Eure Kraft für uns einsetzt, reiche ich Euch meine Hand in Freundschaft - gleich, wo diese Kraft herkam.", sourceObjectiveStatus = "unverified-source-field" }
quests[83282] = { id = 83282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hügelpinnenfamilie: Ein Gelege", description = "<Ein Hühnergelege, das von einer nahen Farm stammen muss. Vielleicht kann Aliya Hügelpinne mehr darüber erzählen.>", sourceObjective = "Bringt das Gelege zu Aliya Hügelpinne am Hügelpinnenhof.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt das in einer Höhle in der Nähe gefunden? Wir haben ein paar abenteuerlustige Hühner, die müssen sich da hin verirrt haben.\n\nEs kann den ganzen Tag dauern, all die Ausreißer wieder einzufangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83283] = { id = 83283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Moral", description = "Bitte verzeiht, dass mein Mann so ungehobelt ist. Als wir uns für die Expedition meldeten, gingen wir davon aus, dass wir schlimmstenfalls einige Jahre von unseren Familien getrennt wären. Stattdessen ließen wir uns hier als Wachen nieder, gegen... nun, gegen das Ende, gegen Renilash. Wer weiß, wann unsere Wache endet?\n\nIch habe einen Vorrat an Wein von den Weinbergen unserer Kirche angelegt, damit sich alle bei einem guten Schluck beruhigen können, wenn die Spannungen zu groß werden. Jetzt wurde jedoch mein Versteck in Schmuggelstieg von Kreaturen überrannt. Könnt Ihr den Wein für mich holen?", sourceObjective = "Holt 6 Fässer Kaiserlicher Schaumwein aus Schmuggelstieg.", progress = "Stellt Euch 20 Arathi vor, die seit zehn Jahren im sicheren Schein eines einzigen Lichts aufeinander hocken. Stellt Euch vor, wie sehr sie sich danach sehnen, sich ab und zu bei einem feinen Schluck mit ihren Kameraden zu entspannen.\n\nUnd jetzt stellt Euch vor, was los ist, wenn sie hören, dass es keinen Wein mehr gibt.\n\n... Bitte beeilt Euch.", completion = "Oh, der Flamme sei Dank.\n\nIhr habt gerade noch einen Aufruhr verhindert. Seid gesegnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[83285] = { id = 83285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralte Schriftrolle", description = "Ein Dunstschleier scheint zunächst über den Einzelheiten der Schriftrolle zu liegen. Während Ihr Euch darauf konzentriert, ihre Merkmale zu entziffern, verschwindet der Dunst kurz und gibt eine makellose Schriftrolle aus dem feinsten Pergament frei, deren Siegel so frisch wirkt, als sei das Wachs sogar noch weich. Auf einmal fühlt sich die Rolle gefährlich brüchig an und das Siegel macht einen so empfindlichen Eindruck, als könnte es augenblicklich brechen. Dann bildet sich der Nebel wieder, und Ihr seht, wie die Schriftrolle durch alle möglichen Punkte zwischen diesen beiden Extremen wabert.", sourceObjective = "Schriftrollen sind wirklich faszinierend. Sie reisen durch das ganze Land, und diese hier scheint sogar durch die Zeit zu reisen.\n\nDass Ihr diese Schriftrolle genau dort gefunden habt, ist ein Omen und Segen zugleich.", sourceObjectiveStatus = "unverified-source-field" }
quests[83286] = { id = 83286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was unter Dornogal verborgen liegt", description = "Eigenartig. Der Mechanismus und diese Konsole werden mit Energie versorgt, aber die Neustartsequenz lässt sich nicht initialisieren.\n\nDagrans Bitte wird wohl warten müssen.\n\nMir ist es gelungen, die Bezeichnung der Einrichtung herauszufinden: die \"Kammer der Erinnerung\". Das führt mich zu der Annahme, dass meine ursprüngliche Theorie richtig war. Sie steht mit dem Archiv in Dornogal in Verbindung.\n\nVielleicht habt Ihr, da Ihr beide mit dieser Art von Titaneneinrichtung vertraut seid, mehr Glück, sie wieder zum Laufen zu bringen.", sourceObjective = "Führt einen Neustart des zentralen Hauptrechners in der Kammer der Erinnerung in Dornogal durch.", progress = "Nehmt Euch die Zeit, die Ihr braucht. Das ist schon seit Jahrtausenden hier. Ich bin mir sicher, dass es nicht verschwinden wird.", completion = "Ich habe nun Zugriff auf den Hauptrechner in der Kammer der Erinnerung.\n\nEs gibt hier eine Menge... aber alles ist fragmentiert. Es wird einige Zeit dauern, alles neu zu kompilieren.\n\nUnd ich fürchte, dass einige Daten beschädigt sein könnten und repariert werden müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83306] = { id = 83306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die wilden Tiere kampieren", description = "Einige meiner Leute haben ein paar Haranir gefunden, die eines ihrer Lager im Südwesten aufgebaut haben. Den Haranir fehlten wichtige Vorräte, also haben meine Leute ihnen ihre Hilfe angeboten. Aber ich mache mir Sorgen, wie sie dort zurechtkommen.\n\nWürdet Ihr nach ihnen sehen? Vergewissert Euch, dass wir gute Gastgeber für die Haranir sind... und dass niemand versehentlich jemanden gekränkt hat. Bitte.", sourceObjective = "Trefft Euch im Wildlager Ul'ar mit Orweyna.", completion = "Ihr schon wieder. Interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[83315] = { id = 83315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitung auf das Unbekannte", description = "Das wird ein langer Prozess werden. Ich fürchte, länger als Dragan hier auf den Inseln bleiben kann.\n\nAber vielleicht...\n\nEs gibt viele Relikte der Titanen, die ich als \"Schlüssel\" verwenden kann, um die Informationen im Hauptrechner zu entschlüsseln oder ihn zu reparieren. Das könnte den Prozess beschleunigen.\n\nDie Zeit wird es zeigen.\n\nIhr habt uns genug geholfen, {name}. Geht zurück zu Moira und erzählt ihr, was wir herausgefunden haben.", sourceObjective = "Kehrt zu Moira Thaurissan in Dornogal zurück.", completion = "Nun, ich weiß, wo ich Dragan finde, wenn er mir fehlt.\n\nEs ist schön, ihn so glücklich und in seinem Element zu sehen. Er macht mich stolz.\n\nDanke, dass Ihr ihm auf seinem Weg geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83321] = { id = 83321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Fledermäuse", description = "Hey. Die gnädige Dame hat eine Spur zu einer eigenartigen Fledermaus, die in den Wurmlanden herumflattert. \n\nDie Spione berichten, dass sie sich eher wie eine Person als wie eine Fledermaus verhält. Wir glauben, dass es sich um einen Druiden handeln könnte, aber er wird sich den Nerubern nicht absichtlich offenbaren.\n\nIhr habt eines dieser Gesichter, die die Leute zögern lassen, bevor sie zuschlagen. Geht hinaus und seht es Euch an.", sourceObjective = "Untersucht eine mögliche Druidensichtung.", completion = "Ihr! Euch brauche ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[83322] = { id = 83322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Morgenbringer: Die Schiffstaufe", description = "Das Flaggschiff der Arathi-Armada ist die Morgenbringer. Sie ist ein Zeugnis der Ingenieurskunst der Arathi und des Glaubens an die Heilige Flamme. Ihre Anwesenheit am Himmel von Heilsturz wird uns helfen, die Neruber zurückzudrängen, wenn sie das nächste Mal einen Angriff auf unsere Ländereien wagen.\n\nAls jemand, der uns in der Vergangenheit so sehr geholfen hat, seid Ihr herzlich zur Taufe der Morgenbringer eingeladen. Wenn Ihr für einen reibungslosen Ablauf sorgen könntet, wäre ich Euch persönlich sehr dankbar.", sourceObjective = "Helft beim reibungslosen Ablauf der Schiffstaufe im Dungeon 'Morgenbringer'.", completion = "Nun.\n\nDas lief so, wie man es für eine Zeremonie in Heilsturz erwarten konnte.\n\nDanke, dass Ihr hier wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[83324] = { id = 83324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seidener Faden", description = "Seid Ihr auf der Suche nach Arbeit? <Linny schaut Euch mit zusammengekniffenen Augen an.> Ich habe Gerüchte aus der Hauptstadt gehört. Ein Kollege der Weberin möchte Geschäftsbeziehungen mit dem Seidendistrikt aufbauen.\n\nDer neue Distrikt sollte für die Einwohner der Hauptstadt ein Neuanfang sein, aber die blassen Webpeitscher der Königin behandeln ihn wie ein Militärlager. Das kommt bei der Bevölkerung nicht gut an.\n\nTrefft Euch mit einer Neruberin namens Sum'latha vor dem Distrikt. Sie kann Euch über die Details aufklären.", sourceObjective = "Trefft Euch mit Sum'latha im Seidendistrikt.", completion = "Ihr müsst die Hilfe sein, die unsere \"gemeinsame Freundin\" entsendet hat. Willkommen im Seidendistrikt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83325] = { id = 83325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Menge Käfer", description = "General Anub'azal hat große Pläne für den Schwarmhof Rak-Ush in Gang gesetzt. Er will ihn wieder arbeitsfähig machen, damit er seinen Feldzug unterstützt.\n\nJedoch... habe ich so meine Vorbehalte, was die beiden Verantwortlichen angeht.\n\nKish'nal scheint ganz vernünftig zu sein, aber Vix'aron? \"Temperamentvoll\" wäre noch vorsichtig ausgedrückt. Man muss ihn vielleicht ein wenig... anstupsen.\n\nSucht Kish'nal in Rak-Ush auf und erkundigt Euch nach Anub'azals Befehlen.", sourceObjective = "Sprecht mit Kish'nal in Rak-Ush.", completion = "Ah, der General hat also einen Beobachter entsandt?", sourceObjectiveStatus = "unverified-source-field" }
quests[83326] = { id = 83326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Kerze", description = "Ihr seid gut im Kerzenziehen. \n\nWir haben noch eine letzte Aufgabe für Euch, Eure Kerzenheit! Eine letzte Aufgabe! Dann ist Schluss mit dem klebrigen Geschäft. \n\nGROSSE Kerze im Keller. Steinerne benutzen sie, um die Ratten von ihrem Honigsaft fernzuhalten. Wir keine Ratten! Wir Kobo-ooolde. \n\n<Eine unangenehme Pause entsteht.>\n\nNichts reimt sich auf Kobold, hm. \n\nBringt uns große Kerze!", sourceObjective = "Stehlt die letzte Kerze für den verdächtigen Schacht im Gasthaus von Gundargaz.", progress = "Kerzen! Kerzen! Kerzen!", completion = "Yeah! Juchuuu! Die Kerze! Die Große! \n\n...Ihr riechen Rauch?", sourceObjectiveStatus = "unverified-source-field" }
quests[83328] = { id = 83328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Analyseschnittstelle", description = "Das ist die Analyseschnittstelle.\n\nUm sicherzustellen, dass unsere Hauptprogrammierung intakt bleibt, wurden diese Konsolen installiert. Sie führen eine Reihe von Untersuchungen durch, um die Erinnerungsmatrizen frisch erweckter Irdener zu prüfen.\n\nAuch wenn Aurora Euch dazu ermutigen wird, so zu antworten, wie es Euch beliebt... Ich... Na ja, ich hoffe einfach, dass Ihr wahrheitsgemäß antwortet.\n\nFahrt fort, sobald Ihr bereit seid.", sourceObjective = "Schließt die Analysesequenz an der Analyseschnittstelle ab.", completion = "Wer war ich, wer bin ich und wer will ich sein?\n\nDas sind alles Fragen, die jeder Irdene ab sofort fragen darf.\n\nEs ist an uns, unser Schicksal und unseren Sinn im Leben zu wählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83329] = { id = 83329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufe 50" }
quests[83330] = { id = 83330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufe 60" }
quests[83331] = { id = 83331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewahren und Behumsen", description = "Schneif nach Geschichte graben. Ihr helfen finden?\n\nHaben Geschichtsdetektor von Goblin. Sagen, Geschichte unter Erde zu finden! Ihr einsetzen. Schneif graben.", sourceObjective = "Helft dabei, Orte zu finden, wo man nach \"historischen Objekten\" graben kann, indem Ihr den Goblin-\"Geschichtsdetektor\" einsetzt.", completion = "Viele Danke, Grabe-Finder.\n\nSchneif wissen, diese nicht haben wichtige Geschichte... aber irgendwann haben werden.\n\nSchneif sie bis dahin sicher aufbewahren. Kobolde machen neue Geschichte. \n\nDann retten und schützen. Für immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[83333] = { id = 83333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Sachen Probleme einen Gang hochschalten", description = "Seid gegrüßt.\n\nDie Maschine ist erneut reparaturbedürftig.\nIch brauche Eure Expertise, um die Wartungsarbeiten erfolgreich abschließen zu können.\n\nWenn Ihr Euch gut anstellt, ist für Euch auch eine Belohnung drin.", sourceObjective = "Schließt 20 Wellen des Ereignisses \"Erweckung der Maschine\" ab.", progress = "Statusbericht?", completion = "Die Maschine geht wieder ihrer Arbeit nach.\n\nDanke für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[83334] = { id = 83334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reichtum eines Reichs", sourceObjective = "Die Arathi wissen Eure Hilfe in diesen gefährlichen Landen wirklich zu schätzen. Nehmt dies bitte als Zeichen unserer Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[83335] = { id = 83335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: der Gemeindebrecher", description = "<Diese Notiz ist mit einer kleinen Chitinplatte an den Pfosten genagelt.>\n\nFür Verbrechen gegen die Edikte von Dornogal hat der Rat eine Belohnung für jene ausgeschrieben, welche die in Chitin gepanzerte Bestie namens Stik'kar erschlagen.\n\nEine Probe von Stik'kars Panzer liegt bei. Wenn Ihr diese nicht beschädigen könnt, wird Euch geraten, weiter Euren Pflichten nachzugehen und diese Aufgabe jemand anderem zu überlassen.", sourceObjective = "Tötet Gemeindebrecher Stik'kar auf der Insel von Dorn.", progress = "Tragt Euren Teil bei, Abenteurer. Ich muss meine Pflicht tun.", completion = "Der Rat kann sich so viel streiten, wie er will. Die wahren Helden sind die, die ausziehen und die Welt sicherer machen. Ich danke Euch, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[83336] = { id = 83336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erdwunde", description = "<Etterca grummelt, als Ihr Euch nähert.>\n\nDer Boden bebt. Nicht gut.\n\nAll der Ärger erweckt schon wieder die Elemente. Befleckt sie mit Verderbnis. Gefahr für uns alle. Bringt ihnen Manieren bei und bringt das Herz her.\n\nErst dann kann die Erde heilen. Nur dann kann Etterca ihre Pflicht tun.", sourceObjective = "Erlangt das zerbrochene Steinherz von Roth der Erdwunde auf der Insel von Dorn.", progress = "<Etterca grummelt und starrt Euch ausdruckslos an.>", completion = "Hmmpf. Zerbrochenes Herz zu reparieren dauert lange.\n\nEtterca hört Euch, Roth. Erde wird heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83337] = { id = 83337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmvernarbt", description = "Seht Euch in dieser schönen Stadt um. Was seht Ihr? Viehzüchter und ihre Mooswollen. Aber wo ist die Herde dieses Viehzüchters? Im Magen einer Bestie. Sturmnarbe nennen sie ihn.\n\nSturmnarbe, dessen Heulen wie der Donner ist. Dessen Biss ein Blitzschlag ist. Dessen Bauch voll von meinem Lebenswerk ist.\n\nIch bin gekommen, um Waffen zu kaufen, und wir haben nichts als Bauernwerkzeug. Ihr seht stark aus. Würdet Ihr Sturmnarbes Herrschaft über unsere Weiden ein Ende setzen?", sourceObjective = "Erschlagt Sturmnarbe in den Weiden nahe Bummelgau auf der Insel von Dorn.", progress = "Habt Ihr es schon geschafft?", completion = "Ich danke Euch, Abenteurer. Meine Rolle in dieser Welt ist es, Viehzüchter zu sein. Eure ist es, Wölfe zu erschlagen. Wir haben jeder unseren Platz.", sourceObjectiveStatus = "unverified-source-field" }
quests[83338] = { id = 83338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Magiertöter", description = "Ich gebe zu, ich bin aus einem guten Grund hier. Es gibt ein Wesen, dass womöglich noch da draußen ist und nicht in Freiheit bleiben darf.\n\nEin Gefangener der Violetten Festung, den wir widerwillig den Magiertöter nennen. Ich bin gekommen, um diese Leute um Hilfe zu bitten, aber sie sind Viehzüchter und Bauern. Ich hoffe, Ihr seid für diese Herausforderung besser ausgerüstet.\n\nSucht dieses Monster und setzt seinem Dasein ein Ende.", sourceObjective = "Erschlagt Magiertöter Phytethil nahe Bummelgau auf der Insel von Dorn.", completion = "Dalaran mag in Trümmern liegen, aber die Kirin Tor gewähren Euch keine Freiheit, Magiertöter!\n\nVielen Dank für Eure Hilfe, {name}.\n\nSeid Ihr sicher, dass Ihr sie alle besiegt habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[83339] = { id = 83339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spitzenbrecher", description = "Angriffe der Neruber sind für uns nicht ungewöhnlich. Die Kirin Tor sind gut gewappnet, sich einer solchen Bedrohung zu stellen. Dalaran...\n\nWar gewappnet. Ich kann nicht alle Feinde dieser Stadt abwehren, aber Ihr könntet dazu in der Lage sein. Ich habe auf dem Weg hierher einen Hinterhalt bemerkt. Eine sehr vertraute Taktik eines sehr vertrauten Feindes. Geht und löst die Falle aus, um das Monster zu töten, das sich darunter verbirgt.", sourceObjective = "Tötet Anub'esska auf der Straße bei Bummelgau auf der Insel von Dorn.", progress = "Sind sie jetzt in Sicherheit?", completion = "Ein Glück. Mit Eurer Hilfe werden wir vielleicht Erfolg haben... diesmal. \n\nDiese Leute verdienen Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[83345] = { id = 83345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Aufruf zur Schlacht", description = "Ich habe gehört, Euer Volk führt riesige Schlachten gegeneinander, auf riesigen Feldern und in verfallenen Ruinen. \n\nEs kommt mir ein bisschen wie Zeitverschwendung vor, sich um Flaggen zu streiten, wo es doch richtige Arbeit zu tun gibt. Aber das Schlachtfeld kann den Mut eines Kriegers auf die Probe stellen. Das hat seinen Wert.\n\nBringt mir Nachrichten über Eure Siege! Ich lasse mich gern beeindrucken.", sourceObjective = "Gewinnt 4 Schlachtfeldpartien.", progress = "Für uns Maschinenflüsterer ist eine Feuerprobe nichts Neues. So kann man lernen, im Team zu arbeiten, und Strategien ausprobieren.", completion = "Ihr kehrt mit Neuigkeiten von Siegen zurück? Vielleicht auch von Niederlagen?\n\nJeder Verlust ist eine Lektion zur Verbesserung. Feiert auch Eure Siege.", sourceObjectiveStatus = "unverified-source-field" }
quests[83347] = { id = 83347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter des Krieges", description = "Seid Ihr bereit für eine echte Herausforderung? Taucht ein in die dunkelsten Tiefen und erhebt Euch in die höchsten Höhen, während die Herausforderung schwieriger wird. \n\nWenn wir uns bis zum Äußersten anstrengen, können wir unsere Fertigkeiten wirklich testen.", sourceObjective = "Schließt 4 Dungeons auf dem Schwierigkeitsgrad 'Mythisch' ab.", completion = "Das war keine leichte Aufgabe, die Ihr da bewältigt habt. Ich bin mäßig beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83357] = { id = 83357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Besten der Besten", description = "Das Band zwischen uns und unseren Maschinen ist ähnlich wie das, das andere mit ihren Haustieren haben. Man muss mit seinen Gefährten harmonieren, um Großes zu vollbringen!\n\nZeigt mir, dass Ihr mit Euren Haustieren im Team arbeiten könnt. Besiegt Eure Feinde mit ihrer Hilfe!", sourceObjective = "Besiegt 5 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", completion = "Ihr und Eure Haustiere seid ein schwer zu schlagendes Team!", sourceObjectiveStatus = "unverified-source-field" }
quests[83358] = { id = 83358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arena ruft", description = "Habt Ihr Euren Mut in der Arena unter Beweis gestellt? Wenn Ihr genügend Schlachten gewinnt, haben Eure Geschichten vielleicht eines Tages einen Platz in den Archiven verdient.", sourceObjective = "Gewinnt 10 Arenageplänkel.", completion = "Gut gemacht! Ihr seid mit Eurer Ausbildung auf dem richtigen Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[83359] = { id = 83359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verwüsteter Pfad durch die Zeit", description = "Einer Eurer Leute hat mir eine seltsame Geschichte über den Kataklysmus erzählt, der Azeroth zerstört hat. In Euren Ländern wurde dies durch die Machenschaften der bösen Kreatur Todesschwinge am schlimmsten empfunden. \n\nReist durch Raum und Zeit und kämpft gegen ihn und andere Bedrohungen.", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", completion = "Das Echo des Kataklysmus war in ganz Azeroth zu spüren. Es war in der Tat eine schreckliche Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[83360] = { id = 83360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein teuflischer Weg durch die Zeit", description = "Ich habe Geschichten über eine ganze Legion von Bedrohungen gehört, die auf den Pfaden von Raum und Zeit lauern. \n\nBesiegt sie und berichtet mir von ihrer Vernichtung.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Habt Ihr die Brennende Legion vernichtet? Nach allem, was ich gehört habe, haben sie nichts anderes verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[83362] = { id = 83362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verschleierter Pfad durch die Zeit", description = "Einer Eurer Leute hat mir Geschichten über Pandaria erzählt! Eines Tages würde ich sehr gern durch die Lüfte dort fliegen. \n\nWandelt durch Nebel und die Zeit und berichtet mir von Euren Taten.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, Ihr kehrt nass vom Nebeltau zurück. Ich höre, Ihr bringt Neuigkeiten von Euren Siegen in Pandaria.", sourceObjectiveStatus = "unverified-source-field" }
quests[83363] = { id = 83363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein brennender Pfad durch die Zeit", description = "Euer Volk hat mir Geschichten von einem dunklen Portal erzählt, in dem viele Feinde und Herausforderungen lauern. Ich würde gern mehr davon hören.\n\n Reist durch Zeit und Raum zu diesem seltsamen Ort, besiegt die Feinde dort und berichtet mir von ihrer Vernichtung.", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", progress = "Einige meiner Leute mögen die Ankunft der Fremden als Invasion betrachten, aber ich bin froh, dass Ihr auf unseren Schuhen gelandet seid, und nicht die Brennende Legion.", completion = "Ihr kehrt ruhmreich zurück und bringt mir Geschichten darüber, wie Ihr die Feuer der Brennenden Legion gelöscht habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[83364] = { id = 83364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wilder Pfad durch die Zeit", description = "Seit Eure Stadt vom Himmel gefallen ist, habe ich mehr über die Geschichte dieser Welt und die Herausforderungen gelernt, denen sich Helden wie Ihr gestellt haben. \n\nWenn wir aus der Vergangenheit lernen, können wir unsere Zukunft sichern. Reist durch die Zeit in eine vom Höllenfeuer gezeichnete Vergangenheit, um diese Bedrohungen noch einmal zu besiegen und diese Lektionen weiterzugeben.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ihr seid zurückgekehrt, und unsere Realität hat sich nicht aufgelöst, also nehme ich an, Ihr wart erfolgreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[83365] = { id = 83365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefrorener Weg durch die Zeit", description = "Seit Eure Stadt vom Himmel gefallen ist, habe ich mehr über die Geschichte dieser Welt und die Herausforderungen gelernt, denen sich Helden wie Ihr gestellt haben. \n\nWenn wir aus der Vergangenheit lernen, können wir unsere Zukunft sichern. Reist durch die Zeit in die gefrorene Vergangenheit, um diese Bedrohungen noch einmal zu besiegen und diese Lektionen weiterzugeben.", sourceObjective = "Besiegt 5 Zeitwanderungsschlachtzugsbosse oder Zeitwanderungsdungeons.", progress = "Während wir hier gearbeitet haben, ist in der großen Welt viel passiert. Ich habe gehört, Ihr hattet bei einigen dieser Geschichten die Hand im Spiel.", completion = "Welche Lektionen bringt Ihr von Euren Reisen durch die Zeit mit?", sourceObjectiveStatus = "unverified-source-field" }
quests[83366] = { id = 83366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welt wartet", description = "Vielleicht können wir Eure Tragödie in eine für uns beide vorteilhafte Erfahrung verwandeln. Es gibt viel, was Ihr tun könnt, um den Irdenen eine Hilfe zu sein. \n\nHelft mit, wo Ihr nur könnt.", sourceObjective = "Schließt 10 Weltquests in Khaz Algar ab.", progress = "Mein Volk sieht sich zurzeit mit einer Vielzahl von Herausforderungen konfrontiert, genau wie Euer Volk. Machen wir das Beste aus dem, was uns beiden widerfahren ist.", completion = "Ich habe von Euren Taten in meinem Volk gehört. Euer Name ist bei den Irdenen in aller Munde.", sourceObjectiveStatus = "unverified-source-field" }
quests[83417] = { id = 83417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschwägert", description = "Wir sind eine traditionelle Goblinfamilie und der Zukünftige meiner Süßen kommt auch aus so einer. Junge Leute fangen an, unter Vertrag zu arbeiten und kaufen sich gegenseitig frei, wenn sie heiraten, damit sie freie Zeit bekommen.\n\nIch hab die Kohle, mit der meine Süße den Vertrag ihres Zukünftigen auslösen kann, aber es wäre... peinlich, wenn ihr Zukünftiger nicht die Knete für den Vertrag meiner kleinen Zuckerschnute hätte, versteht Ihr?\n\nSprecht mit dem Kleinen und sorgt dafür, dass er für den großen Tag frisch ist. Ist er es nicht, bringt es in Ordnung.", sourceObjective = "Sprecht mit Vrizek und sorgt dafür, dass er das Vertragshonorar hat.", progress = "Alles muss für den großen Tag meines Mädels perfekt sein. Sonst knallt's.", completion = "Ich dachte mir schon, dass so was passieren würde. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[83418] = { id = 83418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der perfekte Mantel", description = "Meine Prinzessin verdient nur das Beste, was Azeroth zu bieten hat - und das gilt insbesondere für ihre Kleider. Woher soll'n die Leute sonst wissen, für wie unglaublich ich sie halte?\n\nIch hab da jemanden, der mir 'nen seltenen und fantastisch'n Pelz für mein kleines Mädchen besorgt, aus dem sich ein fabelhafter Mantel schneidern lässt. Geht zu ihm und holt mir die Ware. Und achtet darauf, dass sie nicht versaut wird.", sourceObjective = "Beschafft das Material für den fabelhaften Federmantel.", progress = "Tick, tack!", completion = "Hey, das ist aber elegant! Meine Teure wird fantastisch in dies'n Federn ausseh'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[83419] = { id = 83419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Gästeliste", description = "Eine perfekte Hochzeit hat eine perfekte Gästeliste!\n\nDoch ich warte noch auf die Rückmeldung zu ein paar Einladungskarten. Papa sagte, er würde dafür sorg'n, dass sie auftauchen, also müsst Ihr sie daran erinnern, dass sie sehr gerne zu meiner Hochzeit kommen werden. Das wird die größte Sause, die diese Stadt je erlebt hat! Warum sollten sie nicht kommen woll'n? Wir sind eine Familie! Großteils.\n\nWie dem auch sei, sorgt dafür, dass alle auf dieser Liste sich bereiterklär'n, zu meiner Hochzeit zu kommen. Erinnert sie daran, dass Papa gesagt hat: \"Sonst knallt's.\"", sourceObjective = "Holt positive Rückmeldungen von den verbleibenden Gästen ein.", progress = "Habt Ihr schon mit allen Faulpelzen in meiner Verwandtschaft gesprochen? Ich muss die Tische organisieren.", completion = "Hervorragend! Endlich kann ich die Tischordnung fertigstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83420] = { id = 83420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfektes Catering", description = "Mein perfekter Tag braucht das perfekte Menü! Ich hab mir ein paar Sachen auf Mampfstagram angesehen und Küchenmeister Hartschnitt ist der Einzige, den ich haben will. Papa hat mir versprochen, dass ich den Besten kriege, und er hält sein Wort!\n\nIhr müsst dafür sorgen, dass alles auf meiner Speisekarte auch auf den Tischen landet, damit wir perfekte Bilder bekommen. Alle sollen sehen, wie fabelhaft meine Hochzeit ist.\n\nAhh! Ich bin so aufgeregt! Ich kann's kaum erwarten, die Kreationen von Küchenmeister Hartschnitt auf den Tischen meiner Hochzeit zu erleben!", sourceObjective = "Sprecht mit Küchenmeister Hartschnitt und beschafft fehlende Zutaten.", progress = "Ist Küchenmeister Hartschnitt nicht ein Genie?", completion = "Alle werden mich um mein Essen beneiden!", sourceObjectiveStatus = "unverified-source-field" }
quests[83421] = { id = 83421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Hochzeit", description = "Ich hab ein paar Schläger angeheuert. Die sollen die Hochzeit überfallen. Das passiert doch nur den besten Hochzeiten, oder?\n\nAber ich will mein Pfand für die Location zurückbekommen. Deswegen sorgt dafür, dass diese Schläger nicht alles kurz und klein schlagen, verstanden?", sourceObjective = "Verhindert, dass die ungebetenen Gäste den Veranstaltungsort zu sehr demolieren.", completion = "Hey! Ich kriege mein Pfand zurück. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[83432] = { id = 83432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brutstätte", description = "Meine Kontakte in der Nähe von Dornogal haben mich angewiesen, das geheim zu halten, aber ich vertraue Euch. Vor allem, weil ich jemanden brauche, der diesen Auftrag für mich erledigt.\n\nWir haben ein Problem innerhalb der Mauern der Brutstätte - einen Ausbruch der Skardyn.\n\nIch brauche jemanden, der die Brutstätte von den Skardyn befreien, die Quelle des Ausbruchs finden und mit einem Felsbrocken versiegeln kann.\n\nSobald Ihr diese Mission abgeschlossen habt, könnt Ihr Euch bei mir Eure Belohnung abholen.\n\nUnd vergesst nicht... das bleibt unter uns.", sourceObjective = "Biergoth möchte, dass Ihr die Brutstätte betretet und die Skardynbedrohung beseitigt.", progress = "Schon zurück? Ich hoffe doch, Ihr habt gute Neuigkeiten?", completion = "Gut gemacht. Ihr seid jetzt offiziell mein Lieblingsheld. \n\nZumindest bis morgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83436] = { id = 83436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metbrauerei Glutbräu", description = "Ich habe Nachricht von einem meiner Kontakte namens Wenbrandt bekommen. Ihr habt möglicherweise von ihm gehört. Er betreibt die Metbrauerei Glutbräu.\n\nEr sagt, dass Goblins, die zu einer Organisation gehören, die sich selbst Venture Company nennt, versuchen, die Brauerei zu übernehmen. Wir können das nicht zulassen. Deshalb müsst Ihr die Brauerei infiltrieren und diese Gefahr beseitigen.\n\nGlutbräu ist ein Luxusgut der Irdenen und muss in den Händen der Irdenen bleiben. Wenbrandt wird ihnen diese Lektion erteilen, aber bis dahin verlasse ich mich darauf, dass Ihr diesen Auftrag erledigt.", sourceObjective = "Biergoth möchte, dass Ihr die Venture Company aus der Metbrauerei Glutbräu vertreibt.", progress = "Schlechte Nachrichten sind besser als überhaupt keine Nachrichten. \n\nLasst mich nicht warten. Ich habe nicht die Geduld eines Berges, sondern die eines Felssturzes.", completion = "Wenbrandt hat mich benachrichtigt. Gut gemacht. \n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[83442] = { id = 83442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geworfen und gedreht", description = "All meine Notizen. Meine Pläne!\n\n<Schnapp zittert vor Wut.>\n\nIch weiß genau, dass Mite Glanzritzel meine Wohnung durchwühlt hat. Er ist mein Rivale auf der Arbeit und wollte bestimmt meine neueste Erfindung stehlen - den Superriecher 5000!\n\nDas ist ein Zubehörteile für die Grills, die wir entwerfen. Ich hatte gerade den Bauplan für unseren Chef fertiggestellt und wollte raus, was essen gehen. Und als ich zurückkehrte...\n\nVielleicht hat er ihn nicht gefunden. Helft mir zuerst bei der Suche, dann kümmern wir uns um Mite.", sourceObjective = "Durchsucht die Wohnung von Schnapp Schmierpergament in Lorenhall nach dem Bauplan.", progress = "Das ist ein Bauplan von einem Abluftteil, das auf einen Grill gesteckt wird. Er ist so fantastisch, dass Ihr ihn gar nicht verfehlen könnt!", completion = "<Schnapp zerknüllt den ihn verhöhnenden Zettel.>\n\nOh, diesmal klaut er mir nicht die Beförderung!", sourceObjectiveStatus = "unverified-source-field" }
quests[83443] = { id = 83443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelflammenspalt", description = "Ein neuer Verbündeter, ein Kobold aus den Schallenden Tiefen namens Krabbler, hat mich kontaktiert.\n\nIhr müsst für mich zum Dunkelflammenspalt gehen und eine gewisse Bedrohung beseitigen, die Krabbler nur als \"Die Finsternis\" bezeichnet hat.\n\nWie kann ein Kobold Angst vor der Finsternis haben, wenn sie den Großteil ihrer Zeit unter Tage verbringen? Das ergibt für mich keinen Sinn. Aber Kobolde sind Kobolde, und ich werde meine Zeit nicht mit Verständnis verschwenden.", sourceObjective = "Biergoth möchte, dass Ihr in den Dunkelflammenspalt reist und Euch der Finsternis stellt.", progress = "Lasst es mich wissen, wenn Ihr herausfindet, was es mit dieser Finsternis auf sich hat.", completion = "Die Finsternis ist also ein Koboldwesen? Und ich dachte, Krabbler übertreibt einfach.\n\nHier ist Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[83445] = { id = 83445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier stinkt was", description = "Uh! Dieser Mite macht mich so wütend! Er hat dafür sogar die Lorbeeren eingeheimst. Und recht hatte ich! Er wird den Superriecher unserem Chef präsentieren!\n\nWahrscheinlich macht er das genau in diesem Moment!\n\nAber da fällt mir was ein. Wir haben zwar den Bauplan nicht, aber Mite wird nicht wissen, wie man das Teil bedient. Wenn wir dem Chef zeigen können, dass Mite es nicht entworfen hat, bekomme ich vielleicht doch meine Anerkennung!\n\nWie gut seid Ihr im Drücken von Knöpfen? Helft Ihr mir, den Prototypen zu präsentieren?", sourceObjective = "Sprecht mit Schnapp Schmierpergament bei Billogrills in Bruchbudenhügel.", progress = "Wir müssen uns beeilen! Mite hatte fast eine Stunde Zeit, sich vorzubereiten.\n\nWährend ich in der Pause war. Dieser Idiot!", completion = "Dieser Tunichtgut von einem hirnlosen Bratwurm eines Ingenieurs!\n\nDafür wird er bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83446] = { id = 83446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abmahnung", description = "Unsere Präsentation hat gezeigt, dass wir die Einzigen sind, die das Gerät bedienen können! Wenn Sammy nicht so besessen von der Idee wäre, dass die Dokumentation bei Mite ist... Jeder andere würde uns glauben, dass wir das Ding hergestellt haben, auch wenn wir den Bauplan nicht mehr haben!\n\nAber diese Sache ist noch nicht vorbei. Habt Ihr bemerkt, wie Mite den Superriecher überladen hat? Das können wir auch! Drückt einfach mehrere Knöpfe auf einmal, dann können wir seine unausgegorene und geklaute Idee zu unseren Gunsten nutzen!\n\nWir gehen rein, machen den Prototypen kaputt und werfen die Produktion um Monate zurück!", sourceObjective = "Haltet die Produktion des Superriecher 5000 bei Billogrills in Bruchbudenhügel auf.", progress = "Mite... könnte da durchaus rechthaben.", completion = "Oh, äh. Hi, {name}. Danke, dass Ihr diese kaputten Prototypen für uns zerfetzt habt. Hier ist Euer Anteil.\n\nDas hat sich alles als ein großes Missverständnis herausgestellt. Er ist eingebrochen, weil er dachte, ich hätte SEINE Idee gestohlen.\n\nUnd ihm ist auch was Gutes für den Superriecher... Duftifizierer... oder was auch immer eingefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83457] = { id = 83457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Steingewölbe", description = "Ich habe einen Auftrag für Euch von der Obersten Sprecherin Brinthe persönlich.\n\nDie Skardyn-Verderbnis breitet sich im Steingewölbe aus. Oberste Sprecherin Brinthe benötigt Hilfe, um die Panik einzudämmen. Ich habe ihr gesagt, dass sie sich auf uns verlassen kann wie auf das Grundgestein unter unseren Füßen.\n\nGeht zum Steingewölbe und beseitigt die Skardyn-Verderbnis. Gebt Bescheid, wenn die Sache erledigt ist.", sourceObjective = "Biergoth möchte, dass Ihr die Skardyn-Verderbnis im Steingewölbe beendet.", progress = "Bringt Ihr Neuigkeiten, die ich der Obersten Sprecherin Brinthe melden kann?", completion = "Ihr seid in der Tat wie das Grundgestein – solide und zuverlässig.\n\nIch werde der Obersten Sprecherin Brinthe von Eurem Erfolg berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[83458] = { id = 83458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorat der Heiligen Flamme", description = "Schön, Euch zu sehen, {name}. Ich habe einen Auftrag für Euch.\n\nSchwester Etna Feuersbrynst von den Arathi ist überzeugt, dass im Priorat der Heiligen Flamme etwas nicht stimmt. Sie hat nichts Genaueres über diese Angelegenheit gesagt.\n\nBitte begebt Euch zum Priorat der Heiligen Flamme und findet die Schwester. Ich habe ein komisches Kieselchen im Magen, das mir sagt, dass sie recht haben könnte und Eure Hilfe benötigt.", sourceObjective = "Biergoth möchte, dass Ihr Euch zum Priorat der Heiligen Flamme begebt und Schwester Etna Feuersbrynst helft.", progress = "Ich bin nicht sicher, ob Ihr immer noch hier oder bereits wieder da seid.", completion = "Manchmal muss man nur auf sein Kieselchen im Magen hören.\n\nHier, eine Belohnung für Eure Zeit und Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[83459] = { id = 83459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Morgenbringer", description = "Ich habe Nachricht von Generalin Stahlstoß von den Arathi bekommen. Sie bittet Euch darum, an einer Zeremonie an Bord der Morgenbringer teilzunehmen.\n\nUnd mit \"teilnehmen\" meint sie, dass sie ein zusätzliches Paar Augen braucht - also zwischen zwei und fünf. Habt Ihr schon einmal eine Zeremonie bewacht? Das fühlt sich an wie eine Pfütze aus klebrigem Schlamm in den Schmiedegründen.\n\nEs tut mir leid, aber Generalin Stahlstoß hat mich darum gebeten, und ich habe mit einem einfachen \"Ja\" geantwortet. Wie heißt es: Nicht alle Hügel sind aufregend.", sourceObjective = "Biergoth möchte, dass Ihr zur Morgenbringer geht und Generalin Stahlstoß helft, die Zeremonie zu beschützen.", progress = "Ich weiß, dass Zeremonien nicht dein Glutbräu sind. Meins auch nicht, aber dein Auftrag ist wichtig.", completion = "Ich habe gehört, dass die Zeremonie eher an eine Schlammlawine als an eine klebrige Pfütze erinnerte. \n\nIch bin froh, dass Ihr dort wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[83465] = { id = 83465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ara-Kara, Stadt der Echos", description = "Tulumun, ein Agent eines neuen Kontakts, der als \"der Wesir\" bekannt ist, hat sich an uns gewandt.\n\nIch hätte nie erwartet, dass ein Neruber uns um Hilfe bitten würde, aber was er uns erzählt hat, könnte uns alle bedrohen.\n\nIhr müsst für mich nach Azj-Kahet hinabsteigen und Aka-Kara, die Stadt der Echos, infiltrieren. Wenn es stimmt, was Tulumun mir erzählt hat, darf das, was sie da unten gewoben haben, nicht in die Außenwelt entkommen.\n\nSetzt ihrem Treiben ein Ende und bringt mir Beweise.", sourceObjective = "Biergoth möchte, dass Ihr den Betrieb in Ara-Kara stoppt.", progress = "Macht schnell. Ihr Vorhaben darf keine Früchte tragen.", completion = "Schwarzblut? Ich bin mir nicht sicher, was das ist, aber wenn ein Neruber es bösartig nennt, nehme ich ihn beim Wort.\n\nHier, das ist für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83469] = { id = 83469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stadt der Fäden", description = "Tulumun, unser nerubischer Verbündeter, hat uns erneut kontaktiert. Er sprach von einem Ort namens Transformatorium, an dem grauenvolle Experimente stattfinden.\n\nIch möchte, dass Ihr die Stadt infiltriert. Anschließend müsst Ihr Euch mit dem Wesir treffen, um den Rest der Mission zu erhalten. \n\nEliminiert die Feinde des Wesirs, beendet die Bedrohung und kehrt zu mir zurück, um Eure Bezahlung zu erhalten.", sourceObjective = "Biergoth möchte, dass Ihr alle Gefahren in der Stadt der Fäden eliminiert.", progress = "Macht schnell. Ich will nicht, dass Ihr mehr Zeit in einer nerubischen Stadt verbringt als notwendig.", completion = "Ich weiß nicht, ob ich diesen Nerubern traue - noch nicht. \n\nIhre Fähigkeit, bösartige Verschwörungen auszubrüten, und diese Einrichtungen, die ihre dunkelsten Pläne unterstützen... es erschüttert mein Innerstes.", sourceObjectiveStatus = "unverified-source-field" }
quests[83484] = { id = 83484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elendige Ratten!", description = "Okay, Pfadfinderehrenwort: Das ist kein Witz, ich brauche Hilfe, weil...\n\nIch habe meine beste Freundin in eine Ratte verwandelt.\n\nMeine Freundin Allie ist hier die Köchin. Sie gibt ihr Bestes, aber... sie kann nichts. Sie hat Probleme mit dem Schnuppern. Deswegen habe ich ihr einen Trank gekauft, damit sie besser riecht!\n\nIch meine, damit ihr Geruchssinn verbessert wird. Aber er hat sie in eine Ratte verwandelt! Und sie ist weggelaufen!\n\nIhr müsst sie für mich finden. Der Händler hatte noch einen Trank, mit dem man Ratten versteht. Ich trau mich aber nicht, ihn zu trinken.\n\nKönntet Ihr das tun und sie finden?", sourceObjective = "Findet Alice Grillfunken.", completion = "Ich kann nicht auf ewig eine Ratte bleiben. Ich brauche Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[83485] = { id = 83485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirksame Tränke", description = "<schnupper> <schnupper>\n\nDieser Trank riecht nach den Bottichwerken. Am Nordrand gibt es einen Händler, der Tränke verkauft. Der hier muss von ihm stammen. Wenn Ihr ihn findet, könnt Ihr ihn vielleicht überreden, ein Gegenmittel rauszurücken.\n\nBitte helft mir. Außer Euch versteht mich doch niemand!", sourceObjective = "Helft Alice Grillfunken.", completion = "Wenn Ihr das lest, bin ich gerade draußen und durchforste die Kaja'Küste nach Reagenzien. \n\nWenn Ihr hier seid, um Schulden einzutreiben, dann seid Ihr ein EINDRINGLING und müsst diese Nachricht ignorieren.\n\n- Getry", sourceObjectiveStatus = "unverified-source-field" }
quests[83486] = { id = 83486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimarbeit", description = "Wenn Ihr das lest, bin ich gerade draußen und durchforste die Kaja'Küste nach Reagenzien. \n\nWenn Ihr hier seid, um Schulden einzutreiben, dann seid Ihr ein EINDRINGLING und müsst diese Nachricht ignorieren.\n\n- Getry", sourceObjective = "Findet Getry Verkaufwohl an der Kaja'Küste in Zandalar.", completion = "<Hier in der Gegend müssen doch irgendwo Rotbeeren wachsen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[83487] = { id = 83487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufsrisiko", description = "<Ihr vermutet, dass das Sammeln von genügend Rotbeeren, die Ihr dann Humphrey übergebt, Alice wieder in ihre normale Goblingestalt verwandeln müsste.>", sourceObjective = "Sammelt die Rotbeeren-Reagenzien und bringt sie Humphrey.", progress = "Hattet Ihr Glück mit dem Gegenmittel, {name}?", completion = "Danke noch mal für das Gegenmittel. Wir bewahren es für später auf.\n\nAlice kann jetzt viel besser kochen als vorher und möchte diese Erfolgsgeschichte ausweiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[83489] = { id = 83489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Gladiatoren versammeln!", description = "Hört, hört! Seht her! Kommt alle nach Dornogal!\n\nZusätzlich zur gewohnten Auswahl an mächtiger Ausrüstung, die am Rivalentor angeboten wird, können aufstrebende Kämpfer und erfahrene Gladiatoren auch Wappenmarken kaufen, die zur Herstellung von Ausrüstung verwendet werden können, die in Arenen und auf Schlachtfeldern zugelassen ist!\n\nReicht diese Broschüre bei Hotharn ein, um ein paar davon zu erhalten - kostenlos, aufs Haus!\n\n- Aisha", sourceObjective = "Gebt die Broschüre bei Hotharn am Rivalentor in Dornogal ab.", completion = "Ah, ich hatte mich schon gefragt, wann die ersten eifrigen Kämpfer auftauchen werden. \n\nHier, nehmt das, wie versprochen. Benutzt sie, wenn Ihr Handwerksaufträge einreicht oder Eure eigene Ausrüstung herstellt. Das Ergebnis wird genauso mächtig sein wie das, was Lalandi da drüben verkauft, aber diese Teile sind großartig, wenn Ihr etwas Individuelles möchtet, das auf Eure Bedürfnisse abgestimmt ist. Wenn Ihr mehr braucht, wisst Ihr, wo Ihr mich findet.\n\nFragen? Hebt sie Euch für die Schmiedegründe auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[83492] = { id = 83492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmeuten: Gemeinsame Kriegsmeute", description = "{name}, einige Abenteurer haben sich zu einer Kriegsmeute zusammengeschlossen und könnten Eure Hilfe gebrauchen.\n\nFindet Blau und ihre Truppe in Gadgetzan.", sourceObjective = "Trefft Blau und ihre Kriegsmeute in Gadgetzan.", completion = "Ich danke Euch für Euer Kommen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[83493] = { id = 83493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmeuten: Rissleser", description = "Ich wette, Ihr fragt Euch, woran wir arbeiten, hm? Wir machen den Zugriff auf unsere Kriegsmeutenbank von überall möglich!\n\nNieti nennt es den Entfernungshemmer der Kriegsmeutenbank, bis mir ein spaßigerer Name einfällt. Allerdings brauchen wir ein wenig Hilfe bei der Fertigstellung.\n\nUm dafür zu sorgen, dass wir von verschiedenen Orten auf unsere gemeinsamen Vorräte zugreifen können, brauchen wir Portale! Und wir haben hier unten ein paar ungewöhnliche Teile aufgespürt.\n\nWenn Ihr uns ein paar Scans der lokalen Anomalien besorgen könntet, wäre das eine große Hilfe!", sourceObjective = "Untersucht transpositionale Anomalien in der Nähe von Gadgetzan.", completion = "Das sind mal glitzernde Daten!", sourceObjectiveStatus = "unverified-source-field" }
quests[83494] = { id = 83494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmeuten: Raumgeister an der Küste", description = "In der Wüste, die hier in der Nähe ist, läuft ein ganzer Haufen halbteleportierter Kreaturen herum. Ich meine, auch nur ein solches Wesen wäre bereits überraschend, aber aus irgendeinem Grund sind es eine ganze Menge!\n\nSie machen keinen besonders freundlichen Eindruck, aber ich wette, dass wir aus ihrem Unglück lernen können, damit der Kriegsmeutenbankentfernungsunterdrücker unsere Beute nicht in einen Baum teleportiert!\n\nSeht nach, ob Ihr etwas finden könnt, das uns hilft zu verstehen, was schiefgelaufen ist. Es kann doch niemand einfach per Zufall teleportiert werden, nicht wahr?", sourceObjective = "Sammelt räumliche Rückstände von den teilweise teleportierten Kreaturen in der Nähe von Gadgetzan.", progress = "Irgendwelche Hinweise?", completion = "Gut gemacht, {name}! Ich bin mir nicht sicher, was das ist, aber es hilft bestimmt!", sourceObjectiveStatus = "unverified-source-field" }
quests[83495] = { id = 83495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmeuten: Zwillingsposition", description = "Wir sind richtig in Fahrt! Während Ihr weg wart, haben wir eine noch anomalere Anomalie erfasst und sie ein kleines Stück westlich der Stadt verortet.\n\nWir haben dort bereits eine brandneue transpositionale Signalrekombobulierung eingerichtet, aber ich wollte sie nicht ohne Euch starten. Schließlich wart Ihr uns eine große Hilfe.\n\nIhr müsst Euch lediglich einwählen und den Schalter umlegen! Das sollte selbst ein Kind schaffen, und Kinder sind soweit ich weiß nicht sehr clever.\n\nNieti sagt, dass es eine gute Wahrscheinlichkeit gibt, dass etwas Kataklysmisches passieren wird, also weiß ich, dass nichts Schlechtes passieren kann!", sourceObjective = "Aktiviert die transpositionale Signalrekombobulierung außerhalb von Gadgetzan und werdet mit den Konsequenzen fertig.", progress = "Werft den Schalter herum!", completion = "Gut gemacht!\n\nNicht das, was ich erwartet hatte, aber ich muss sagen, der Schnurrbart hat mir sehr gut gefallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83496] = { id = 83496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmeuten: Raumzeit ist Geld", description = "Jetzt, da wir so viele Transpositionsdaten haben, wie wir uns nur erhoffen konnten, müssen wir nur noch ein Wurmloch in einer geeigneten Bank einrichten, dann können wir uns schon bald gegenseitig Ausrüstung vom Feld direkt in die Taschen zuwerfen!\n\nUnd zufälligerweise gibt es hier in Gadgetzan eine passende Bank!\n\nWenn Ihr schon dabei seid, könnt Ihr auch Euer eigenes Portal einrichten, um von überall auf Eure Kriegsmeutenbank zuzugreifen. Das wird so praktisch!", sourceObjective = "Bringt die Derekombobulierungsmatrix in die Bank in Gadgetzan.", progress = "Habt Ihr die Bank gefunden?", completion = "Ein paar Problemchen, aber nichts, was nicht durch gute, altmodische Teamarbeit gemeistert werden konnte! Wir waren großartig!", sourceObjectiveStatus = "unverified-source-field" }
quests[83497] = { id = 83497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besorgter Freund", description = "Ah, {name}, da seid Ihr! Der Große Kyron hat nach Euch und Eurem Freund Anduin gefragt. \n\nIch denke, er will mit Euch über Faerin sprechen. Das ist aber nichts Dringendes, sie braucht vermutlich nur Gesellschaft. Aber wir machen uns ein wenig Sorgen um sie.\n\nSprecht mit Kyron, wenn Ihr einen Moment Zeit habt, in Ordnung?", sourceObjective = "Trefft den Großen Kyron in Mereldar.", completion = "Ich hoffe, die Reise war nicht zu lang.", sourceObjectiveStatus = "unverified-source-field" }
quests[83499] = { id = 83499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkaneinöde", description = "Die Überlebenden der Kirin Tor haben gezögert, in dieses Gebiet zurückzukehren. Vor und nach dem Absturz von Dalaran wurde viel Energie verstreut. Für diejenigen unter uns, die empfänglich dafür sind, schwebt über diesem Gebiet ein unsichtbares, aber spürbares Miasma.\n\nEs ist unklar, ob dieser Ort verunreinigt ist oder ob hier auch körperhaftere Gefahren lauern.\n\nIch kann uns beschützen, aber ich habe all meine Reagenzien im Proszenium verbraucht. Wollt Ihr mir helfen, mehr zu beschaffen?", sourceObjective = "Helft Aethas Sonnenhäscher, am Ruhigen Ufer die benötigten Reagenzien für einen Schutzzauber zu sammeln.", progress = "Die letzten Tage waren... schwierig.", completion = "Ja, die werden reichen. Danke, {name}.\n\nTrotz der Splitter und Elementare in den Ruinen scheint dort keine unmittelbare Gefahr zu drohen. Aber wenn wir hier länger bleiben wollen, müssen wir über eine Arkanbarriere nachdenken.\n\nWir wissen nicht, was das Miasma für langfristige Auswirkungen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[83500] = { id = 83500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zekvir, Hand der Vorbotin", description = "Wir müssen uns beim Erforschen der Tiefen vor Zekvir in Acht nehmen. Ich glaube, dass wir noch nicht mächtig genug sind, um es mit ihm aufzunehmen, aber das wird sich bald ändern!\n\nLasst uns weiterforschen und Schätze bergen, bis wir stark genug sind, ihn zu seinem Versteck zu verfolgen und zu besiegen.", sourceObjective = "Besiegt Zekvir, Hand der Vorbotin, in seiner eigenen Tiefe.", completion = "Wir haben es geschafft! Wir haben diesen Ort für alle Abenteurer sicher gemacht. \n\nDas sollte Xal'atath in die Klemme gebracht haben, jetzt da ihr einer ihrer mächtigsten Kriecher fehlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83502] = { id = 83502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lektionen in defensiver Magie", description = "Der Zauber für die Barriere ist bereit, aber ich muss ihn erst kanalisieren und seinen Perimeter definieren. \n\nNehmt diese Schutze und platziert sie am Rand unserer gewünschten Barriere, während ich den Zauber kanalisiere.\n\nWir werden den Zauber entfesseln, sobald Ihr fertig seid.", sourceObjective = "Helft Aethas Sonnenhäscher dabei, einen Zauber zu wirken, um eine arkane Schutzkuppel über dem Ruhigen Ufer zu erschaffen.", completion = "<Aethas atmet ein.>\n\nJa. Das wird reichen... fürs Erste.", sourceObjectiveStatus = "unverified-source-field" }
quests[83503] = { id = 83503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Dornogal", description = "Der Kampf ist endlich vorbei. Jetzt ist es wohl an der Zeit, dass wir unsere Wunden lecken.\n\nKehrt nach Dornogal zurück, Champion.\n\nIch komme nach, sobald Khadgar wohlauf und reisefähig ist.", sourceObjective = "Kehrt nach Dornogal auf der Insel von Dorn zurück und erstattet Bericht.", completion = "Unser Kampf war hart. Aber uns steht noch vieles bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[83519] = { id = 83519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aber was ist mit dem Casino?", description = "Die Zeiten ändern sich. Nun, da der alte Jastor hinüber ist, kann das Kartell es kaum erwarten, das Schicksal des Kronjuwels von Lorenhall zu besiegeln: das Garbagio.\n\nDas morgige Gerichtsverfahren soll einen endgültigen Beschluss erörtern. Zum Glück befindet sich die Urkunde in den Händen eines Mannes, dem ich traue.\n\nSein Name lautet Rosenknospe Gallywix.\n\nIch weiß, ich weiß. Aber Röschen ist ein feiner Kerl. Ich mache Euch später miteinander bekannt.\n\nVorher müsst Ihr aber mir einen Gefallen tun. Fragt die Mächtigen auf der Feier, was sie vom neuen Eigentümer halten.", sourceObjective = "Erkundigt Euch auf der Eröffnungsfeier des Garbagio nach Rosenknospe Gallywix.", progress = "Lasst Euch vom Namen Gallywix nicht abschrecken. Er hatte eine große Familie und nicht alle davon sind niederträchtige Spinner.", completion = "Das... ist schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[83522] = { id = 83522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuld begleichen, Freiheit einstreichen", description = "Die ersten Vorstandsmitglieder auf unserer Liste sind das geniale Spieleduo: Kayjay und der fantastische Davey.\n\nMein Schwager hat mir erzählt, dass die Venture Company all ihre Schulden aufgekauft hätte. Das geschah in dem Moment, als man Rosenknospe erledigte.\n\nHaben sie ihn umgebracht? Kein naheliegendes Motiv, wenn sie hochverschuldet waren, aber man kann nie wissen, wer wen in der Tasche hat.\n\nWir müssen herausfinden, wie gut es ihnen hier auf der Deponie von Venturemühle geht. Wenn sie die neue Urkunde nicht unterzeichnen wollen, haben wir vielleicht unsere Übeltäter!", sourceObjective = "Sprecht mit Kayjay und dem fantastischen Davey und bittet sie, die neue Urkunde des Garbagio zu unterzeichnen.", progress = "Ihr werdet sehen, dass alle meine Arbeiter recht zufrieden sind. Ich habe Rechnungen von mehreren Firmenlehrgängen, die das beweisen.", completion = "Seht Ihr? Glücklich und froh wie ein Wadenbeißer der Zandalari...o.\n\nDoch falls Ihr wirklich darauf aus seid, Euch ihre Dienste unter den Nagel zu reißen, werden wir uns womöglich einig...", sourceObjectiveStatus = "unverified-source-field" }
quests[83524] = { id = 83524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Müll, des anderen Gold", description = "Kayjay und Davey sind in der Tat Meister darin, Spiele zu erfinden. Sie haben sich für mich ein neues ausgedacht und es ist ein absoluter Erfolg.\n\nFalls Ihr bereit seid, das Risiko einzugehen, gebe ich Euch die Chance, die beiden mitsamt ihren Schulden für Euch zu gewinnen.\n\nSchnappt Euch eine Hacke und betretet die Deponie. Sobald die Pfeife ertönt, tretet Ihr gegen all meine anderen \"Angestellten\" an.\n\nGewinnt bis zur letzten Glocke und ich lasse die beiden gehen. Verliert und Ihr gehört mir.\n\nEs nennt sich Wetthacken. Und Ihr werdet den Rest Eures Lebens in meiner Schuld stehen.", sourceObjective = "Nehmt beim Wetthacken auf den Halden teil.", progress = "<Tarbonara sagt nichts. Er fletscht bloß seine blendenden Zähne.>", completion = "Ihr habt nicht gewonnen. Überraschung, schätze ich.\n\nWillkommen im Schuldenzirkus von Tarbonara. Der Spaß hört nie auf...", sourceObjectiveStatus = "unverified-source-field" }
quests[83527] = { id = 83527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewinnen ist sowieso was für Verlierer", description = "Das ist der schlimmste Job, den ich je hatte. Und ich habe schon das Schildkrötenwerfen auf dem Dunkelmond-Jahrmarkt beaufsichtigt.\n\nWir mögen keine Fesseln an den Füßen haben, aber Tarbonara gelten alle unsere Schulden. Er hat die Informationen auf Schuldenmarker gedruckt, die seine Wachen aufbewahren, für den Fall, dass wir wissen wollen, wo wir stehen.\n\nAber wenn Ihr diese Marker in die Finger bekommt, sind wir alle frei. Doch um das zu schaffen, müsst Ihr ein paar Schädel einschlagen. Ich gebe Euch Punkte für jede Wache, die Ihr besiegt.\n\nIhr sammelt doch gerne Punkte, oder?", sourceObjective = "Sammelt Schuldenmarker und befreit die Vertragsschuldner.", completion = "Alle dabei? Gut! So wird man uns ganz sicher NICHT anhalten.\n\nIch kann Euch dafür gar nicht genug danken, {name}. Wirklich. Ehrlich. Das Garbagio wird eine ganze Etage voller eifriger Spiele-Enthusiasten beherbergen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83528] = { id = 83528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles Teil des Spiels", description = "Hört zu. Ich weiß, dass wir uns die Schulden eingebrockt haben, aber Rosenknospe hat an uns geglaubt! Mit ihm gab es ein Licht am Ende der Casino-Etage.\n\nOhne ihn... sind wir nur zwei einzelne Hälften eines Spielgenies, die ab und an angeheuert werden, statt solides Geld zu verdienen.\n\nDoch Rennraser sagte, wir hätten noch immer die Chance, den Job im Garbagio durchzuziehen. Stimmt das? Falls ja, sind Davey und ich dabei.\n\nDas Problem ist nur, dass Kommissar Kudd Milchzahn höchstpersönlich unsere Schuldenmarker aufbewahrt. Und er steckt tief in Tarbys Tasche.", sourceObjective = "Holt Euch die Schuldenmarker von Kayjay und dem fantastischen Davey von Kommissar Kudd Milchzahn.", completion = "Wie viel musstet Ihr für ihre Schuldenmarker bezahlen?\n\nOh... nun, dann werden wir wohl keine Entschädigungsformulare für Euch ausfüllen müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83529] = { id = 83529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelfest von Heilsturz", sourceObjective = "Fangt diese Trophäenfische, bevor der Festflitzer-Buff ausläuft: Bismut-Butterling, Flüsternder Sterngucker, Majestätischer Zwergbarsch.", completion = "Das sind ein paar gute Fänge, {name}. Ich freue mich schon darauf, was Ihr nächste Woche fangen werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[83530] = { id = 83530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelfest von Heilsturz", sourceObjective = "Fangt diese Trophäenfische, bevor der Festflitzer-Buff ausläuft: Blutbarsch, Tosender Anglersucher, Stacheliger Seerabe.", completion = "Das sind ein paar gute Fänge, {name}. Ich freue mich schon darauf, was Ihr nächste Woche fangen werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[83531] = { id = 83531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelfest von Heilsturz", sourceObjective = "Fangt diese Trophäenfische, bevor der Festflitzer-Buff ausläuft: Trödelnder Häsling, Dornischer Hecht, Azj-Kahet-Slumhai.", completion = "Das sind ein paar gute Fänge, {name}. Ich freue mich schon darauf, was Ihr nächste Woche fangen werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[83532] = { id = 83532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelfest von Heilsturz", sourceObjective = "Fangt diese Trophäenfische, bevor der Festflitzer-Buff ausläuft: Kristalliner Stör, Spiegelregenbogenfisch, Blutroter Dornhai.", progress = "Hat etwas angebissen, {name}?", completion = "Das sind ein paar gute Fänge, {name}. Ich freue mich schon darauf, was Ihr nächste Woche fangen werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[83534] = { id = 83534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Aufwärmübung", description = "Nicht zu fassen, dass Revilgaz uns den Auftakt gegeben hat! Keiner guckt sich die erste Band an!\n\nEgal. Ihr seid also die Person, von der der alte Junge Marty gesprochen hat? Er hat mir bereits davon erzählt, dass Ihr die Auktion des Garbagio verhindern wollt. Find ich albern. Ein richtiger Plan ist das nicht.\n\nTreffen wir eine Abmachung. Als der Casino-Deal geplatzt ist, hat uns unsere Managerin im Stich gelassen. IHR werdet heute ihren Platz einnehmen. Keine Sorge, kann nicht schlimmer sein als all die anderen Jobs, die Ihr bereits hattet.\n\nDer erste Punkt auf der Tagesordnung: Verschafft uns ein Publikum.", sourceObjective = "Macht Stimmung und versammelt ein Publikum für die Kellergnome.", completion = "Gute Arbeit, Boss. Ihr habt uns ein Publikum beschafft und noch mehr als das.\n\nDer zweite Punkte auf unserer Tagesordnung... Ihr könnt doch ein Instrument spielen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[83535] = { id = 83535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunderparty-Erdbeben", description = "Hier! Nehmt diese Mecha-Trianglocke!\n\nIst mir egal, dass Ihr kein Instrument spielen könnt, denn Ihr WERDET darauf spielen.\n\nWährend wir abrocken, werden Mitglieder rivalisierender Bands versuchen, die Bühne zu stürmen und uns aufzuhalten.\n\nDie Trianglocke erklingt nicht nur in der perfekten Tonlage, sondern katapultiert auch alle, die nicht zu unserer Band gehören, bis ganz nach hinten auf die billigen Plätze.", sourceObjective = "Beschützt die Kellergnome während ihres Auftritts mit der Mecha-Trianglocke.", completion = "Der beste Gig, den wir je hatten! Das war ein verdammtes Schlachtfeld, was?\n\nIhr habt Euch gut geschlagen. Bringt uns Martys neuen Vertrag, dann unterschreiben wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[83536] = { id = 83536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totengräber der Ebbe" }
quests[83537] = { id = 83537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geothermale Edelsteinbehandlung" }
quests[83538] = { id = 83538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabungsbefreiung" }
quests[83539] = { id = 83539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefühl von Traurigkeit", description = "Ich fürchte... dass vielleicht nur ich übrig bin, {name}. Oder dass die anderen zu weit weg sind, um meine Nachricht zu empfangen.\n\nVielleicht müssen wir hier einen Außenposten errichten und uns um die Säuberung der Absturzstelle kümmern.\n\nSo soll es sein. Das ist auch in Ordnung...", sourceObjective = "Errichtet den Außenposten der Kirin Tor am Ruhigen Ufer.", progress = "Es ist schwer zu beschreiben, was ich gerade fühle.", completion = "Gut gemacht. Die Tasche ist echt nützlich, was? Ich bin froh, dass ich sie mitgenommen habe.\n\nFahren wir mit der Aufgabe fort...", sourceObjectiveStatus = "unverified-source-field" }
quests[83540] = { id = 83540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrängeln", description = "Ich weiß ja nicht, was Euer Zinken auf der Fahrt hierher so geschnuppert hat, aber die Straße da unten hat ein paar herrliche Düfte zu bieten.\n\nLeider waren die Leute zu dicht aneinandergedrängt. Ich konnte Gobdre nirgendwo finden.\n\nUnd da kommt Noggy ins Spiel. Der ist dieser Tage 'n ziemlich wichtiger Mann, der uns bestimmt was Nützliches verraten könnte.\n\nEr ist eigentlich von der herzlosen, berechnenden Sorte, der keine Geheimnisse ausspuckt. Aber sein Stolz ist so zerbrechlich wie die Rumble-Figuren meiner Frau.\n\nEin Stupser in die richtige Richtung und er macht den Mund auf.", sourceObjective = "Bringt Marin Noggenfogger dazu, Euch den Aufenthaltsort von Jojo Gobdre zu verraten.", completion = "Noggenfogger hat Euch auch ein persönliches Empfehlungsschreiben gegeben?\n\nWenn er erwartet, dass ich Euch vorlasse, ist er dümmer, als ich dachte.", sourceObjectiveStatus = "unverified-source-field" }
quests[83541] = { id = 83541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hagelt Kritik", description = "Zeigt mir, dass in Euch mehr steckt als nur heiße Luft.\n\nIch gebe allen Kunden Rezensionskarten. Sie sollen meine Speisekarte darauf bewerten und sie dann hier abgeben. Aber ich habe noch keine einzige gesehen.\n\nIst da was faul? Auf jeden Fall. Und nicht auf die Art, die mir gefällt.\n\nLos. Bringt mir meine Rezensionen zurück. Ohne sie werde ich mich keinen Zentimeter in Richtung des Garbagio bewegen.", sourceObjective = "Bringt 100 Rezensionskarten für Speisende zurück.", progress = "Wie hat ihnen der in Dschungelranken eingelegte Sturmrochen geschmeckt?\n\nSie fanden ihn bestimmt bitter. Ich wusste, dass diese Charge bitter ist. Als ich sie gekocht habe, ist mir das Salz ausgegangen.", completion = "Die faulen Gäste verstehe ich noch.\n\nAber meine Konkurrenz hat sich Karten genommen, weil Tarbonara ihnen gesagt hat, das würde mich vertreiben? Im Ernst? Können die nicht einfach... besseres Essen kochen?\n\nNa ja, egal. Ihr habt mit dem Kochen nichts am Hut, aber Ihr habt getan, was Ihr solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[83542] = { id = 83542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelle Kiemen gegen Gold", description = "Ah, Mist... Ich wusste, dass das passieren würde.\n\nDie Speisenden fanden ein Gericht besser als alle anderen: scharf angebratener Tiefenläufer-Schenkel an algarischem Orbinid mit Blutconfit.\n\nLanger Name, was? Ich hatte gehofft, dass er die Gäste davor abschrecken würde, ihn auf Ihre Rezensionskarten zu schreiben.\n\nAber ohne Bratgefäß lässt sich nichts im Bratgefäß anbraten... Und nachdem der Garbagio-Deal geplatzt war, habe ich mein bestes Stück verkauft.\n\nWollt Ihr mich wieder an Bord haben? Dann besorgt mir mein Bratgefäß. Diese Tiefenläufer-Schenkel braten sich schließlich nicht von selbst.", sourceObjective = "Tauscht Gold-Fische gegen Gobdres geschätztes Bratgefäß.", progress = "Blair Barsch und Chub Barsch. Die hinterhältigsten Turteltäubchen, denen Ihr je begegnen werdet.\n\nAber die sie haben mir fantastischen Fisch besorgt.", completion = "Ihr seid des Kochens zwar immer noch nicht würdig, aber wenn's darum geht, was zu besorgen, macht Euch keiner was vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[83543] = { id = 83543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteuer in Khaz Algar", description = "Wir haben Späher in jeder Ecke von Khaz Algar, und sie berichten alle dasselbe: Ärger.\n\nWir kommen wohl gerade rechtzeitig, was?\n\nSeht euch die Späherkarte auf dem Tisch hinter Euch an und helft mit, wo Ihr nur könnt.", sourceObjective = "Betrachtet die Späherkarte, um eine Gegend in Khaz Algar auszusuchen, die Ihr unterstützen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83546] = { id = 83546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verantwortung", description = "Es ist soweit! Es wird Zeit für Hemd und Krawatte, {name}!\n\nWir haben die Unterschriften für die Verträge. Wir haben die Unterstützung der Kartelle. Und wir haben... meine Kinder.\n\nMeine Frau sollte uns eigentlich begleiten, aber sie ist in der Dusche ausgerutscht! Ist das zu glauben? Sie wird den ganzen Morgen beim Chiropraktiker verbringen. Sie tut mir so leid. Einfach furchtbar.\n\nTja, ihr Pech! Lasst uns alles einpacken, was wir brauchen. Dann fahre ich uns alle rüber zum Gerichtssaal.", sourceObjective = "Packt zusammen und fahrt zum Gerichtshof.", completion = "Wow! Großes Publikum, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[83547] = { id = 83547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in der Nachbarschaft", description = "<Ein Brief steckt in Eurem Briefkasten. Die Handschrift ist sauber und schön geschwungen.>\n\nWillkommen in Borohain, {name}! Mein Name ist Lyssabel Dämmerblüte und ich bin die Verwalterin hier. Ich helfe Euch, Euch in der Nachbarschaft zurechtzufinden.\n\nBesucht mich bitte im Rathaus, wenn Ihr so weit seid.", sourceObjective = "Sprecht mit Lyssabel Dämmerblüte im Rathaus.", sourceObjectiveStatus = "unverified-source-field" }
quests[83548] = { id = 83548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insel von Dorn", description = "Die Überlebenden des Angriffs auf Dalaran werden von Nerubern bedrängt, die von der Königinnenwache Zirix angeführt werden.\n\nSteht ihnen bei und beschützt alle, die noch übrig sind.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer auf der Insel von Dorn.", completion = "Wir werden nicht zulassen, dass die Neruber uns noch mehr von unseren Leuten nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83550] = { id = 83550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schallenden Tiefen", description = "Sprecherin Brinthe ist zu den Schallenden Tiefen gegangen, um zu sehen, wie es den Maschinenflüsterern während ihrer Abwesenheit ergangen ist.\n\nSie hat um Abenteurer gebeten, die sich ihr am Grund des Kernweges anschließen.", sourceObjective = "Trefft Sprecherin Brinthe in den Schallenden Tiefen.", completion = "Danke, dass Ihr gekommen seid. Das ist ein größeres Durcheinander, als ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[83551] = { id = 83551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilsturz", description = "Anduin Wrynn hofft, das Vertrauen und die Hilfe der Arathi in Heilsturz zu gewinnen.\n\nEr wird Hilfe brauchen, um diese potenziellen Verbündeten zu überzeugen.", sourceObjective = "Sprecht mit Faerin Lothar in Heilsturz.", completion = "Wenn Ihr gekommen seid, weil Ihr Hilfe braucht, fürchte ich, dass Ihr uns selbst mitten in einer Krise antrefft.", sourceObjectiveStatus = "unverified-source-field" }
quests[83552] = { id = 83552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azj-Kahet", description = "Ein Luftschiff der Arathi ist nach einem bösartigen nerubischen Hinterhalt in Azj-Kahet gestrandet.\n\nHelft den Überlebenden, den nerubischen Angriff abzuwehren.", sourceObjective = "Sprecht mit Faerin Lothar an Bord der Abrechnung in Azj-Kahet.", completion = "Gerade noch rechtzeitig, {name}. Wir wurden überrascht, aber jetzt werden wir sie zurückdrängen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83553] = { id = 83553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magie raubende Kobolde", description = "Ich fürchte, unsere \"Säuberung\" von Dalaran geht weit über die Küsten der Insel von Dorn hinaus.\n\nAuf der Suche nach Euch habe ich die Insel viele Male umkreist. Im Flug habe ich die Magie vieler vertrauter Gegenstände gespürt. Gegenstände, die früher in Dalaran aufbewahrt wurden.\n\nGefährliche Gegenstände.\n\nJemand oder etwas muss sie mitgenommen haben. Wir müssen diese Gegenstände finden, bevor jemand Unschuldiges zu Schaden kommt.\n\nFolgt mir.", sourceObjective = "Trefft Euch mit Kalecgos in Trauerhöhe auf der Insel von Dorn.", completion = "Wir werden hier mit unserer Suche beginnen.\n\nIch kann eine schwache arkane Aura spüren, die von diesem Gebäude ausgeht.\n\nDie Kobolde müssen die Gegenstände gefunden und hierhergebracht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[83554] = { id = 83554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmuckstücke, Kuriositäten und andere mächtige Gegenstände", description = "Die Kobolde hier könnten mit den gestohlenen Sachen ungeheuerlich viel Unfug anstellen.\n\nHolt so viel wie möglich von ihnen zurück, egal wie...\n\nIhr kümmert Euch um die Kobolde bei den Gräbern von Trauerhöhe, und ich werde mich unter Tage begeben und Kriegvals Kräftigung durchsuchen.\n\nTrefft mich in der Nähe von Kriegvals Kräftigung, wenn Ihr die von den Kobolden gestohlenen Artefakte der Kirin Tor gesichert habt.", sourceObjective = "Holt Euch die gestohlenen Artefakte der Kirin Tor von den Kobolden in Trauerhöhe zurück.", progress = "Wir müssen finden und zurückholen, was wir können. Selbst die kleinste Kuriosität könnte für jemanden von Bedeutung sein... oder gefährlich.", completion = "Ich bin schockiert, wie viel sie in so kurzer Zeit erbeuten konnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[83555] = { id = 83555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöse Halskette", description = "<Das Juwel pulsiert vor arkaner Energie und weist auf uralte Magie hin, die tief in seinen Kern gewoben wurde.>", sourceObjective = "Bringt die Halskette zu Kalecgos in Trauerhöhe auf der Insel von Dorn zurück.", completion = "Der Kobold, bei dem Ihr das gefunden habt, war tot, sagt Ihr?\n\nDas ist... kein gutes Zeichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83556] = { id = 83556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieber nicht anfassen", description = "Diese Halskette...\n\nSie steckt eindeutig voller mächtiger Magie, aber... sie ist nur schwer greifbar, als würde sie ihre Herkunft vor mir verbergen.\n\nSeht Ihr sie Euch mal an. Vielleicht übersehe ich ja etwas Offensichtliches.", sourceObjective = "Untersucht die smaragdgrüne Halskette in Trauerhöhe.", completion = "Es war dumm von mir, unachtsam zu werden.\n\nMacht Euch keine Sorgen, {name}, aber das scheint... eine Taschendimension zu sein.\n\nWenn die Kobolde, die hier ihren Tod gefunden haben, auf irgendetwas hindeuten, dann darauf, dass sich eine Rückkehr zur Insel von Dorn als schwierig erweisen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[83558] = { id = 83558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Casinohof", description = "Ich bin bereit, unser Anliegen vorzubringen. Es gibt nur eine winzig kleine Kleinigkeit, die ich Euch mitteilen möchte...\n\nUnter meinem Tisch befindet sich eine Bombe.\n\nKeine Sorge! Es ist nicht das erste Mal, dass so etwas passiert. Aber es sind viele Leute hier, und ich möchte den Ablauf nicht wegen einer kleinen Explosion unterbrechen.\n\nNehmt diesen X-Plo-Dar 64k. Verwendet ihn, um die Signatur der Bombe zu dem Goblin mit dem Auslöser zurückzuverfolgen.\n\nMein Anwaltsinstinkt sagt mir, dass der Verantwortliche für diese Explosion auch Rosenknospes Mörder ist. Nur eine Vermutung.", sourceObjective = "Verwendet den X-Plo-Dar 64k, um herauszufinden, wer den Auslöser der Bombe hat.", progress = "Habt Ihr die Quelle schon gefunden?", completion = "Tarbonara? Er ist der Bombenleger? ...Tatsächlich?\n\nIch bin nur deshalb so überrascht, weil es zu offensichtlich war!", sourceObjectiveStatus = "unverified-source-field" }
quests[83563] = { id = 83563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaffee für den Erfolg", description = "Ihr habt uns den Beweis geliefert, den wir brauchten. Jetzt müssen wir dem Richter nur noch Rosenknospes Mörder offenbaren.\n\nIch kann mir vorstellen, dass Tarbonara nicht so einfach klein beigeben wird, also macht Euch auf eine der vielen goblinischen Reaktionen gefasst.\n\nIhr wisst, was ich meine. Explosionen oder Kanonen oder Geschrei oder Casinoüberfälle oder was auch immer. Ich mache mir aber keine Sorgen, Ihr scheint recht fähig zu sein.", sourceObjective = "Besiegt Tarbonara Knisterkurbel und sorgt dafür, dass Richter Landro die neue Garbagio-Urkunde notariell beglaubigt.", progress = "Ich hatte das Gefühl, dass dies ein großartiger Fall sein würde.", completion = "Was habe ich gesagt? Ich sagte, Ihr sollt Euch auf eine goblinische Reaktion gefasst machen. Oh Junge, und was für eine wir bekommen haben.\n\nWie Ihr sehen könnt, sind alle Gazlowe gefolgt und haben sich mit Tarbonaras Schlägern angelegt. Wir waren ziemlich gut, oder?\n\nIch meinerseits? Nun, ich bin auf dem Weg zum Eingang des Garbagio. Die neuen Inhaber sind alle da oben, und ich möchte ihnen alles Gute wünschen, bevor wir beide von Anwälten zu Klienten befördert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[83566] = { id = 83566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, das Casino!", description = "Ihr würdet <einen guten Anwalt/eine gute Anwältin> abgeben!\n\nHah! Nur Spaß! Das eigentliche Geheimnis der Branche ist, dass es so etwas wie einen guten Anwalt nicht gibt!\n\nBegleitet mich doch bitte zum Eingang des Garbagio. Das wäre ein schöner Abschied für die Kinder, die den Laden jetzt leiten werden.\n\nGanz zu schweigen davon, dass wir ihnen tatsächlich die beglaubigte Urkunde aushändigen sollten!", sourceObjective = "Übergebt das Garbagio.", progress = "Habt Ihr Tränen in den Augen, weil unser Abenteuer vorbei ist?\n\nOder weil Ihr insgeheim gehofft habt, dass das Haus versteigert wird und Ihr die Chance bekommt, es zu kaufen?\n\nIch wette, Letzteres ist der Fall! Hah!", completion = "Manchmal hat man das Gefühl, dass ein nicht enden wollender Strom von Problemen aus dem sprichwörtlichen Abwasserkanal kommt, die es zu lösen gilt. Ist es nicht so, {name}?\n\nAber das hier... Nun, sagen wir einfach, dass dies wie ein persönlicher Gefallen für alle aus Lorenhall ist.\n\nEs gibt zwar keinen Schlüssel zur Stadt, aber Marty wollte Euch eines seiner besten Anwaltsoutfits vermachen. Tragt es mit Stolz, Kindchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83569] = { id = 83569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod und Steuern", description = "Er ist einfach... explodiert...\n\nWenn ein Goblin schon gehen muss, dann wohl auf diese Art. Das ist alles, was ich zu dem armen Röschen sagen kann. Und dass ich ihn vermissen werde. UND dass wir herausfinden werden, wer das getan hat!\n\nAber das eigentliche Problem ist Folgendes: Wem gehört das Garbagio jetzt?\n\nEs ist an der Zeit, sich an einen Experten für juristischen Hokuspokus zu wenden. Der Staat Lorenhall hat uns für die morgige Gerichtsverhandlung einen Pflichtverteidiger zugewiesen, einen Kerl namens Rennraser. Er ist alles, was wir haben.\n\nBringt das, was von der Urkunde übrig ist, in sein Büro in Bruchbudenhügel und klärt diese Angelegenheit.", sourceObjective = "Trefft Euch mit dem Pflichtverteidiger von Lorenhall.", completion = "Ich versichere Euch, dass ich normalerweise in meinem Papierkram ertrinke, und zwar weitaus mehr im übertragenen Sinne, als noch vor Kurzem.", sourceObjectiveStatus = "unverified-source-field" }
quests[83587] = { id = 83587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Chance, zuzuschlagen", description = "<Die kindliche Spinne überreicht Euch eine versiegelte Schriftrolle. Der versiegelte Brief trägt die Markierungen des Wesirs.>\n\nDas Gleichgewicht der Macht in Azj-Kahet verschiebt sich. Die Königin wird von Tag zu Tag labiler, und ich fürchte, wir müssen handeln, bevor wir unsere Chance verpassen, sie aufzuhalten. \n\nTrefft mich im königlichen Apothekarium, wenn Ihr diesen Brief erhaltet.", sourceObjective = "Trefft Euch mit dem Wesir im königlichen Apothekarium.", completion = "Ich hätte lieber meinen persönlichen Diener geschickt, um Euch zu holen, aber die Situation erfordert äußerste Diskretion.", sourceObjectiveStatus = "unverified-source-field" }
quests[83616] = { id = 83616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verschanzte", description = "Und jetzt der andere Teil dieses Coups.\n\nIch habe schon eine ganze Weile unter den Mandibeln der großen Hochspinnerin Antourix gearbeitet. Sie hat sich in Rak-Ahat verschanzt und denkt, dass ihr an der Spitze nichts etwas anhaben kann. Sie hat sich bereits geweigert, sich Ren'khat zu unterwerfen.\n\nAuch sie weiß, dass es nur eine Frage der Zeit ist, wenn Ren'khat den Rückhalt des Throns hat. Lasst uns ihre Versuche zur Verdrängung dieses Emporkömmlings beschleunigen.\n\nSeht, wie schnell sie sich gegeneinander wenden.", sourceObjective = "Bietet der großen Hochspinnerin Antourix Eure Dienste gegen Ren'khat an.", completion = "Argh! Für so was habe ich keine Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[83627] = { id = 83627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anfang von etwas Wunderschönem", description = "<Dies sieht aus, als wäre es für einen nerubischen Alchemisten von Interesse.\n\nDer Aufstieg ist ihre Spezialität und dies könnte der Schlüssel sein, um mehr über den Vorgang zu erfahren.>", sourceObjective = "Bringt die Phiole mit Himmelsreißerblut zu Shalba.", completion = "Hm? Was? Nun, das ist faszinierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[83628] = { id = 83628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angespannte Rettung", description = "Die Lage mit diesen Fremden ist... angespannt. Wir wissen es zu schätzen, dass wir hier in ihrem Lager Unterschlupf finden dürfen. Aber sie scheinen uns bestenfalls zu tolerieren. Wir haben ihnen angeboten, unsere Vorräte zu teilen, aber das hat sie irgendwie beleidigt.\n\nMeine Schwester ist schwer verwundet. Ich sehe in dem Zelt dort drüben Kräuter, mit denen ich ihr helfen könnte, aber diese riesige Schnecke versperrt den Eingang. Ich komme nicht an sie heran.\n\nIch habe die Wache auf dem Hügel um Hilfe gebeten, aber er hat mich nur angestarrt. Ich weiß nicht, was ich tun soll! Vielleicht hört er ja auf Euch?", sourceObjective = "Sprecht mit den Fremden, um die Beziehungen zu den Arathi zu verbessern.", completion = "Ihr seid nicht unerwünscht, Fremder. Ich bin der Letzte.", sourceObjectiveStatus = "unverified-source-field" }
quests[83629] = { id = 83629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümliche Ruhe", description = "Dies war einst ein großer See. Im Laufe der Zeit brachen die Wurzeln seinen Boden auf und ließen das Wasser abfließen. Ich habe hier mein ganzes Leben lang gelebt und alles miterlebt. Aber jetzt sind dunklere Veränderungen gekommen.\n\nManchmal kommen Veränderungen mit dem Tod. Verfall ist natürlich.\n\nAber die Milben, die sich von meinem Volk ernähren, sind es nicht. Ihr Befall ist so seltsam, dass meine Rinde sich anfühlt, als würde sie aus meinem Körper kriechen.\n\nVernichtet diese Milben, damit ich mich ausruhen kann, ohne Angst vor ihren Mäulern auf meiner schlafenden Gestalt.", sourceObjective = "Tötet 15 schlemmende Milben für Goehi.", progress = "Das Geräusch ihres Nagens erfüllt mich mit Schrecken.", completion = "Es ist ruhig. Vielleicht werde ich mich jetzt mit meinem Volk ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83632] = { id = 83632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ringe der Erinnerung", description = "Ich weiß zu schätzen, was Ihr getan habt. Macht Euch keine Sorgen, ich bin noch nicht fertig.\n\nWenn Ihr wollt, könnt Ihr diese Wurzel zu denen bringen, die Euch geschickt haben. Sie können die Geschichte meines Lebens in den Ringen aus Holz lesen. Mein Leben ist eines von vielen im Wandteppich, aber wir sind alle miteinander verwoben. \n\nDie Fremden, denen Ihr begegnet seid, mögen zurückgezogen sein, und sogar geheimnisvoll, aber sie verstehen diesen Wandteppich wie kein anderer und schützen ihn mit ihrem Leben.", sourceObjective = "Bringt Goehis Wurzel ins Wildlager Or'lay.", progress = "Habt Ihr das Urtum gefunden?", completion = "Goehi hat diese Wurzel geschickt, war aber noch am Leben...\n\nIch verstehe. Seine Geschichte ist bei uns sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[83639] = { id = 83639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Kommunikation", description = "Ihr versteht, dass andere ein anderes Leben führen als Ihr selbst. Unsere Wege schränken uns ein. Unsere Traditionen sind nicht für die Ohren von Fremden bestimmt. Ich habe nur auf Anraten von Orweyna überhaupt mit Euch gesprochen. Aber ich kann On'hieas Missbilligung von hier aus spüren.\n\nEs ist manchmal unangenehm, Geheimnisse zu haben. Deshalb fürchten so viele die Finsternis. Sie ist unbekannt.\n\nIch muss kryptisch erscheinen. Aber die Arathi kränken uns nicht, nur weil sie anders sind. Sie schaffen Spannungen, wo sie für uns nicht existieren.", sourceObjective = "Sprecht mit Ysabel und klärt das Missverständnis auf.", progress = "Ich kann meine Schwester nicht so zurücklassen.", completion = "Ich kann nicht glauben, dass das nur ein einfaches Missverständnis war. Ich hätte keine Vermutungen anstellen sollen. \n\nDanke, dass Ihr mich beruhigt habt und meiner Schwester geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[83641] = { id = 83641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangen zwischen Leben und Tod", description = "Eine Taschendimension. Das ist alte Magie.\n\nMalygos nutzte manchmal Taschendimensionen, wenn er ungestört bleiben wollte.\n\nEigentlich wurden sie hauptsächlich von Magiern benutzt, um Forschung zu betreiben oder gefährliche Zauber auszuprobieren. Oder wenn sie verbergen wollten, was sie taten...\n\nIch frage mich, wer diese hier erschaffen hat? Spielt wohl keine Rolle. Wir müssen hier raus.\n\nZum Glück haben alle Taschendimensionen einen Ausgang. Der ist aber normalerweise gut versteckt.\n\nFinden wir ihn.", sourceObjective = "Findet einen Weg aus der Taschendimension.", completion = "Schau mal einer an! Jegliche Magie, die noch in der Halskette war, ist jetzt verschwunden. Und damit auch Kel'Thuzads Spiegelbild.", sourceObjectiveStatus = "unverified-source-field" }
quests[83643] = { id = 83643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwie haben wir überlebt", description = "Was wir in Kel'Thuzads Taschendimension erlebt haben, ist eine passende Erinnerung daran, was passieren kann, wenn Magie ohne Rücksicht auf Ethik oder Regeln eingesetzt wird.\n\nFür mich unterstreicht das die Bedeutung der Kirin Tor.\n\nAber auf der anderen Seite war Kel'Thuzad ein Kirin Tor. Es ist auch eine Erinnerung daran, wie Macht verdirbt.\n\nNun, da wir sichergestellt haben, dass diese Artefakte niemanden mehr auf eine unerwartete Reise schicken werden... Lasst uns zu Aethas zurückkehren.\n\nVielleicht haben jetzt mehr auf seinen Brief geantwortet.", sourceObjective = "Trefft Euch mit Kalecgos am Ruhigen Ufer.", completion = "Es sind anscheinend noch mehr Magier angekommen!\n\nDas gibt mir Hoffnung.\n\nAethas wird sicher erleichtert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[83711] = { id = 83711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Eroberung", description = "Die Geschichten über Euer Können haben sogar mich erreicht, Held. Wenn Ihr so gut kämpft, wie man sagt, dann werdet Ihr mit einer meiner Kreationen sicher noch besser sein. Schreibt Euren Namen in die Geschichte. Kehrt zurück, wenn Ihr Euch als fähig und ehrenhaft erwiesen habt.", sourceObjective = "Erhaltet Eroberungspunkte in gewerteten Arenen und auf Schlachtfeldern.", sourceObjectiveStatus = "unverified-source-field" }
quests[83715] = { id = 83715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beanspruchtes Bergungsgut" }
quests[83716] = { id = 83716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter den Wurzeln", description = "Ich bin froh, dass es Euch gut geht, {name}. Ich habe vor kurzem erfahren, dass einige Luftritter in einem Lager in der Nähe der Stelle Schutz gesucht haben, wo das Luftschiff in der Luft gekapert wurde. \n\nWürdet Ihr nach ihnen sehen?", sourceObjective = "Findet das Lager, in dem die Luftritter untergebracht sind, im Westen von Azj-Kahet.", completion = "Wir tun unser Bestes mit dem, was wir haben. Die Besitzer dieses Lagers haben uns Zuflucht gewährt, aber hier gibt es kein Lächeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[83718] = { id = 83718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierentzug" }
quests[83719] = { id = 83719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das sind Chitinworte", description = "Nun, das ist mal ein interessantes Exemplar. Es scheint, dass der ursprüngliche Erschaffer dieser Kreatur grobe Fehler im Gleichgewicht zwischen dem genetischen Material gemacht hat. Da ist es kein Wunder, dass die Kreatur, der Ihr begegnet seid, eine Monstrosität war. Eine furchtbare Technik!\n\nMit dem richtigen Material könnte ich sie jedoch perfektionieren. Siesbarg hier wird unser Testobjekt sein. Vielleicht kann sein Aufstieg endlich die Aufmerksamkeit von irgendwem erregen, der für Beförderungen zuständig ist.", sourceObjective = "Sammelt genug nerubisches Chitin für Shalbas Experiment.", progress = "Chitinproben werden helfen, die Stärke von Siesbargs neuer Form zu definieren.", completion = "Ich werde dieses Chitin weise einsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83720] = { id = 83720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toxin ist die beste Medizin", description = "Nun, da wir genug Chitinproben gefunden haben, um die perfekte Rüstung zu erschaffen, brauchen wir das perfekte Gift. Seht mich nicht so an. Unsere Form sollte immer mächtig und in der Lage sein, sich zu verteidigen!\n\nIch werde beginnen, die neuen Panzervoraussetzungen für Siesbargs Aufstieg einzubinden, während Ihr sammelt, was ich brauche. Bedenkt, dass es sich speziell um nerubisches Gift handeln muss. Diese Käfer und Spinnen reichen diesmal einfach nicht aus.\n\nWo Ihr so was findet, wisst Ihr selbst am besten.", sourceObjective = "Sammelt genug nerubisches Gift für Shalbas Experiment.", progress = "Sehr gut! Genau danach habe ich gesucht.", completion = "Das wird ausreichen. Auf zur finalen Phase des Experiments!", sourceObjectiveStatus = "unverified-source-field" }
quests[83721] = { id = 83721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Ozean voll Blut", description = "Ausgezeichnet! Das Ende ist abzusehen! Aber auch wenn wir beinahe fertig sind, fehlt uns noch der wichtigste Teil dieser genetischen Gleichung: das Blut. Wir brauchen einen kleinen Ozean nerubisches Blut.\n\nDamit diese neue Form narrensicher ist, muss das Blut jedoch von den stärksten Nerubern überhaupt stammen. Ob Himmelsreißer oder Aufgestiegene spielt keine Rolle. Damit haben wir das beste genetische Material zur Verfügung.\n\nDie Art von Material, die Siesbarg verdient hat!", sourceObjective = "Sammelt genug nerubisches Blut für Shalbas Experiment.", progress = "Unser Experiment nähert sich seiner Vollendung, Überkrabbler.", completion = "Macht Euch bereit - Ihr dürft gleich wahre Perfektion bezeugen!", sourceObjectiveStatus = "unverified-source-field" }
quests[83722] = { id = 83722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegender Trostpreis", description = "Nun... das ist bedauerlich.\n\nMein Experiment ist offenbar fehlgeschlagen und Siesbarg musste den Preis dafür bezahlen. Dennoch bin ich optimistisch wegen der Zukunft, die mir vorbestimmt ist. Es ist nur eine Frage der Zeit, bis ich mein Verfahren perfektioniere. Und dann entwickle ich vielleicht meinen eigenen Aufstieg!\n\nAuch wenn seine körperliche Form nicht geworden ist, was ich vorgesehen hatte, scheint Siesbargs Verstand intakt zu sein. Bestimmt kann er noch nützlich sein. Nehmt ihn nur mit. Seine neue Form ist auf dem Schlachtfeld sicher besser aufgehoben als in meiner kleinen Werkstatt.", sourceObjective = "Nehmt Siesbarg von Shalba entgegen.", completion = "<Nach einem schweren Seufzen in Richtung von Shalba stellt sich Siesbarg begeistert an Eure Seite.>", sourceObjectiveStatus = "unverified-source-field" }
quests[83723] = { id = 83723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine helfende Hand", description = "Kalecgos' Hypothese, dass die Trümmer Dalarans die Teleportation über große Entfernungen behindern, scheint richtig zu sein.\n\nAn der Küste sind Magierportale aufgetaucht, aber niemand hat sie durchschritten. Wahrscheinlich sind in den Portalen Magier gefangen.\n\nVielleicht wird auch etwas Manahungriges, wie ein Teufelsjäger, durch die freigesetzte Macht von Dalaran hierhergelockt.\n\nWir müssen nachforschen. Die Magier der Kirin Tor könnten in Gefahr sein. Die Teufelsjäger sind ein akzeptables Risiko.\n\nLasst uns keine Zeit mehr verlieren.", sourceObjective = "Helft den Magiern, ihre Portale auf der Insel von Dorn zu verlassen.", completion = "Ich freue mich, dass die verstreuten Magier der Kirin Tor dem Ruf von Aethas folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83738] = { id = 83738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekannt bei der Weberin", description = "Vielen, vielen Dank an Euch von der Webermutter. \n\nKommt zurück ins Nest. Ich habe gute Waren für Euch. \n\nIch habe sie mit Netzen umwickelt und geschützt, also keine Sorge!", sourceObjective = "Sprecht mit Hüppi im Nest der Weberin.", completion = "Weiter so!\n\nDie Weberin bittet uns auch, Euch ihre \"Komplimente\" zu übermitteln, aber ich finde hier keine \"Komplimente\".\n\nVielleicht habe ich sie gegessen? Tut mir leid!", sourceObjectiveStatus = "unverified-source-field" }
quests[83739] = { id = 83739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekannt beim General", description = "Die Kunde von Euren Taten hat viele Akolythen des Generals erreicht!\n\nBesucht mich im Nest der Weberin. Wir haben etwas Besonderes für Euch vorbereitet!", sourceObjective = "Sprecht mit Aspirant Kiipka im Nest der Weberin.", completion = "Hier! Nehmt diese Geschenke als Tribut an Eure Stärke an!\n\nIgitith ik tak'na!", sourceObjectiveStatus = "unverified-source-field" }
quests[83740] = { id = 83740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bekannt beim Wesir", description = "Der Wesir hat mich gebeten, Euch zusätzliche Ressourcen für Eure Bemühungen bereitzustellen.\n\nKommt zum Nest der Weberin. Ich warte mit einem Paket auf Euch.", sourceObjective = "Sprecht mit Tulumun im Nest der Weberin.", completion = "Die Komplimente des Wesirs sollten für Euch ein mehr als ausreichendes Geschenk sein...\n\nAber ich schätze, diese Waren würden ohne seine Großzügigkeit einfach verloren gehen. Nehmt sie. Seid dankbar.\n\nUnd versucht, am Leben zu bleiben, Überkrabbler.", sourceObjectiveStatus = "unverified-source-field" }
quests[83742] = { id = 83742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruf zur Aufmerksamkeit", description = "Seid gegrüßt. General Anub'azal verlangt Eure sofortige Anwesenheit in der Belagerungsfeste. Er benötigt Eure Erfahrung bei der Untersuchung einer heiklen Angelegenheit.\n\nMehr darf ich hier nicht sagen. Sucht den General für weitere Informationen auf.\n\nFür Azj-Kahet.", sourceObjective = "Meldet Euch bei General Anub'azal in der Belagerungsfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[83743] = { id = 83743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkaner kalter Krieg", description = "Ein paar Magier sind gekommen, aber... Ich hatte erwartet, dass mehr dem Ruf von Aethas folgen würden.\n\nAber vielleicht war das Wunschdenken.\n\nWir brauchen mehr Hilfe, auch nach Euren und Kalecgos' Bemühungen in Trauerhöhe. Abgesehen von Kel'Thuzads Anhänger fanden wir unter der Beute der Kobolde nur ein paar mittelmäßige Artefakte.\n\nInzwischen gab es Berichte über mächtige magische Gegenstände, die ihre Runden durch Azj-Kahet machten, was bedeutet, dass die Neruber die Absturzstelle von Dalaran zuerst geplündert haben müssen!\n\nWir müssen diese Artefakte finden, bevor sie gegen uns eingesetzt werden.", sourceObjective = "Reist nach Azj-Kahet und trefft Euch mit Lady Jaina Prachtmeer.", completion = "Wir sind vielleicht zu spät gekommen, {name}. Für alle von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[83749] = { id = 83749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefen: Die Wasserwerke", description = "Was für eine Reise! Hättet Ihr gedacht, wie viel es hier in den Tiefen gibt?\n\nDiese Maschinenflüsterer haben mir von Problemen erzählt, die sie drüben an einem Ort haben, den sie die Wasserwerke nennen. Klingt, als würden die Kobolde wieder Ärger machen. Tiefer an diesem Ort lagern sie außerdem Schätze.\n\nWas sagt Ihr? Gehen wir auf ein Abenteuer und helfen diesen Leuten!", sourceObjective = "Schließt die Tiefe der Wasserwerke auf beliebigem Schwierigkeitsgrad ab.", completion = "Rein und raus. Ganz ohne Probleme!\n\nBis auf die Falle in dieser Kiste da vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[83750] = { id = 83750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Zuramat der Vernichter", sourceObjective = "Findet Zuramat den Vernichter und sammelt seinen Seelenstein in Azj'Kahet.", sourceObjectiveStatus = "unverified-source-field" }
quests[83752] = { id = 83752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohungen von Zekvir", description = "Jemand beobachtet uns, {name}. Sie haben diese Kiste für uns hier hinterlassen.\n\nGebt Bescheid, wenn Ihr bereit seid. Ich werde die Falle auslösen und dann sehen wir, was hier wirklich vor sich geht.", sourceObjective = "Sprecht mit Brann Bronzebart, um die seltsame Kiste zu untersuchen.", completion = "Nun, ich werde mich von einer kleinen Bedrohung nicht vom Forschen abhalten lassen. Wie es aussieht, muss ich weitere Untersuchungen anstellen. \n\nIch bin sicher, dass wir uns sehr bald wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83753] = { id = 83753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanonenkarma", description = "Es wird ernst, {name}! Diese Piratenschläger haben eine Kanone und drohen, uns damit in die Luft zu jagen!\n\nAber das könnte auch eine Chance sein.\n\nWenn Ihr es schafft, den Affen loszuwerden, der die Kanone abfeuert, können wir sie uns vielleicht selbst unter den Nagel reißen und es ihnen heimzahlen!", sourceObjective = "Angriff der Bilgeratte unterbrochen und Kanonenmeister Jin'chu eliminiert.", progress = "Sagt mir lieber, dass die Piraten alle weg sind!", completion = "Das hätte ich auch nicht besser hinbekommen. Ihr solltet das mit einer Kaja'Cola feiern.", sourceObjectiveStatus = "unverified-source-field" }
quests[83755] = { id = 83755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefen: Nachtsturzsanktum", description = "Schön, Euch wiederzusehen! Ich hatte einige Schwierigkeiten, seit wir uns zuletzt getroffen haben.\n\nIrgendein Neruber namens \"Zekvir\" verlangt, die Expedition dieses Land nicht weiter erforscht. Ihr wisst, was das heißt. Wir müssen noch viel mehr erkunden!\n\nDie Kultisten vom Orden der Nacht haben vielleicht Informationen über Zekvir. Gehen wir zum Nachtsturzsanktum und sehen, was wir herausfinden können.", sourceObjective = "Findet Hinweise über Zekvir im Nachtsturzsanktum und schließt die Tiefe auf beliebigem Schwierigkeitsgrad ab.", completion = "Hrm... Also dieser Zekvir scheint an vielen Orten, die wir erkunden, im Dunkeln zu lauern. Er könnte sogar in der Lage sein, Leute zu ermächtigen!\n\nWir müssen tiefer gehen, um das herauszufinden. Überlasst mir die Laufarbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[83758] = { id = 83758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Fungusphantasterei", description = "Wir haben weitere Berichte über Fungianer, die an den Ort zurückkehren, den wir \"Fungusphantasterei\" nennen.\n\nErkundet die Höhle und eliminiert dort jegliche Bedrohung, die Euch begegnet.", sourceObjective = "Schließt die Tiefe der Fungusphantasterei auf beliebigem Schwierigkeitsgrad ab.", completion = "Danke, dass Ihr Euch um die Fungianer gekümmert habt. Eines Tages werden sie nicht mehr so eine Fehlfunktion im System sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[83759] = { id = 83759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Kriegvals Kräftigung", description = "HILFE GESUCHT\n\nKriegvals Kräftigung ist von Kobolden überrannt worden! Diese einst heilige Ruhestätte der Irdenen muss wieder aufgebaut werden.", sourceObjective = "Schließt die Tiefe Kriegvals Kräftigung auf beliebigem Schwierigkeitsgrad ab.", progress = "Untersucht Ihr Kriegvals Kräftigung?", completion = "Kriegvals Kräftigung ist ein heiliger Ort für unser Volk. Danke, dass Ihr uns beim Wiederaufbau helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[83761] = { id = 83761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefen: Die Tiefenfestung", description = "Wer hätte gedacht, dass ich es mir in der Höhle eines Nerubers gemütlich machen könnte!\n\nEs gibt einen Fiesling namens Zekvir, der Leute bedroht, die die Insel erforschen wollen. Ich habe die Weberin um jede Information gebeten, die sie hat.\n\nAnscheinend gibt es einen Ort, der Tiefenfestung genannt wird und Aufzeichnungen über ihn haben könnte. Lasst uns dort nachsehen, was wir finden können!", sourceObjective = "Findet Informationen über Zekvir in der Tiefenfestung und schließt die Tiefe auf beliebigem Schwierigkeitsgrad ab.", completion = "Zekvir ist ein Agent von Xal'atath! Und er versucht, alle Erinnerungen an Azeroth zu zerstören, die er findet.\n\nDas macht unsere Aufgabe, alles zu erkunden, wichtiger denn je, {name}. Wir werden nicht aufgeben, nicht einmal, wenn Xal'ataths Kröte hinter uns her ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[83762] = { id = 83762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kritische Masse", description = "Genau das hatte ich befürchtet.\n\nThalen Sangwebers Aufzeichnungen über die Manabombe, die er für die Zerstörung von Theramore entwickelt hatte, wurden in Dalaran streng bewacht. Nur wenige wussten davon.\n\nIch war der Meinung, dass sie vernichtet werden sollten. Aber andere argumentierten, dass wir sie brauchen würden, um eine solche Bombe zu entschärfen, wenn je wieder eine hergestellt würde.\n\nUnd jetzt sind diese Aufzeichnungen sowohl das Problem als auch die Lösung.\n\nZum Glück habe ich sie gelesen, {name}. Ich werde Euch beim Entschärfen der Manabombe helfen.", sourceObjective = "Helft Lady Jaina Prachtmeer, die Manabombe in der Atemgrube zu entschärfen.", completion = "Mein Vertrauen in Euch wird nie enttäuscht. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[83763] = { id = 83763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbe bewahren", description = "Die größte Bedrohung wurde eingedämmt, {name}, aber ich glaube, dass es hier in Azj-Kahet noch andere Artefakte gibt, die für unser Erbe wichtig sind. Gute und schlechte.\n\nSie sind zwar immer noch gefährlich, aber ihr Wissen kann uns auf lange Sicht von Nutzen sein. Und wir dürfen nicht zulassen, dass die Neruber von dem profitieren, was sie und Xal'atath Dalaran angetan haben.\n\nLasst keine dunklen Ecken hier in der Atemgrube unerforscht, {name}.", sourceObjective = "Sammelt wertvolle Gegenstände in der Atemgrube.", progress = "Wir müssen so viel vom Erbe der Kirin Tor zurückholen, wie wir können.", completion = "Was habt Ihr gefunden?\n\nDie Aufzeichnungen von Thalen Sangweber.\n\nDer Rest wird sicher aufbewahrt, aber diese Aufzeichnungen...\n\nIch werde mich selbst um ihre Vernichtung kümmern.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[83764] = { id = 83764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu mächtig, zu gefährlich", description = "Einige der Relikte, die die Neruber jetzt besitzen, waren in speziell entworfenen Eindämmungskammern in Dalaran untergebracht. Das zeigt, wie gefährlich und mächtig sie sind.\n\nDa es diese Kammern nicht mehr gibt, bleibt uns nichts anderes übrig, als sie zu zerstören.\n\nIm Nachhinein scheint es ein großer Fehler gewesen zu sein, so viele mächtige Artefakte an einem Ort zusammenzubringen, selbst wenn dieser Ort Dalaran war.\n\nIch würde diese Aufgabe niemandem sonst anvertrauen, {name}. Findet und zerstört diese Artefakte.", sourceObjective = "Findet gefährliche Artefakte, die in der Atemgrube verstreut sind, und zerstört sie.", completion = "Vielen Dank, {name}.\n\nIn Zukunft müssen die Kirin Tor bessere Wege finden, um magische Artefakte zu untersuchen und zu schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83766] = { id = 83766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Terrorschacht", description = "Zwei Dinge sind schlecht fürs Geschäft: ernstzunehmende Konkurrenz und die Höhlen des Terrorschachts. Wir brauchen jemanden, der sich um Letztere kümmert!\n\nIrgendwas Schlimmes geht hier vor sich. Wir haben einen Haufen Arbeiter in diesen Höhlen verloren.\n\nKümmert Euch um die Bedrohung, damit unser Geschäft weiter floriert!", sourceObjective = "Schließt die Tiefe des Terrorschachts auf beliebigem Schwierigkeitsgrad ab.", progress = "Ich bin froh, dass ich endlich jemanden gefunden habe, der sich den Terrorschacht ansieht!", completion = "Ihr habt Euch um die Spinnen im Terrorschacht gekümmert? Toll!\n\n Ich werde mir einen besseren Namen für diesen Ort ausdenken. \"Terrorschacht\" ist nicht einprägsam genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[83767] = { id = 83767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Der Krater", description = "Wir haben Berichte über einen Haufen Kobyss erhalten, die sich in einer Höhle namens Erdsturz versammelt haben. Es gibt Befürchtungen, dass sie die kleineren Küstendörfer angreifen wollen, sobald sie die Gelegenheit dazu haben.\n\nEs gibt eine saftige Belohnung für jeden, der in Erdsturz eindringt und vereitelt, was auch immer sie vorhaben!", sourceObjective = "Schließt die Tiefe des Kraters auf beliebigem Schwierigkeitsgrad ab.", completion = "Danke für die Hilfe. In der aktuellen Situation ist es schwer, allen in Heilsturz zu helfen.\n\nHoffentlich werden es sich die Kobyss zweimal überlegen, ob sie weiter angreifen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83768] = { id = 83768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Die Schwärmerbresche", description = "Wir brauchen jeden, der ein Schwert schwingen oder einen Zauber schleudern kann!\n\nDie Neruber führen im Schatten unserer einst schönen Aegismauer üble Rituale durch. Es heißt, dass ein dunkler Tempel, der ihren verfluchten Göttern geweiht ist, unter der Erde ruht. \n\nJemand muss diesen abscheulichen Ort erforschen und ihren Machenschaften ein Ende setzen.", sourceObjective = "Schließt die Tiefe der Schwärmerbresche auf beliebigem Schwierigkeitsgrad ab.", completion = "Ihr habt die Schwärmerbresche überlebt? Ich kenne viele Lampenanzünder, die sich von diesem üblen Ort zurückziehen mussten.\n\nIhr habt dieses Land sicherer gemacht. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[83769] = { id = 83769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Mykomantenhöhle", description = "Gewürzhilfe benötigt!\n\nFungianer haben in der Mykomantenhöhle Gewürzkisten geplündert, die für Lorels Kreuzung bestimmt waren. Jemand muss in diese Höhlen gehen und die Fungianer-Bedrohung zurückschlagen! \n\nWird gut bezahlt.", sourceObjective = "Schließt die Tiefe der Mykomantenhöhle auf beliebigem Schwierigkeitsgrad ab.", completion = "Ich habe gehört, dass die Fungianer vor kurzem von jemandem verringert worden sind. Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[83770] = { id = 83770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Spiralgewebe", description = "Viele von uns Überlebenden haben Geschichten über das Spiralgewebe gehört. Es scheint ein Ort zu sein, an dem die Neruber große Militäroperationen durchführen.\n\nDen Kampf gegen sie aufzunehmen, könnte die Kriegspläne der Neruber ernsthaft durchkreuzen.", sourceObjective = "Schließt die Tiefe des Spiralgewebes auf beliebigem Schwierigkeitsgrad ab.", progress = "Ihr geht in das Herz einer nerubischen Militärbasis. Seid vorsichtig.", completion = "Ihr habt es geschafft! Das sollte unseren Truppen an der Oberfläche eine kleine Verschnaufpause verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83771] = { id = 83771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Tiefenforschers: Tak-Rethan-Abgrund", description = "ANWEISUNGEN DER WEBERIN\n\nDer Tak-Rethan-Abgrund wird weiterhin von Unruhen und Ärger heimgesucht.\n\nJemand muss die Bedrohung im Zaum halten, bevor unsere Pläne gefährdet werden.", sourceObjective = "Schließt die Tiefe des Tak-Rethan-Abgrunds auf beliebigem Schwierigkeitsgrad ab.", progress = "Untersucht Ihr die Kobyss?", completion = "Gute Arbeit. Ich gebe Euch Bescheid, wenn ich noch mehr Kobyss-Reinigungen brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[83773] = { id = 83773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ade, Stadt der Magie", description = "Nicht alle Probleme der Kirin Tor können an einem Tag gelöst werden.\n\nAber eins können wir tun, und zwar diejenigen ehren, die wir verloren haben. Nachdem wir mit allen hier gesprochen haben, haben wir eine Zeremonie für die Gefallenen vorbereitet... und für Dalaran.\n\nEs wäre uns eine Ehre, wenn Ihr Euch uns anschließen würdet, um unseren Kameraden von den Kirin Tor zu gedenken.", sourceObjective = "Legt die von den Überlebenden Dalarans mitgebrachten Erinnerungsstücke in die Boote am Ruhigen Ufer.", progress = "Ich bin mir sicher, dass die Zukunft der Kirin Tor keine weitere schwebende Festung im Himmel ist.\n\nNein, welchen Weg die Kirin Tor auch immer einschlagen werden, er wird hier in Azeroth fest verwurzelt sein, bei den Menschen, denen sie dienen.", completion = "Ich werde hier bei Euch allen bleiben und helfen, wo ich kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[83775] = { id = 83775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Wachstum II", sourceObjective = "Ihr habt Euch beträchtlich weiterentwickelt, doch möglicherweise bedürft Ihr meiner Dienste. Eternus hat eine Ausgabe von Bronze an erfahrene Zeitläuferinnen und Zeitläufer bewilligt. Ich kann Eure Ausrüstung ermächtigen, falls nötig.", sourceObjectiveStatus = "unverified-source-field" }
quests[83776] = { id = 83776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Wachstum III", sourceObjective = "Es fühlt sich an, als hätten wir uns gerade erst gesprochen. Ich habe weitere Bronze für Euch. Ihr könnt sie nach eigenem Belieben einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[83777] = { id = 83777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Wachstum IV", sourceObjective = "Zeitläufer! Ihr habt es so weit gebracht. Bedeutet dies das Ende Eurer Reise in dieser Zeitlinie oder ist es lediglich deren Anfang? Ich kann Eure Ausrüstung weiterhin auf neue Höhen heben. Ihr könnt Eure Bronze aber natürlich auch bei den anderen Ewigen ausgeben. Eure Wahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[83793] = { id = 83793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Jinyu", progress = "Unsere Leute sind zu ruhelos, um sich dem Fluss des Wassers zu fügen. Helft unserem Dorf, auf dass wir uns wieder der Strömung hingeben können.", completion = "Vielen Dank für Eure Spenden." }
quests[83794] = { id = 83794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triefende Feierkiste", description = "<Die Kiste ist klatschnass und riecht ein wenig nach Fisch, scheint aber ansonsten luftdicht versiegelt zu sein. Alyx würde sich über die Vorräte freuen.>", sourceObjective = "Bringt die triefende Feierkiste zu Alyx zurück.", progress = "Oh, ich habe so viel zu tun. Doch womit kann ich Euch helfen?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nAber... wieso riecht die so nach Fisch? Ach, das will ich gar nicht wissen.\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie mir bitte auch her.", sourceObjectiveStatus = "unverified-source-field" }
quests[83795] = { id = 83795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft den Ho-zen", progress = "Ihr seid Freund der Ho-zen, Nappel? Dann her mit den Klingelings!", completion = "Juchhu! Seid echt mächtig potzig, Nappel!" }
quests[83825] = { id = 83825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restaurierung einer großartigen Fabel", description = "Es war entsetzlich! Mein Buch wurde zerschreddert und die Seiten stoben nur so durch die Luft!\n\nIch habe gesehen, wie einige an den Sandteufeln hängen blieben, die sich in den Tunnel davon machten. Andere klebten an den Abenteurern fest, die sich aufmachten, um die großen Monster in Tanaris zu bekämpfen. Und ein Teil wurde hier verstreut. Vielleicht könnte Euer riesiges Vogeldings helfen, sie zu finden?\n\nBitte helft mir, die Seiten wiederzufinden, damit ich mein Buch wieder zusammenflicken kann!\n\nOh und nehmt Euch vor diesem dubiosen Cravitz Lorent in acht. Er verkauft unter der Bühne des Moderauschs neue Exemplare für Einhundert Gold. Raubrittertum!", sourceObjective = "Bringt ein Exemplar von \"Die Grünen Hügel des Schlingendorntals\" zu Raenie Zischmoor vor den Höhlen der Zeit.", progress = "Habt Ihr alle Seiten gefunden und mein Buch reparieren können?", completion = "Oh, es sieht aus wie neu! Ihr habt ganze Arbeit geleistet.\n\nAlyx sagte, dass ich Euch das hier für Eure Hilfe geben soll! Und mir wäre sehr daran gelegen, wenn wir die Sache für uns behalten könnten. Meine Schwester Addie muss ja nicht davon erfahren, dass ich Ihr Geschenk beinahe verloren hätte.", sourceObjectiveStatus = "unverified-source-field" }
